let activeSettingsHelp = null;

function _appendSettingsHelpText(parent, tagName, className, text) {
    const el = document.createElement(tagName);
    if (className) el.className = className;
    el.textContent = text;
    parent.appendChild(el);
    return el;
}

function _buildSettingsHelpPopover(data) {
    const panel = document.createElement('div');
    panel.className = 'settings-help-popover';
    panel.setAttribute('role', 'dialog');
    panel.setAttribute('aria-modal', 'false');
    panel.setAttribute('tabindex', '-1');

    const head = document.createElement('div');
    head.className = 'settings-help-popover-head';
    const titleWrap = document.createElement('div');
    _appendSettingsHelpText(titleWrap, 'div', 'settings-help-popover-kicker', data.kicker || 'Hilfe');
    const title = _appendSettingsHelpText(titleWrap, 'h3', 'settings-help-popover-title', data.title || 'Hilfe');
    const titleId = `settingsHelpTitle_${Date.now()}`;
    title.id = titleId;
    panel.setAttribute('aria-labelledby', titleId);
    head.appendChild(titleWrap);

    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'settings-help-close-btn';
    closeBtn.setAttribute('aria-label', 'Hilfe schliessen');
    closeBtn.textContent = '×';
    closeBtn.addEventListener('click', closeSettingsHelp);
    head.appendChild(closeBtn);
    panel.appendChild(head);

    if (data.intro) _appendSettingsHelpText(panel, 'p', 'settings-help-intro', data.intro);

    const list = document.createElement('dl');
    list.className = 'settings-help-list';
    (data.items || []).forEach(item => {
        _appendSettingsHelpText(list, 'dt', '', item.term);
        _appendSettingsHelpText(list, 'dd', '', item.text);
    });
    panel.appendChild(list);
    return panel;
}

function _positionSettingsHelpPopover(panel, anchor) {
    if (!panel || !anchor) return;
    const margin = 12;
    const rect = anchor.getBoundingClientRect();
    const width = panel.offsetWidth;
    const height = panel.offsetHeight;
    let left = Math.min(window.innerWidth - width - margin, Math.max(margin, rect.right - width));
    let top = rect.bottom + 8;

    if (top + height > window.innerHeight - margin) {
        top = rect.top - height - 8;
    }
    if (top < margin || window.innerWidth <= 540) {
        left = margin;
        top = Math.min(window.innerHeight - height - margin, Math.max(margin, rect.bottom + 8));
        if (top + height > window.innerHeight - margin) top = margin;
    }

    panel.style.left = `${Math.round(left)}px`;
    panel.style.top = `${Math.round(top)}px`;
}

function closeSettingsHelp() {
    if (!activeSettingsHelp) return;
    const { panel, anchor, onOutside, onKey, onReposition } = activeSettingsHelp;
    if (anchor) anchor.setAttribute('aria-expanded', 'false');
    if (panel && panel.parentNode) panel.parentNode.removeChild(panel);
    document.removeEventListener('pointerdown', onOutside, true);
    document.removeEventListener('keydown', onKey, true);
    window.removeEventListener('resize', onReposition);
    document.removeEventListener('scroll', onReposition, true);
    activeSettingsHelp = null;
}

function showSettingsHelp(helpKey, event) {
    if (event) {
        event.preventDefault();
        event.stopPropagation();
    }

    const data = SETTINGS_HELP_CONTENT[helpKey];
    const anchor = event?.currentTarget || null;
    if (!data) return;

    if (activeSettingsHelp?.key === helpKey && activeSettingsHelp?.anchor === anchor) {
        closeSettingsHelp();
        return;
    }

    closeSettingsHelp();

    const panel = _buildSettingsHelpPopover(data);
    document.body.appendChild(panel);
    if (anchor) anchor.setAttribute('aria-expanded', 'true');

    const onReposition = () => _positionSettingsHelpPopover(panel, anchor || panel);
    requestAnimationFrame(onReposition);

    const onOutside = (e) => {
        if (panel.contains(e.target) || (anchor && anchor.contains(e.target))) return;
        closeSettingsHelp();
    };
    const onKey = (e) => {
        if (e.key === 'Escape') closeSettingsHelp();
    };

    activeSettingsHelp = { key: helpKey, panel, anchor, onOutside, onKey, onReposition };
    document.addEventListener('pointerdown', onOutside, true);
    document.addEventListener('keydown', onKey, true);
    window.addEventListener('resize', onReposition);
    document.addEventListener('scroll', onReposition, true);

    panel.focus({ preventScroll: true });
}

window.showSettingsHelp = showSettingsHelp;
window.closeSettingsHelp = closeSettingsHelp;

function setTheme(mode) {
    const wasNavcom = document.body.classList.contains('theme-navcom');
    document.body.classList.remove('theme-retro', 'theme-navcom', 'theme-ops1940');
    const lblClassic = document.getElementById('lbl-classic');
    const lblRetro = document.getElementById('lbl-retro');
    const lblNavcom = document.getElementById('lbl-navcom');
    const lblOps1940 = document.getElementById('lbl-ops1940');
    const slider = document.getElementById('themeSlider');

    if (lblClassic) lblClassic.style.color = '#888';
    if (lblRetro) lblRetro.style.color = '#888';
    if (lblNavcom) lblNavcom.style.color = '#888';
    if (lblOps1940) lblOps1940.style.color = '#888';

    if (mode === 'retro') {
        document.body.classList.add('theme-retro');
        localStorage.setItem('ga_theme', 'retro');
        if (slider) slider.value = 1;
        if (lblRetro) lblRetro.style.color = '#d93829';
    } else if (mode === 'navcom') {
        document.body.classList.add('theme-navcom', 'theme-retro');
        localStorage.setItem('ga_theme', 'navcom');
        if (slider) slider.value = 2;
        if (lblNavcom) lblNavcom.style.color = '#33ff33';
    } else if (mode === 'ops1940') {
        document.body.classList.add('theme-ops1940');
        localStorage.setItem('ga_theme', 'ops1940');
        if (slider) slider.value = 3;
        if (lblOps1940) lblOps1940.style.color = '#d0a44f';
    } else {
        localStorage.setItem('ga_theme', 'classic');
        if (slider) slider.value = 0;
        if (lblClassic) lblClassic.style.color = '#4da6ff';
    }
    applySavedPanelTheme();
    updateDynamicColors();
    refreshAllDrums();
    syncGPSWithTheme(mode, wasNavcom);
    if (typeof updateOps1940Panel === 'function') updateOps1940Panel();

    // --- NEU: Wetter-Widgets beim Theme-Wechsel sofort neu rendern ---
    if (typeof currentStartICAO !== 'undefined' && currentStartICAO) {
        const depP = routeWaypoints && routeWaypoints.length > 0 ? routeWaypoints[0] : null;
        loadMetarWidget(currentStartICAO, 'metarContainerDep', depP?.lat, depP?.lng || depP?.lon);
    }
    if (typeof currentDestICAO !== 'undefined' && currentDestICAO) {
        const isPOI = document.getElementById("destRwyContainer")?.style.display === "none";
        const destP = routeWaypoints && routeWaypoints.length > 1 ? routeWaypoints[routeWaypoints.length - 1] : null;
        loadMetarWidget(isPOI ? null : currentDestICAO, 'metarContainerDest', destP?.lat, destP?.lng || destP?.lon);
    }
}

function syncGPSWithTheme(newMode, wasNavcom) {
    const fp = document.querySelector('.flightplan-container');
    const mod = document.getElementById('kln90bModule');
    if (newMode === 'navcom') {
        if (gpsState.visible) {
            if (mod) mod.style.display = 'flex';
            if (fp) fp.style.display = 'none';
            renderGPS();
        } else {
            if (mod) mod.style.display = 'none';
            if (fp) fp.style.display = '';
        }
    } else {
        if (mod) mod.style.display = 'none';
        if (fp) fp.style.display = '';
    }
}

function syncToNavCom(radioId, value) {
    const el = document.getElementById(radioId);
    if (!el) return;
    if (el.tagName === 'INPUT' || el.tagName === 'SELECT') {
        el.value = value;
    } else {
        el.innerText = value;
    }
}

function applyNavComPreset(t, g, s, n, btnElement) {
    if (arguments.length === 1 && typeof t === 'string') {
        applyAircraftPresetSlot(t);
        return;
    }
    applyPreset(t, g, s, n);
    document.getElementById('tasSlider').value = t;
    document.getElementById('gphSlider').value = g;
    handleSliderChange('tas', t);
    handleSliderChange('gph', g);
    syncToNavCom('tasRadioDisplay', t);
    syncToNavCom('gphRadioDisplay', g.toString().padStart(2, '0'));
    updateNavComAircraftButtons();
    saveAudioButtonStates();
}

function toggleNavComAI(btnElement) {
    const aiToggleBtn = document.getElementById('aiToggle');
    if (aiToggleBtn) {
        aiToggleBtn.checked = !aiToggleBtn.checked;
        saveAiToggle();
        if (aiToggleBtn.checked) btnElement.classList.add('active');
        else btnElement.classList.remove('active');
        saveAudioButtonStates();
    }
}

function swapDepDest() {
    const depRadio = document.getElementById('startLocRadio');
    const destRadio = document.getElementById('destLocRadio');
    const depClassic = document.getElementById('startLoc');
    const destClassic = document.getElementById('destLoc');
    if (!depRadio || !destRadio) return;

    if (!destRadio.value || !destRadio.value.trim()) {
        destRadio.value = depRadio.value;
        if (destClassic) destClassic.value = depRadio.value;
        const targetTypeSel = document.getElementById('targetType');
        if (targetTypeSel) {
            targetTypeSel.value = 'poi';
            targetTypeSel.dispatchEvent(new Event('change'));
        }
        updateMapFromInputs();
        return;
    }

    const tempVal = depRadio.value;
    depRadio.value = destRadio.value;
    destRadio.value = tempVal;
    if (depClassic) depClassic.value = depRadio.value;
    if (destClassic) destClassic.value = destRadio.value;
    updateMapFromInputs();
}

function cycleRadioOption(selectId) {
    const selectEl = document.getElementById(selectId);
    if (!selectEl) return;
    let nextIndex = selectEl.selectedIndex + 1;
    if (nextIndex >= selectEl.options.length) nextIndex = 0;
    selectEl.selectedIndex = nextIndex;
    selectEl.dispatchEvent(new Event('change'));
}

const MISSION_PICKER_STORAGE_KEY = 'ga_mission_picker_mode';
const SAR_HELI_PROFILE_ID = 'sar_heli';
const SAR_HELI_RECOVERABLE_INCIDENT_IDS = Object.freeze([
    'missing_hiker',
    'fallen_climber',
    'missing_kayaker',
    'angler_missing',
    'small_boat_overdue',
    'vehicle_off_road',
    'road_collision'
]);

function missionIsSarHeliProfileId(profileId = '') {
    return String(profileId || '').trim().toLowerCase() === SAR_HELI_PROFILE_ID;
}

function missionSarHeliSpecFromMission(mission = null) {
    const explicitMission = !!(mission && typeof mission === 'object');
    const md = mission && typeof mission === 'object'
        ? mission
        : ((typeof currentMissionData !== 'undefined' && currentMissionData) ? currentMissionData : null);
    if (!md || typeof md !== 'object') return null;
    const contract = md.missionContract && typeof md.missionContract === 'object'
        ? md.missionContract
        : ((!explicitMission && typeof window !== 'undefined' && window.activeMissionContract && typeof window.activeMissionContract === 'object')
            ? window.activeMissionContract
            : null);
    return (md.sarHeli && typeof md.sarHeli === 'object')
        ? md.sarHeli
        : ((contract?.sarHeli && typeof contract.sarHeli === 'object') ? contract.sarHeli : null);
}

function missionIsSarHeliMission(mission = null) {
    const explicitMission = !!(mission && typeof mission === 'object');
    const md = mission && typeof mission === 'object'
        ? mission
        : ((typeof currentMissionData !== 'undefined' && currentMissionData) ? currentMissionData : null);
    const spec = missionSarHeliSpecFromMission(md);
    if (spec?.enabled === true) return true;
    const contract = md?.missionContract || (!explicitMission && typeof window !== 'undefined' ? window.activeMissionContract : null) || null;
    return [
        md?._appliedProfile,
        md?._requestedProfile,
        md?.profileId,
        md?.missionPicker?.profile,
        md?.missionPlanV2?.picker?.profile,
        md?.missionPlanV4?.picker?.profile,
        contract?.appliedProfileId,
        contract?.requestedProfileId
    ].some(missionIsSarHeliProfileId);
}

function missionSarHeliIncidentIdsForCategory(category = '', targetLabel = '') {
    const key = missionSarIncidentCategoryKey(category, targetLabel);
    const target = String(targetLabel || '').trim().toLowerCase();
    const matrix = {
        water: ['missing_kayaker', 'angler_missing', 'small_boat_overdue'],
        road: ['vehicle_off_road', 'road_collision', 'missing_hiker'],
        forest: ['missing_hiker', 'fallen_climber', 'vehicle_off_road'],
        mountain: ['fallen_climber', 'missing_hiker'],
        land: ['missing_hiker', 'fallen_climber', 'vehicle_off_road']
    };
    const ids = matrix[key] || matrix.land;
    if (key === 'road' && /(kreuzung|intersection|junction|abzweig|zufahrt|auffahrt|ausfahrt|anschluss)/.test(target)) {
        return ['road_collision', 'vehicle_off_road'];
    }
    return ids.filter(id => SAR_HELI_RECOVERABLE_INCIDENT_IDS.includes(id));
}

function missionSarHeliInitialProgress() {
    return {
        schema: 'sarHeliProgress.v1',
        status: 'enroute_search',
        targetConfirmed: false,
        markerSpawned: false,
        targetAreaEnteredAt: 0,
        holdReadyAnnounced: false,
        holdStartedAt: 0,
        holdSec: 0,
        patientLoaded: false,
        patientLoadedAt: 0,
        hospitalReached: false,
        readyToClose: false,
        lastUpdatedAt: Date.now()
    };
}

function missionSarHeliBuildRouteWaypoints({
    start = null,
    target = null,
    hospital = null,
    mission = null,
    startName = '',
    startIcao = '',
    targetName = '',
    targetTerrainFt = null
} = {}) {
    const md = (mission && typeof mission === 'object') ? mission : null;
    const spec = missionSarHeliSpecFromMission(md) || md?.sarHeli || null;
    const hospitalRef = hospital || spec?.hospitalRef || null;
    const targetRef = target || spec?.targetRef || null;
    const startLat = Number(start?.lat);
    const startLon = Number(start?.lon ?? start?.lng);
    const targetLat = Number(targetRef?.lat);
    const targetLon = Number(targetRef?.lon ?? targetRef?.lng);
    const hospitalLat = Number(hospitalRef?.lat);
    const hospitalLon = Number(hospitalRef?.lon ?? hospitalRef?.lng);
    if (![startLat, startLon, targetLat, targetLon, hospitalLat, hospitalLon].every(Number.isFinite)) return [];

    const terrainFt = Number(targetTerrainFt ?? targetRef?.terrainFt ?? md?.poiTerrainFt ?? md?.targetAltFt);
    const recoveryHoldSec = Math.max(20, Number(spec?.recovery?.stableHoldSec || 20));
    const startLabel = String(startName || start?.icao || startIcao || start?.n || start?.name || md?.start || 'Start').trim();
    const targetLabel = String(targetName || targetRef?.name || md?.poiName || md?.targetName || 'SAR').trim();
    const hospitalName = String(hospitalRef?.name || hospitalRef?.icao || 'Krankenhaus-Helipad').trim();
    return [
        { lat: startLat, lng: startLon, name: startLabel },
        {
            lat: targetLat,
            lng: targetLon,
            name: `🚁 Fundstelle ${targetLabel}`,
            isPOI: true,
            isSarHeliIncident: true,
            altFt: Number.isFinite(terrainFt) ? Math.max(0, Math.round(terrainFt)) : null,
            simHoldSec: recoveryHoldSec + 2,
            simHoldAction: 'sar_heli_recovery'
        },
        {
            lat: hospitalLat,
            lng: hospitalLon,
            name: `🏥 ${hospitalName}`,
            isSarHeliHospital: true,
            icao: String(hospitalRef?.icao || 'HOSP').toUpperCase(),
            altFt: Number.isFinite(Number(hospitalRef?.elevation)) ? Math.round(Number(hospitalRef.elevation)) : null
        }
    ];
}

