function normalizeMissionType(raw = '', isPOI = false) {
    const t = String(raw || '').trim().toLowerCase();
    if (t === 'bush') return 'bush';
    if (t === 'poi') return 'poi';
    if (t === 'apt') return 'apt';
    return isPOI ? 'poi' : 'apt';
}

