function compactOpsLabel(text, maxLength = 13) {
    const normalized = String(text || '')
        .replace(/\s*\([^)]*\)/g, '')
        .replace(/\s+/g, ' ')
        .trim();
    if (!normalized) return '----';
    return normalized.length > maxLength ? `${normalized.slice(0, maxLength - 1)}.` : normalized;
}

