function _charterNormalizeText(value = '') {
    return String(value || '')
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/\s+/g, ' ')
        .trim();
}

function _charterRoleLooksGeneric(role = '') {
    const s = _charterNormalizeText(role);
    return !s || /^(passagier|passagierin|gast|chartergast|hauptgast|hauptpassagier|hauptpassagierin|begleitperson|geschaeftsreisender|geschaftsreisender|geschaeftsreisende|geschaftsreisende|reisender|reisende|kunde|kundin|pax)$/i.test(s);
}

function _charterNameLooksGeneric(name = '') {
    const s = _charterNormalizeText(name);
    return !s || /^(passagier|passagierin|gast|kunde|kundin|chartergast|pax|reisender|reisende)$/i.test(s);
}

function _charterTemplateContext(passenger = null, context = {}) {
    const name = String(passenger?.name || '').trim() || 'unser Chartergast';
    const firstName = name.split(/\s+/).filter(Boolean)[0] || name;
    const role = String(passenger?.role || '').trim() || 'Chartergast';
    const startName = String(context.startName || context.homeName || context.originName || 'Startplatz').trim() || 'Startplatz';
    const targetName = String(context.targetName || context.destName || context.destinationName || 'Zielflugplatz').trim() || 'Zielflugplatz';
    return { name, firstName, role, startName, targetName };
}

function _applyCharterTemplate(text = '', passenger = null, context = {}) {
    const ctx = _charterTemplateContext(passenger, context);
    return String(text || '')
        .replace(/\{name\}/g, ctx.name)
        .replace(/\{firstName\}/g, ctx.firstName)
        .replace(/\{role\}/g, ctx.role)
        .replace(/\{startName\}/g, ctx.startName)
        .replace(/\{targetName\}/g, ctx.targetName)
        .replace(/\s+/g, ' ')
        .trim();
}

function _charterFallbackStorySeed(passenger = null) {
    const role = _charterNormalizeText(passenger?.role || '');
    if (/anwalt|notar|jurist|recht/.test(role)) {
        return '{name} reist am Zielort zu einem juristischen Termin; die Unterlagen liegen im Handgepäck und sollen nach der Landung sauber an den lokalen Kontakt übergeben werden.';
    }
    if (/bau|architekt|sachverstaendig|sachverstandig|gutachter|immobil|bewert/.test(role)) {
        return '{name} wird am Zielort zu einer fachlichen Begehung erwartet; Pläne, Fotos und Prüfliste bleiben griffbereit, während der lokale Kontakt am Flugplatz übernimmt.';
    }
    if (/event|messe|kongress|referent|vortrag/.test(role)) {
        return '{name} wird am Zielort von der Veranstaltungscrew erwartet; nach der Landung geht es mit Rollkoffer und Unterlagen weiter zum Aufbau oder Vortrag.';
    }
    if (/service|techniker|werft|avionik|mechaniker/.test(role)) {
        return '{name} wird am Zielplatz von einem Werkstatt- oder Servicekontakt abgeholt; Werkzeug und Diagnoseunterlagen bleiben klein verpackt für den geplanten Einsatz vor Ort.';
    }
    if (/projekt|berater|unternehmer|manager|kunde|produktion|leiter/.test(role)) {
        return '{name} hat am Zielort einen Kundentermin; ein Shuttle wartet am Flugplatz, damit der Übergang vom Vorfeld zum lokalen Kontakt sauber klappt.';
    }
    return '{name} reist zu einem festen Termin am Zielort; am Flugplatz wartet die Abholung, damit der nächste Schritt nach dem Aussteigen gut vorbereitet ist.';
}

function _charterWeatherRaw(wx = null) {
    if (wx && typeof wx === 'object' && wx.raw && typeof wx.raw === 'object') return wx.raw;
    return wx && typeof wx === 'object' ? wx : null;
}

function _charterWeatherBundle(context = {}) {
    const candidates = [
        context.missionWeather,
        context.weatherSnapshot,
        context.weather,
        context.missionPlanV2?.resolvedNeeds?.weather_snapshot,
        context.missionPlanV2?.weather,
        context.missionContractV4?.weather,
        context.contract?.weather,
        context.missionContractV4?.missionPlan?.resolvedNeeds?.weather_snapshot
    ];
    return candidates.find(c => c && typeof c === 'object' && (c.dep || c.dest || c.targetPoi)) || null;
}

function _charterCollectWeatherHooks(context = {}) {
    const hooks = [];
    const add = (value) => {
        if (Array.isArray(value)) {
            value.forEach(add);
            return;
        }
        const text = String(value || '').replace(/\s+/g, ' ').trim();
        if (text) hooks.push(text.replace(/\.$/, '').slice(0, 160));
    };
    add(context.weatherHooks);
    add(context.missionPlanV2?.plan?.weatherHooks);
    add(context.missionContractV4?.missionPlan?.plan?.weatherHooks);
    add(context.contract?.missionPlan?.plan?.weatherHooks);
    return Array.from(new Set(hooks)).slice(0, 3);
}

function _charterWindData(wx = null) {
    const windKts = Number(wx?.windKts);
    if (!Number.isFinite(windKts)) return null;
    const windDeg = Number(wx?.windDeg);
    return {
        deg: Number.isFinite(windDeg) ? Math.round(windDeg) : null,
        kts: Math.round(windKts)
    };
}

function _charterWeatherSentence(context = {}) {
    const bundle = _charterWeatherBundle(context);
    const dep = _charterWeatherRaw(bundle?.dep || null);
    const dest = _charterWeatherRaw(bundle?.dest || bundle?.targetPoi || null);
    const bits = [];
    const depWind = _charterWindData(dep);
    const destWind = _charterWindData(dest);
    if (depWind && destWind) {
        const maxKts = Math.max(depWind.kts, destWind.kts);
        const windLabel = maxKts <= 8 ? 'leichter Wind' : 'Wind';
        if (depWind.deg !== null && destWind.deg !== null && Math.abs(depWind.deg - destWind.deg) <= 10) {
            bits.push(`${windLabel} aus ${depWind.deg} Grad (${depWind.kts} kt am Start, ${destWind.kts} kt am Ziel)`);
        } else {
            const depText = depWind.deg !== null ? `${depWind.deg} Grad/${depWind.kts} kt am Start` : `${depWind.kts} kt am Start`;
            const destText = destWind.deg !== null ? `${destWind.deg} Grad/${destWind.kts} kt am Ziel` : `${destWind.kts} kt am Ziel`;
            bits.push(`${windLabel} mit ${depText} und ${destText}`);
        }
    } else if (depWind || destWind) {
        const w = depWind || destWind;
        const place = depWind ? 'am Start' : 'am Ziel';
        const windLabel = w.kts <= 8 ? 'leichter Wind' : 'Wind';
        bits.push(w.deg !== null ? `${windLabel} aus ${w.deg} Grad mit ${w.kts} kt ${place}` : `${windLabel} mit ${w.kts} kt ${place}`);
    }

    const depVis = Number(dep?.visKm);
    const destVis = Number(dest?.visKm);
    const vis = Number.isFinite(depVis) ? depVis : (Number.isFinite(destVis) ? destVis : null);
    if (Number.isFinite(vis)) {
        bits.push(vis >= 10 ? 'mehr als 10 km Sicht' : `${vis.toFixed(1)} km Sicht`);
    }
    const temp = Number.isFinite(Number(dest?.tempC)) ? Number(dest.tempC) : (Number.isFinite(Number(dep?.tempC)) ? Number(dep.tempC) : null);
    if (Number.isFinite(temp)) bits.push(`etwa ${Math.round(temp)}°C`);
    const fltCat = String(dest?.fltCat || dep?.fltCat || '').trim().toUpperCase();
    if (fltCat && !bits.some(bit => bit.toUpperCase().includes(fltCat))) bits.push(`${fltCat}-Bedingungen`);

    if (bits.length) {
        return `Das Wetter gibt dem Flug einen ruhigen Rahmen: ${bits.join(', ')}. So bleibt der VFR-Transfer planbar und ruhig.`;
    }
    const hooks = _charterCollectWeatherHooks(context);
    if (hooks.length) {
        return `Aus den Wetterdaten nehmen wir ${hooks.join('; ')} als ruhigen Rahmen für den Transfer mit.`;
    }
    return '';
}

function _charterStoryLooksGeneric(story = '', passenger = null) {
    const s = _charterNormalizeText(story);
    if (!s) return true;
    if (/geplanter charter-transfer|professionelle durchfuhrung|professionelle durchfuehrung|passagiere reisen|wegen passagiere|weitergabe der passagiere|begleitperson reist|der auftrag bleibt ein ruhiger a-b-charter|saubere flugfuhrung|saubere flugfuehrung|kurzer handoff am zielflugplatz/.test(s)) return true;
    const name = _charterNormalizeText(passenger?.name || '');
    const role = _charterNormalizeText(passenger?.role || '');
    const hasName = !!name && !/passagier|gast|kunde|pax/.test(name) && s.includes(name);
    const hasRole = !!role && !_charterRoleLooksGeneric(role) && s.includes(role);
    const hasPersonalHook = /(shuttle|weiterreise|termin|kundentermin|notar|meeting|bauabnahme|begehung|freigabe|diagnose|vortrag|kongress|messe|event|veranstaltung|team|crew|abholung|unterlagen|rollkoffer|werkstatt|auftraggeber|bauleiter|makler)/.test(s);
    return !(hasName || hasRole) || !hasPersonalHook;
}

function _charterStoryHasWeather(story = '') {
    const s = _charterNormalizeText(story);
    return /(?:\bwetter\b|\bwind\b|\bsicht\b|\bvfr\b|\bmvfr\b|\bifr\b|temperatur|\bgrad\b|\bkt\b|\bknoten\b|regen|niesel|schauer|bewolkt|bewoelkt|wolken|cavok|metar|°c)/.test(s);
}

function _charterGreetingLooksGeneric(greeting = '', passenger = null, targetName = '') {
    const s = _charterNormalizeText(greeting);
    if (!s) return true;
    if (/wegen passagiere|passagiere reisen|erfolgreiche und sichere landung|weitergabe der passagiere|professionelle durchfuhrung|professionelle durchfuehrung|der flug nach .* wurde angefragt|heute geht es wegen/.test(s)) return true;
    const name = _charterNormalizeText(passenger?.name || '');
    const firstName = _charterNormalizeText(String(passenger?.name || '').split(/\s+/)[0] || '');
    const hasPerson = (!!firstName && s.includes(firstName)) || (!!name && s.includes(name));
    const hasPersonalHook = /(shuttle|weiterreise|termin|kundentermin|notar|meeting|begehung|freigabe|diagnose|vortrag|kongress|messe|event|veranstaltung|team|crew|abholung|unterlagen|rollkoffer|werkstatt|auftraggeber|bauleiter|makler)/.test(s);
    return !(hasPerson || hasPersonalHook);
}

function buildPersonalAptCharterStory(passenger = null, context = {}) {
    const ctx = _charterTemplateContext(passenger, context);
    const seed = _applyCharterTemplate(
        passenger?.storySeed || passenger?.personalStoryCue || _charterFallbackStorySeed(passenger),
        passenger,
        context
    );
    const paxLabel = _charterRoleLooksGeneric(ctx.role) ? ctx.name : `${ctx.name}, ${ctx.role},`;
    const intro = `${paxLabel} nutzt heute unseren Charter von ${ctx.startName} nach ${ctx.targetName}, weil der Termin am Ziel eine verlässliche, planbare Verbindung braucht.`;
    const weather = _charterWeatherSentence(context);
    const arrival = `Nach der Landung wartet ein lokaler Kontakt im GA-Bereich und übernimmt ${ctx.firstName} samt Handgepäck für den Weg zum Termin.`;
    const pilotFocus = `Für uns zählt ein unaufgeregter Charterflug: zuverlässig starten, sauber ankommen und dem Gast genug Ruhe lassen, um gesammelt auszusteigen.`;
    return _cleanupNarrativeArtifacts(`${intro} ${seed} ${weather} ${arrival} ${pilotFocus}`);
}

function buildPersonalAptCharterGreeting(passenger = null, context = {}) {
    const ctx = _charterTemplateContext(passenger, context);
    const templated = _applyCharterTemplate(passenger?.greetingText || '', passenger, context);
    if (templated && !_charterGreetingLooksGeneric(templated, passenger, ctx.targetName)) {
        return _cleanupNarrativeArtifacts(templated);
    }
    const weatherPrefix = _charterWeatherSentence(context) ? 'Die Bedingungen sehen für den Transfer ruhig aus. ' : '';
    return _cleanupNarrativeArtifacts(`Hi, ich bin ${ctx.firstName}. ${weatherPrefix}Am Ziel in ${ctx.targetName} wartet meine Abholung; mir ist wichtig, dass wir ruhig und planbar ankommen.`);
}

function personalizeAptCharterMission(mission = null, context = {}, preferredPersona = null) {
    if (!mission || typeof mission !== 'object') return mission;
    const m = { ...mission };
    const passenger = buildCharterPassenger(m.passenger || null, preferredPersona);
    const storyKey = Object.prototype.hasOwnProperty.call(m, 'story') ? 'story' : 's';
    const titleKey = Object.prototype.hasOwnProperty.call(m, 'title') ? 'title' : 't';
    const targetName = String(context.targetName || context.destName || m.targetName || m.destName || '').trim();
    const existingStory = String(m[storyKey] || '').trim();
    const storyContext = {
        ...context,
        targetName: targetName || context.targetName || context.destName
    };
    if (_charterStoryLooksGeneric(existingStory, passenger)) {
        m[storyKey] = buildPersonalAptCharterStory(passenger, storyContext);
    } else if (!_charterStoryHasWeather(existingStory)) {
        const weather = _charterWeatherSentence(storyContext);
        if (weather) m[storyKey] = _cleanupNarrativeArtifacts(`${existingStory} ${weather}`);
    }
    passenger.greetingText = buildPersonalAptCharterGreeting(passenger, storyContext);
    m.passenger = passenger;
    if (!String(m[titleKey] || '').trim()) {
        m[titleKey] = targetName ? `Charter nach ${targetName}` : 'Persönlicher Charterflug';
    }
    return m;
}

function buildCharterPassenger(basePassenger = null, preferredPersona = null) {
    const base = (basePassenger && typeof basePassenger === 'object') ? basePassenger : {};
    const persona = (preferredPersona && typeof preferredPersona === 'object')
        ? { ...preferredPersona }
        : _pickNextCharterPersona();
    const baseName = String(base.name || '').trim();
    const baseRole = String(base.role || '').trim();
    return {
        ...persona,
        ...base,
        name: !_charterNameLooksGeneric(baseName) ? baseName : persona.name,
        role: !_charterRoleLooksGeneric(baseRole) ? baseRole : persona.role,
        gender: (String(base.gender || '').toLowerCase() === 'female' || String(base.gender || '').toLowerCase() === 'male')
            ? String(base.gender || '').toLowerCase()
            : persona.gender,
        personality: String(base.personality || '').trim() || persona.personality,
        storySeed: String(base.storySeed || base.personalStoryCue || persona.storySeed || '').trim(),
        greetingText: String(base.greetingText || '').trim() || persona.greetingText,
        dialectHint: 'neutral',
        gTolerance: String(base.gTolerance || 'mittel').toLowerCase(),
        bankTolerance: String(base.bankTolerance || 'mittel').toLowerCase(),
        cargoSensitivity: String(base.cargoSensitivity || 'mittel').toLowerCase(),
        stomachSensitivity: String(base.stomachSensitivity || 'mittel').toLowerCase(),
        comfortPriority: String(base.comfortPriority || 'mittel').toLowerCase(),
        urgencyPriority: (String(base.urgencyPriority || persona.urgencyPriority || '').toLowerCase() === 'hoch') ? 'hoch' : 'niedrig',
        roleProfile: 'charter_professional_neutral_v1',
        taskDomain: 'charter',
        targetAltFt: 0,
        targetRadiusNm: 0,
        targetDwellMin: 0,
        trainingPlan: null
    };
}

function _missionProfilePersonaContext(missionContext = {}) {
    const md = (missionContext && typeof missionContext === 'object') ? missionContext : {};
    const plan = md._missionPlanV2?.plan || md.missionPlanV2?.plan || md.missionPlanV4?.plan || {};
    const contract = md.missionContractV4 || md._missionContractV4 || {};
    const profile = contract.profile || {};
    const lookup = md.poiLookup || contract.target?.poiLookup || {};
    const selectedTags = lookup.selectedTags || md.selectedTags || md.tags || {};
    const rawCategory = String(
        md.poiCategory ||
        md.requestedCategory ||
        md.category ||
        md.cat ||
        plan.targetCategory ||
        profile.pickerCategory ||
        profile.requestedCategory ||
        ''
    ).toLowerCase();
    const rawInfraType = String(
        lookup.selectedInfraType ||
        selectedTags.infra_type ||
        selectedTags.infraType ||
        md.infraType ||
        ''
    ).toLowerCase();
    const targetName = normalizeMissionText(md.poiName || md.targetName || md.destName || md.n || md.t || '');
    return {
        category: rawCategory || 'generic',
        infraType: rawInfraType,
        targetName
    };
}

function _missionProfilePersonaScore(persona = {}, context = {}) {
    if (!persona || typeof persona !== 'object') return 0;
    const category = String(context?.category || '').toLowerCase();
    const infraType = String(context?.infraType || '').toLowerCase();
    const nameHint = String(context?.targetName || '');
    const matchCategories = Array.isArray(persona.matchCategories)
        ? persona.matchCategories.map(v => String(v || '').toLowerCase()).filter(Boolean)
        : [];
    const matchInfraTypes = Array.isArray(persona.matchInfraTypes)
        ? persona.matchInfraTypes.map(v => String(v || '').toLowerCase()).filter(Boolean)
        : [];
    let score = 0;
    if (infraType && matchInfraTypes.includes(infraType)) score += 8;
    if (category && matchCategories.includes(category)) score += 4;

    const roleText = normalizeMissionText([
        persona.role,
        persona.storySeed,
        persona.greetingText
    ].filter(Boolean).join(' '));
    if (/wind/.test(nameHint) && /wind/.test(roleText)) score += 4;
    if (/(solar|photovoltaik|pv)/.test(nameHint) && /(solar|photovoltaik|pv)/.test(roleText)) score += 4;
    if (/(wasser|damm|stau|talsperre|hydro)/.test(nameHint) && /(wasser|damm|ufer|hydro)/.test(roleText)) score += 3;
    if (/(bruecke|brucke|bridge|viadukt)/.test(nameHint) && /(bauwerk|bruecke|brucke|tragwerk|widerlager)/.test(roleText)) score += 3;

    if (category && category !== 'generic' && matchCategories.length && !matchCategories.includes(category)) score -= 2;
    if (infraType && matchInfraTypes.length && !matchInfraTypes.includes(infraType)) score -= 2;
    return score;
}

function _pickRandomProfilePersona(profileSpec, missionContext = null) {
    const list = Array.isArray(profileSpec?.personas) ? profileSpec.personas.filter(Boolean) : [];
    if (!list.length) return null;
    const context = _missionProfilePersonaContext(missionContext || {});
    const scored = list
        .map(p => ({ persona: p, score: _missionProfilePersonaScore(p, context) }))
        .filter(entry => entry.score >= 0);
    const bestScore = Math.max(0, ...scored.map(entry => entry.score));
    const pool = bestScore > 0
        ? scored.filter(entry => entry.score === bestScore).map(entry => entry.persona)
        : list;
    return { ...pool[Math.floor(Math.random() * pool.length)] };
}

function buildMissionProfilePassenger(basePassenger = null, profileSpec = null, isPOI = false, storyHint = '', missionContext = null) {
    if (!profileSpec || !profileSpec.id || profileSpec.id === 'auto') {
        return (basePassenger && typeof basePassenger === 'object') ? basePassenger : null;
    }
    const base = (basePassenger && typeof basePassenger === 'object') ? basePassenger : {};
    const persona = _pickRandomProfilePersona(profileSpec, missionContext) || {};
    const tol = profileSpec.tolerances || {};
    const baseGender = String(base.gender || '').toLowerCase();
    const personaGender = String(persona.gender || '').toLowerCase();
    const merged = {
        ...base,
        name: String(persona.name || base.name || '').trim() || 'Alex Neumann',
        role: String(persona.role || base.role || '').trim() || 'Passagier',
        gender: (personaGender === 'female' || personaGender === 'male')
            ? personaGender
            : ((baseGender === 'female' || baseGender === 'male') ? baseGender : 'male'),
        personality: String(persona.personality || base.personality || 'ruhig, freundlich, professionell').trim(),
        dialectHint: String(persona.dialectHint || base.dialectHint || 'neutral').trim() || 'neutral',
        storySeed: String(persona.storySeed || base.storySeed || base.personalStoryCue || '').trim(),
        personalStoryCue: String(persona.storySeed || base.personalStoryCue || base.storySeed || '').trim(),
        greetingText: String(persona.greetingText || profileSpec.greetingText || base.greetingText || '').trim() || 'Hi, danke fürs Fliegen heute.',
        roleProfile: String(profileSpec.roleProfile || base.roleProfile || 'general_passenger_v1').toLowerCase(),
        taskDomain: String(profileSpec.taskDomain || base.taskDomain || 'general').toLowerCase(),
        gTolerance: String(tol.gTolerance || base.gTolerance || 'mittel').toLowerCase(),
        bankTolerance: String(tol.bankTolerance || base.bankTolerance || 'mittel').toLowerCase(),
        cargoSensitivity: String(tol.cargoSensitivity || base.cargoSensitivity || 'mittel').toLowerCase(),
        stomachSensitivity: String(tol.stomachSensitivity || base.stomachSensitivity || 'mittel').toLowerCase(),
        comfortPriority: String(tol.comfortPriority || base.comfortPriority || 'mittel').toLowerCase(),
        urgencyPriority: (String(tol.urgencyPriority || base.urgencyPriority || '').toLowerCase() === 'hoch') ? 'hoch' : 'niedrig',
        targetAltFt: isPOI ? Number(base.targetAltFt || 0) : 0,
        targetRadiusNm: isPOI ? Number(base.targetRadiusNm || 0) : 0,
        targetDwellMin: isPOI ? Number(base.targetDwellMin || 0) : 0,
        trainingPlan: null,
        storyHint: String(storyHint || '')
    };
    return merged;
}

function missionUsesPoiTaskRecipe(mission = null) {
    const md = (mission && typeof mission === 'object') ? mission : null;
    if (!md) return false;
    const missionType = normalizeMissionType(md.missionType || '', false);
    if (missionType === 'poi' || md.isPOI || md.poiPresentation) return true;
    const bush = (md?.bush && typeof md.bush === 'object') ? md.bush : null;
    if (missionType !== 'bush') return false;
    if (typeof _bushRecipeIdFromSpec === 'function') {
        return _bushRecipeIdFromSpec(bush) === 'poi_on_task_return';
    }
    return !!(
        String(bush?.profileId || '').toLowerCase() === 'bush_recon_return'
        && String(bush?.targetMode || '').toLowerCase() === 'area_then_return'
        && String(bush?.completionMode || '').toLowerCase() === 'return_home'
    );
}

function missionPoiRecipeId(mission = null) {
    const md = (mission && typeof mission === 'object') ? mission : null;
    if (!md || !missionUsesPoiTaskRecipe(md)) return '';
    const passenger = (md?.passenger && typeof md.passenger === 'object')
        ? md.passenger
        : ((md?.missionContract?.passenger && typeof md.missionContract.passenger === 'object')
            ? md.missionContract.passenger
            : null);
    const bush = (md?.bush && typeof md.bush === 'object') ? md.bush : null;
    const missionType = normalizeMissionType(md.missionType || '', false);
    const taskDomain = String(
        passenger?.taskDomain
        || md?.missionContract?.taskDomain
        || ''
    ).trim().toLowerCase();
    const dwellMin = Number(passenger?.targetDwellMin ?? md?.targetDwellMin ?? 0);
    if (/^(training|club_training_basic|club_training_advanced)$/.test(taskDomain)) return 'poi_training';
    if (taskDomain === 'fire_watch') return 'poi_fire_watch';
    if (missionIsSarHeliMission(md)) return 'poi_sar_heli';
    if (taskDomain === 'search_and_rescue') return 'poi_search_and_rescue';
    if (Number.isFinite(dwellMin) && dwellMin === 0) return 'poi_flyover';
    if (missionType === 'bush' && ((typeof _bushRecipeIdFromSpec === 'function' && _bushRecipeIdFromSpec(bush) === 'poi_on_task_return')
        || (String(bush?.targetMode || '').toLowerCase() === 'area_then_return' && String(bush?.completionMode || '').toLowerCase() === 'return_home'))) {
        return 'poi_on_task_return';
    }
    return 'poi_on_task';
}

window.missionPoiRecipeId = missionPoiRecipeId;

function missionUsesPoiPresentation(mission = null) {
    const md = (mission && typeof mission === 'object') ? mission : null;
    if (!md) return false;
    return !!(md.isPOI || md.poiPresentation || missionUsesPoiTaskRecipe(md));
}

function getPoiTaskPassengerDefaults({ mission = null, isPOI = false, poiTerrainFt = null } = {}) {
    const usesPoiTaskRecipe = !!(isPOI || missionUsesPoiTaskRecipe(mission));
    if (!usesPoiTaskRecipe) {
        return { treatAsPoiTask: false, defaultTargetAltFt: 0, defaultTargetRadiusNm: 0, defaultTargetDwellMin: 0 };
    }
    const bush = (mission?.bush && typeof mission.bush === 'object') ? mission.bush : null;
    const terrainFt = Number.isFinite(Number(poiTerrainFt))
        ? Math.round(Number(poiTerrainFt))
        : Math.round(Number(mission?.poiTerrainFt ?? mission?.targetAltFt ?? currentDestElev) || 0);
    const areaRadiusNm = Math.max(1.5, Number(bush?.areaRef?.radiusNm) || 0);
    const successMinAreaTimeSec = Math.max(0, Number(bush?.success?.minAreaTimeSec) || 0);
    return {
        treatAsPoiTask: true,
        defaultTargetAltFt: terrainFt > 0 ? terrainFt + 1000 : 0,
        defaultTargetRadiusNm: areaRadiusNm > 0 ? Math.max(2, Math.min(areaRadiusNm, 4.5)) : 3,
        defaultTargetDwellMin: successMinAreaTimeSec > 0 ? Math.max(2, Math.round(successMinAreaTimeSec / 60)) : 2
    };
}

function _escapeMissionNamePattern(value) {
    return String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function _replaceMissionPassengerNameText(value, fromName, toName) {
    const text = String(value || '');
    const from = String(fromName || '').trim();
    const to = String(toName || '').trim();
    if (!text || !from || !to || from === to) return value;
    const parts = from.split(/\s+/).filter(Boolean);
    const replacements = [from];
    if (parts.length >= 2) {
        const first = parts[0];
        const last = parts[parts.length - 1];
        replacements.push(`Frau ${last}`, `Herr ${last}`);
        if (first.length >= 4) replacements.push(first);
    }
    let out = text;
    replacements.forEach(pattern => {
        if (!pattern) return;
        const replacement = /^Frau\s+/i.test(pattern)
            ? `Frau ${to.split(/\s+/).slice(-1)[0] || to}`
            : (/^Herr\s+/i.test(pattern) ? `Herr ${to.split(/\s+/).slice(-1)[0] || to}` : to);
        out = out.replace(new RegExp(`\\b${_escapeMissionNamePattern(pattern)}\\b`, 'g'), replacement);
    });
    return out;
}

function synchronizeMissionPassengerName(mission, oldPassenger = null, newPassenger = null) {
    if (!mission || typeof mission !== 'object') return mission;
    const oldName = String(oldPassenger?.name || '').trim();
    const newName = String(newPassenger?.name || '').trim();
    if (!oldName || !newName || oldName === newName) return mission;
    ['t', 'title', 's', 'story'].forEach(key => {
        if (typeof mission[key] === 'string') {
            mission[key] = _replaceMissionPassengerNameText(mission[key], oldName, newName);
        }
    });
    if (mission.passenger && typeof mission.passenger === 'object' && typeof mission.passenger.greetingText === 'string') {
        mission.passenger.greetingText = _replaceMissionPassengerNameText(mission.passenger.greetingText, oldName, newName);
    }
    return mission;
}

function _normUrgencyBinary(v) {
    return String(v || '').toLowerCase() === 'hoch' ? 'hoch' : 'niedrig';
}

function _hasTimePressureText(txt) {
    return /\b(zeitkrit|dringend|eilig|p(?:ue|ü)nkt\w*|zeitnah|sofort|unverz(?:ue|ü)glich|hoechste\s+prioritaet|höchste\s+priorität|so bald wie moeglich|so schnell wie moeglich)/i.test(String(txt || ''));
}

function _hasCargoSensitivityText(txt) {
    return /\b(empfindlich(?:e|er|en)?|fragil(?:e|er|en)?|stoss(?:-|\s)?empfindlich(?:e|er|en)?|stoß(?:-|\s)?empfindlich(?:e|er|en)?|erschuetterungsarm|erschütterungsarm|vorsichtig\s+mit\s+der\s+fracht)\b/i.test(String(txt || ''));
}

function _stripCargoSensitivityText(txt) {
    return String(txt || '')
        .replace(/\b(empfindlich(?:e|er|en)?|fragil(?:e|er|en)?|stoss(?:-|\s)?empfindlich(?:e|er|en)?|stoß(?:-|\s)?empfindlich(?:e|er|en)?|erschuetterungsarm|erschütterungsarm)\b/gi, '')
        .replace(/\b(vorsichtig|behutsam|sanft)\s+(mit|bei)\s+der\s+fracht\b/gi, '')
        .replace(/\s{2,}/g, ' ')
        .replace(/\s+([,.;:!?])/g, '$1')
        .trim();
}

function _cleanupNarrativeArtifacts(txt) {
    return String(txt || '')
        .replace(/\bDa\s+die\s+Fracht\s+([^.!?]{0,160}?)\s+erwartet\s+wird,\s*m(?:ue|ü)ssen\s+wir,\s*ohne\s+dabei\s+([^.!?]{1,180}?)\s+durch\s+([^.!?]{1,80}?)\s+zu\s+reizen/gi, 'Die Fracht $1 wird erwartet; dabei duerfen wir $2 nicht durch $3 reizen')
        .replace(/\bDa\s+die\s+Empf(?:ae|ä)nger\s+([^.!?]{1,180}?)\s+(?:schon\s+)?sehns(?:ue|ü)chtig\s+auf\s+die\s+Teile\s+warten,\s*ist\s+der\s+Flug\s*,\s*aber\s+die\s+Fracht\b/gi, 'Die Empfaenger $1 warten bereits auf die Teile; die Fracht')
        .replace(/(^|[.!?]\s*)(?:Fokus|Bildungsauftrag|Drift-Guard|Profilkontext|Profil-Fix|Konsistenz-Pflicht|Operations-Regel|Output-Hygiene)\s*:[^.?!]*(?:[.?!]|$)/gi, (_, lead) => lead ? `${lead.trim()} ` : '')
        .replace(/\b(?:ohne|kein(?:e|en|er|es)?)\s+(?:technischen\s+)?(?:inspektionsfokus|inspektionsauftrag|arbeitsauftrag|themenmix)\b[,.]?\s*/gi, '')
        .replace(/\bzeitkritisch,\s*p(?:ue|ü)nktlich\s+ankommen[.!?]?/gi, '')
        .replace(/<\s*\/?\s*(INSTRUKTIONEN|KONTEXT|OUTPUT)\s*>/gi, '')
        .replace(/\b(OUTPUT-HYGIENE|KONSISTENZ-PFLICHT|PROFIL-FIX|OPERATIONS-REGEL)\b[^.?!]*/gi, '')
        .replace(/\bverlaesslicher\s+vereins-?\/?utility-?einsatz\s+ohne\s+themenmix\b[.!?]?/gi, '')
        .replace(/\bverlässlicher\s+vereins-?\/?utility-?einsatz\s+ohne\s+themenmix\b[.!?]?/gi, '')
        .replace(/\bohne\s+themenmix\b[.!?]?/gi, '')
        .replace(/\bder\s+auftrag\s+ist\s*,?\s*wir\s+sollten\b/gi, '')
        .replace(/\bder\s+auftrag\s+ist\b\s*,?/gi, '')
        .replace(/\bwir\s+sollten\b\s*,?/gi, '')
        .replace(/,\s*aber\s*([.?!])/gi, '$1')
        .replace(/\s+\baber\s*([.?!])/gi, '$1')
        .replace(/(?:^|[.!?]\s*)[,;:]+/g, '. ')
        .replace(/\s{2,}/g, ' ')
        .replace(/\s+([,.;:!?])/g, '$1')
        .replace(/^[,.;:\-]\s*/g, '')
        .trim();
}

function _enforceProfileNarrativeContract(storyText, profileId, isPOI = false) {
    let s = _cleanupNarrativeArtifacts(storyText);
    if (String(profileId || '') === 'news_coverage' && !isPOI) {
        s = s
            .replace(/\bund\s+ohne\s+kreisen\s+über\s+dem\s+ziel\b/gi, '')
            .replace(/\bund\s+ohne\s+kreisen\s+ueber\s+dem\s+ziel\b/gi, '')
            .replace(/\bohne\s+kreisen\s+über\s+dem\s+ziel\b/gi, '')
            .replace(/\bohne\s+kreisen\s+ueber\s+dem\s+ziel\b/gi, '')
            .replace(/\bkein(?:en|e|)\s+arbeitsauftrag\s+in\s+der\s+luft(?:\s+am\s+ziel)?\b/gi, '')
            .replace(/\bkein(?:en|e|)\s+kreisen\b/gi, '')
            .replace(/\bkein(?:en|e|)\s+verweilen(?:\/überflug|\/ueberflug)?(?:\s+als\s+missionsziel)?\b/gi, '')
            .replace(/\s{2,}/g, ' ')
            .replace(/\s+([,.;:!?])/g, '$1')
            .trim();
        if (!/berichterstattung\s+am\s+boden/i.test(s)) {
            s = `${s}${s ? ' ' : ''}Am Ziel startet die Berichterstattung am Boden.`.trim();
        }
    }
    return _cleanupNarrativeArtifacts(s);
}

function _stripCoveredProfileCue(storyText, profile) {
    const id = String(profile?.id || '').toLowerCase();
    let s = String(storyText || '');
    if (id === 'science_bio') {
        const cueRe = /\s*Natur-\/Umweltbeobachtung\s+mit\s+klarer,\s+sachlicher\s+Einordnung[.!?]?/i;
        if (cueRe.test(s)) {
            const withoutCue = s.replace(cueRe, '').trim();
            if (_storyAlreadyCoversProfileCue(withoutCue, profile)) {
                s = withoutCue;
            }
        }
    }
    return _cleanupNarrativeArtifacts(s);
}

function _stripTimePressureText(txt) {
    return String(txt || '')
        .replace(/\b(h(?:oe|ö)chste\s+priorit(?:ae|ä)t)\s*:?\s*/gi, '')
        .replace(/\b(zeitkritisch|dringend|eilig|zeitnah)\b/gi, '')
        .replace(/\b(sofort|unverz(?:ue|ü)glich)\b/gi, '')
        .replace(/\bso\s+bald\s+wie\s+m(?:oe|ö)glich\b/gi, '')
        .replace(/\bso\s+schnell\s+wie\s+m(?:oe|ö)glich\b/gi, '')
        .replace(/\bwir\s+m(?:ue|ü)ssen\s+(jetzt\s+)?(dringend|schnell|z(?:ue|ü)gig)\b[^.?!]*/gi, '')
        .replace(/\bp(?:ue|ü)nktlich(?:es|e|er|en)?\s+(ankommen|ankunft|eintreffen|sein)\s+(hilft|ist|waere|wäre|bleibt|macht)\b[^.?!]*/gi, '')
        .replace(/\bp(?:ue|ü)nktlich(?:e|er|es|en)?\s+(ankunft|uebergabe|übergabe|termin|eintreffen)\b[^.?!]*/gi, '')
        .replace(/\bp(?:ue|ü)nktlich\s+(am\s+ziel\s+)?(ankommen|sein)\b/gi, '')
        .replace(/\bist\s*,\s*(da|weil)\b/gi, 'passt gut, $1')
        .replace(/\s{2,}/g, ' ')
        .replace(/\s+([,.;:!?])/g, '$1')
        .trim();
}

function _finalizeMissionNarrative(mission, profile, isPOI = false) {
    const m = (mission && typeof mission === 'object') ? mission : {};
    let title = _cleanupNarrativeArtifacts(String(m.t || m.title || '').trim());
    let story = _cleanupNarrativeArtifacts(String(m.s || m.story || '').trim());
    const urgency = _normUrgencyBinary(m?.passenger?.urgencyPriority);
    const cargoSensitivity = String(m?.passenger?.cargoSensitivity || '').toLowerCase() === 'hoch' ? 'hoch' : 'niedrig';
    const guard = {
        urgency,
        cargoSensitivity,
        timeHintAdded: false,
        timePressureStripped: false,
        cargoHintStripped: false,
        profileContractApplied: false
    };

    if (urgency === 'hoch') {
        if (!_hasTimePressureText(title) && !_hasTimePressureText(story)) {
            story = `${story}${story ? ' ' : ''}Zeitkritischer Auftrag: Pünktliches Eintreffen ist wichtig.`.trim();
            guard.timeHintAdded = true;
        }
    } else {
        const before = `${title} ${story}`;
        title = _stripTimePressureText(title);
        story = _stripTimePressureText(story);
        guard.timePressureStripped = before !== `${title} ${story}`;
    }

    if (cargoSensitivity !== 'hoch') {
        const before = `${title} ${story}`;
        if (_hasCargoSensitivityText(title)) title = _stripCargoSensitivityText(title);
        if (_hasCargoSensitivityText(story)) story = _stripCargoSensitivityText(story);
        guard.cargoHintStripped = before !== `${title} ${story}`;
    }

    if (String(profile?.id || '') === 'cargo_fragile') {
        const before = `${title} ${story}`;
        const medicalUrgencyDrift = /\b(organtransport|spenderorgan|notaufnahme|notfall|emergency|medizinischer\s+notfall|patient(?:in|en)?)\b/i.test(before);
        if (medicalUrgencyDrift) {
            if (/\b(organtransport|spenderorgan|notfall|emergency)\b/i.test(title)) title = 'Empfindliche Fracht';
            story = 'Empfindliche Fracht wird zur sicheren Uebergabe am Ziel gebracht. Der Fokus liegt auf ruhiger, erschuetterungsarmer Flugfuehrung.';
            guard.profileContractApplied = true;
        }
    }

    const beforeProfile = story;
    story = _enforceProfileNarrativeContract(story, String(profile?.id || ''), isPOI);
    story = _stripCoveredProfileCue(story, profile);
    guard.profileContractApplied = guard.profileContractApplied || beforeProfile !== story;
    title = _cleanupNarrativeArtifacts(title);
    story = _cleanupNarrativeArtifacts(story);

    m.t = title || m.t || '';
    m.s = story || m.s || '';
    m._narrativeGuard = guard;
    return m;
}

function _animalTransportCargoSignalFromText(text = '') {
    const raw = String(text || '');
    const norm = normalizeMissionText(raw);
    const hay = `${raw.toLowerCase()} ${norm}`;
    const signals = [
        { id: 'goat', match: /zieg|zicklein|jungziege|goat|hircus/i, cargo: /zieg|zicklein|goat|hircus/i },
        { id: 'sheep', match: /schaf|sheep/i, cargo: /schaf|sheep/i },
        { id: 'deer', match: /rehkitz|reh|hirsch|wildtier|deer/i, cargo: /reh|hirsch|deer/i },
        { id: 'gull', match: /moewe|mowe|möwe|wildvogel|vogelstation|seagull/i, cargo: /moewe|mowe|möwe|wildvogel/i },
        { id: 'goose', match: /gans|goose|wasservogel/i, cargo: /gans|goose/i },
        { id: 'duck', match: /ente|enten|duck|mallard/i, cargo: /ente|duck/i },
        { id: 'horse_vet', match: /pferd|gestuet|gestüt|horse|tierarzt|vet|veterinaer|veterinär/i, cargo: /pferd|horse|vet|tierarzt|veterinaer|veterinär/i }
    ];
    return signals.find(s => s.match.test(hay)) || null;
}

function _pickAnimalTransportCargo(cargoPool = [], missionLike = {}) {
    const pool = Array.isArray(cargoPool) ? cargoPool.filter(Boolean) : [];
    if (!pool.length) return '';
    const titleSignal = _animalTransportCargoSignalFromText(missionLike?.t || missionLike?.title || '');
    const storySignal = _animalTransportCargoSignalFromText(missionLike?.s || missionLike?.story || '');
    const signal = titleSignal || storySignal;
    if (signal) {
        const matchedCargo = pool.find(cargo => signal.cargo.test(String(cargo || '')));
        if (matchedCargo) return matchedCargo;
    }
    return pool[Math.floor(Math.random() * pool.length)] || pool[0] || '';
}

function _missionPlanFactsForNarrative(missionLike = {}, maxItems = 2) {
    const plan = missionLike?._missionPlanV2?.plan || missionLike?.missionPlanV2?.plan || missionLike?.missionPlan?.plan || null;
    const facts = [
        ...(Array.isArray(plan?.localFacts) ? plan.localFacts : []),
        ...(Array.isArray(plan?.mustMention) ? plan.mustMention : [])
    ];
    const seen = new Set();
    return facts
        .map(x => String(x || '').replace(/\s+/g, ' ').trim())
        .filter(Boolean)
        .filter(x => {
            const key = x.toLowerCase();
            if (seen.has(key)) return false;
            seen.add(key);
            return true;
        })
        .slice(0, Math.max(0, Math.round(Number(maxItems) || 0)));
}

function _learningGuideFactLine(paxName = 'Der Lern-Guide') {
    return `${paxName} hebt die vorbereiteten Details fuer die Ansagen im Flug auf und nutzt sichtbare Orientierungspunkte nur zur Einordnung.`;
}

function _targetLabelForGuideNarrative(missionLike = {}) {
    const plan = missionLike?._missionPlanV2?.plan || missionLike?.missionPlanV2?.plan || null;
    const fromPlan = String(plan?.targetLabel || '').replace(/\s+/g, ' ').trim();
    if (fromPlan) return fromPlan;
    const title = String(missionLike?.t || missionLike?.title || '').trim();
    const afterColon = (title.match(/:\s*(.+)$/) || [])[1];
    if (afterColon) return afterColon.trim();
    const orient = title.match(/\b(?:Wissensflug|Orientierungsflug|Kontextflug|Faktenrunde|POI-Erklaerung|POI-Erklärung)\s+(.+)$/i);
    if (orient?.[1]) return orient[1].trim();
    return 'Zielgebiet';
}

function _sanitizeLearningGuideNarrative(missionLike = {}) {
    if (!missionLike || typeof missionLike !== 'object') return missionLike;
    const target = _targetLabelForGuideNarrative(missionLike);
    const paxName = String(missionLike.passenger?.name || 'Der Lern-Guide').trim();
    const factLine = _learningGuideFactLine(paxName);
    const currentRaw = String(missionLike.s || missionLike.story || '');
    const current = currentRaw.toLowerCase();
    const guideLearnsHerself = /(guide|tour-guide|lern-guide|mila|jonas).{0,80}(lernt|trainiert|abspeicher|vorbereit|spaeter|später)|angehend(?:er|e|en)?\s+tour-guide|kuenftig(?:er|e|en)?\s+sightseeing|künft/i.test(current);
    const pronounDrift = /\bunseren\s+[A-ZÄÖÜ][a-zäöüß]+\b|damit\s+er\b|damit\s+sie\s+das\s+gelaende/i.test(currentRaw);
    const internalNarrativeLeak = /gesicherte punkte aus dem kontext|es gibt am boden|\s\|\s|pipeline|contract|debug|formularfeld|konkrete\s+anker|faktenanker|als\s+einstieg\s+reichen\s+im\s+briefing/i.test(currentRaw);
    const writerInstructionLeak = /\bachten\s+sie\b|\bziel\s+ist\s+es\b|\bwir\s+f(?:ü|ue)hren\b|\binformationsflug\b|\bfundiertes\s+verst(?:ä|ae)ndnis\b|\bbegleiten\s+sie\b|\bsie\s+einen\b|\bdurch\s+diesen\b|\bdurchf(?:ü|ue)hren/i.test(currentRaw);
    if (guideLearnsHerself || pronounDrift || internalNarrativeLeak || writerInstructionLeak || !/erklaert|erklärt|fakten|einordnung|orientierung/i.test(currentRaw)) {
        missionLike.s = `${paxName} begleitet dich heute als Lern-Guide rund um ${target}. Unterwegs erklaert ${paxName} kurze Fakten, landschaftlichen Kontext und sichtbare Referenzen, damit du die Gegend aus der Luft besser einordnen kannst. ${factLine} Der Flug bleibt ein ruhiger Rundflug: anfliegen, anschauen, einordnen und danach zurueck zum Heimatplatz.`;
    }
    if (!/^Wissensflug:|^Faktenrunde:|^Kontextflug:|^POI-Erkl/i.test(String(missionLike.t || ''))) {
        missionLike.t = `Wissensflug: ${target}`;
    }
    return missionLike;
}

function _targetLabelForSightseeingNarrative(missionLike = {}) {
    const plan = missionLike?._missionPlanV2?.plan || missionLike?.missionPlanV2?.plan || missionLike?.missionPlan?.plan || null;
    const fromPlan = String(plan?.targetLabel || '').replace(/\s+/g, ' ').trim();
    if (fromPlan) return fromPlan;
    const title = String(missionLike?.t || missionLike?.title || '').trim();
    const afterColon = (title.match(/:\s*(.+)$/) || [])[1];
    if (afterColon) return afterColon.trim();
    const titleTarget = title.match(/\b(?:Panorama(?:flug|-Rundflug)?|Aussichtsflug|Foto-Ausflug|Orientierungsrunde|Rundflug|Ausflug)\s+(?:ueber|über|zu|nach)?\s*(.+)$/i);
    if (titleTarget?.[1]) return titleTarget[1].trim();
    return String(missionLike?.targetName || missionLike?.poiName || 'Zielgebiet').replace(/\s+/g, ' ').trim() || 'Zielgebiet';
}

function _missionTemplateText(text = '', context = {}) {
    const name = String(context.name || '').trim();
    const firstName = String(context.firstName || name.split(/\s+/)[0] || '').trim();
    const targetName = String(context.targetName || context.target || 'dem Zielgebiet').trim();
    const role = String(context.role || '').trim();
    return String(text || '')
        .replace(/\{name\}/g, name || 'der Gast')
        .replace(/\{firstName\}/g, firstName || name || 'der Gast')
        .replace(/\{targetName\}/g, targetName || 'das Zielgebiet')
        .replace(/\{target\}/g, targetName || 'das Zielgebiet')
        .replace(/\{role\}/g, role || 'Gast')
        .replace(/\s{2,}/g, ' ')
        .trim();
}

function _missionSightseeingWorkText(text = '') {
    const s = normalizeMissionText(text);
    if (!s) return false;
    return /\b(auftrag|beauftragt|erfassung|erfassen|dokumentation|dokumentieren|lagebild|befund|befunde|bericht|arbeitsauftrag|arbeitsflug|arbeitshoehe|arbeitshöhe|inspektion|pruefung|prüfung|vermessung|vermessen|kartierung|kartieren|bewertung|bewerten|daten|bebauung|bauzustand|zustandserfassung|einsatz|wartung|zielbeobachtung|beobachtungskreis)\b/.test(s);
}

function _missionSightseeingStoryLooksFlat(story = '') {
    const raw = String(story || '').replace(/\s+/g, ' ').trim();
    const s = normalizeMissionText(raw);
    if (!raw || raw.length < 180) return true;
    if (_missionSightseeingWorkText(raw)) return true;
    if (/\bdie anfrage kommt von sightseeing|visueller ueberblick|visueller uberblick|zielbereich .* abgearbeitet|aussichtspunkt .* abgearbeitet\b/.test(s)) return true;
    return !/\b(gast|gaeste|gaste|besuch|freund|familie|ausflug|blick|aussicht|foto|erinnerung|panorama|rundflug|wochenende|heimat|gemeinsam|entspannt)\b/.test(s);
}

function _missionSightseeingCategoryLine(missionLike = {}, target = 'Zielgebiet') {
    const cat = String(
        missionLike?.cat
        || missionLike?.poiCategory
        || missionLike?._missionPlanV2?.plan?.targetCategory
        || missionLike?.missionPlanV2?.plan?.targetCategory
        || ''
    ).toLowerCase();
    if (cat === 'city') {
        return `Aus der Höhe sollen Ortsbild, Randlagen und die umgebende Landschaft von ${target} als zusammenhängender Eindruck wirken.`;
    }
    if (cat === 'castle' || cat === 'historic') {
        return `Der Blick auf ${target} lebt von der Lage im Gelände und davon, wie Bauwerk, Ort und Umgebung zusammenwirken.`;
    }
    if (cat === 'mountain' || cat === 'terrain' || cat === 'forest') {
        return `Bei ${target} geht es um Relief, Kanten, Täler und den ruhigen Landschaftseindruck aus der Luft.`;
    }
    if (cat === 'water') {
        return `Bei ${target} stehen Uferlinie, Wasserfläche und Umgebung als ruhiger Blickfang im Mittelpunkt.`;
    }
    return `Der Zielbereich ${target} ist der Blickfang der Runde und soll aus der Luft gut wiedererkennbar bleiben.`;
}

function _sanitizeSightseeingTourNarrative(missionLike = {}, isPOI = false) {
    if (!missionLike || typeof missionLike !== 'object' || !isPOI) return missionLike;
    const target = _targetLabelForSightseeingNarrative(missionLike);
    const pax = (missionLike.passenger && typeof missionLike.passenger === 'object') ? missionLike.passenger : {};
    const paxName = String(pax.name || 'Der Sightseeing-Gast').trim();
    const templateContext = {
        name: paxName,
        firstName: paxName.split(/\s+/)[0] || paxName,
        role: pax.role || 'Sightseeing-Gast',
        targetName: target
    };
    const cue = _missionTemplateText(pax.personalStoryCue || pax.storySeed || '', templateContext);
    const currentStory = String(missionLike.s || missionLike.story || '').trim();
    if (_missionSightseeingStoryLooksFlat(currentStory)) {
        const lead = cue || `${paxName} begleitet heute zwei Gäste, die ${target} als ruhigen Ausflugsmoment aus der Luft erleben möchten.`;
        missionLike.s = [
            lead,
            _missionSightseeingCategoryLine(missionLike, target),
            'Der Flug bleibt bewusst weich und unaufgeregt, damit Blick, Orientierung und ein paar persönliche Fotos den Höhepunkt bilden.',
            'Der Zielbereich bleibt reiner Sichtpunkt; nach der Runde geht es ohne Eile zurück zum Heimatplatz.'
        ].join(' ');
    }
    const title = String(missionLike.t || missionLike.title || '').trim();
    if (!/\b(panorama|aussicht|rundflug|foto|orientierungsrunde|blick)\b/i.test(title)) {
        missionLike.t = `Panorama-Rundflug: ${target}`;
    }
    if (missionLike.passenger && typeof missionLike.passenger === 'object') {
        const currentGreeting = String(missionLike.passenger.greetingText || '').trim();
        const templatedGreeting = _missionTemplateText(currentGreeting, templateContext);
        const greetingLooksFlat = !templatedGreeting
            || templatedGreeting.length < 45
            || _missionSightseeingWorkText(templatedGreeting)
            || /entspannten ausblick/i.test(normalizeMissionText(templatedGreeting));
        missionLike.passenger.greetingText = greetingLooksFlat
            ? `Hi, heute geht es nur um den Blick auf ${target}. Bitte eher weich und entspannt, damit alle die Aussicht genießen können.`
            : templatedGreeting;
    }
    return missionLike;
}

function applyMissionTaskProfileToMission(mission, isPOI, profileId, paxText, cargoText) {
    const m = (mission && typeof mission === 'object') ? { ...mission } : {};
    const usesPoiTaskRecipe = missionUsesPoiTaskRecipe(m);
    const baseType = (isPOI || usesPoiTaskRecipe) ? 'poi' : 'apt';
    const profile = getMissionTaskProfile(profileId, baseType);
    if (!profile || profile.id === 'auto') {
        return { mission: m, paxText, cargoText, appliedProfile: 'auto' };
    }

    const sourcePassenger = (m.passenger && typeof m.passenger === 'object') ? { ...m.passenger } : null;
    const passenger = buildMissionProfilePassenger(sourcePassenger || null, profile, (isPOI || usesPoiTaskRecipe), m.s || '', m);
    if (passenger) {
        if (profile.id === 'tour_guide_knowledge') {
            passenger.targetAltFt = 0;
            if (!(Number(passenger.targetRadiusNm) > 0)) passenger.targetRadiusNm = 3;
            if (!(Number(passenger.targetDwellMin) > 0)) passenger.targetDwellMin = 4;
        }
        m.passenger = passenger;
        synchronizeMissionPassengerName(m, sourcePassenger, passenger);
    }
    if (profile.paxText) {
        paxText = profile.paxText;
    } else if (m.passenger?.role) {
        paxText = `1 PAX (${m.passenger.role})`;
    }
    const cargoPool = Array.isArray(profile.cargoPool) ? profile.cargoPool.filter(Boolean) : [];
    if (cargoPool.length) {
        cargoText = profile.id === 'animal_transport'
            ? _pickAnimalTransportCargo(cargoPool, m)
            : cargoPool[Math.floor(Math.random() * cargoPool.length)];
    }
    if (profile.id === 'animal_transport') {
        const targetMatch = String(m.t || '').match(/\b(nach|zur|zum)\s+(.+)$/i);
        const targetHint = targetMatch ? `${targetMatch[1]} ${targetMatch[2]}` : 'zum Zielplatz';
        const cargoClean = String(cargoText || '').replace(/\s*\([^)]*\)/g, '').trim();
        if (cargoClean) {
            const liveAnimalCargo = /transportbox|ziege|schaf|reh|hirsch|moewe|möwe|gans|ente|schwan|wildvogel/i.test(cargoClean)
                && !/vet|veterinaer|veterinär|dokument|unterlagen|tasche|futter|material/i.test(cargoClean);
            m.s = liveAnimalCargo
                ? `Eine Auffangstation braucht einen ruhigen Transfer ${targetHint}. An Bord ist ${cargoClean}; der Flug soll gleichmaessig bleiben, damit die Uebergabe am Ziel entspannt klappt.`
                : `Eine Auffangstation braucht einen ruhigen Tierschutzflug ${targetHint}. An Bord ist ${cargoClean}; der Flug soll gleichmaessig bleiben, damit die Uebergabe am Ziel entspannt klappt.`;
        }
    }
    if (profile.id === 'tour_guide_knowledge' && isPOI) {
        _sanitizeLearningGuideNarrative(m);
    }
    if (profile.id === 'sightseeing_tour' && isPOI) {
        _sanitizeSightseeingTourNarrative(m, true);
    }
    const cue = _profileStoryCue(profile, isPOI);
    if (cue) {
        const story = String(m.s || '').trim();
        if (story && _storyAlreadyCoversProfileCue(story, profile)) {
            // The generated story already carries the profile domain; avoid bolting on a generic cue.
        } else if (cue && story && !story.toLowerCase().includes(cue.toLowerCase())) {
            m.s = `${story} ${cue}`.trim();
        } else if (cue && !story) {
            m.s = cue;
        }
    }
    _finalizeMissionNarrative(m, profile, isPOI);
    if (m.passenger && typeof m.passenger === 'object') {
        m.passenger.storyHint = String(m.s || '').trim();
    }
    m.profileId = profile.id;
    return { mission: m, paxText, cargoText, appliedProfile: profile.id };
}

function _profileStoryCue(profile, isPOI = false) {
    if (!profile || profile.id === 'auto') return '';
    if (profile.id === 'news_coverage') {
        return isPOI
            ? 'Sachlicher Reporterflug mit konkretem sichtbarem Anlass am POI: Festbetrieb, Besucherandrang, Verkehr, Baustelle oder Ortsbild-Veränderung.'
            : '';
    }
    if (profile.id === 'sightseeing_tour') {
        return isPOI
            ? 'Persoenlicher Rundflug: Blick, Orientierung, Erinnerungsfotos und entspannte Rueckkehr stehen im Mittelpunkt.'
            : 'Entspannter Ausflugsflug mit angenehmem Ablauf am Ziel.';
    }
    if (profile.id === 'tour_guide_knowledge') {
        return isPOI
            ? 'Der Lern-Guide erklaert dir am Ziel kurze Fakten, Orientierung und Einordnung aus der Luft.'
            : '';
    }
    if (profile.id === 'historian_guided_tour') {
        return isPOI
            ? 'Am Ziel geht es um historische Ortslesart aus der Luft: Ortskern, alte Wege, Siedlungsform, Kirchen-/Marktplatzlage oder Tal-/Hanglage.'
            : 'Der Flug dient der historischen Einordnung des Zielorts mit ruhigem, stabilem Ablauf.';
    }
    return String(profile.storyCue || '').trim();
}

function _storyAlreadyCoversProfileCue(story, profile) {
    const s = String(story || '').toLowerCase();
    const id = String(profile?.id || '').toLowerCase();
    if (!s || !id) return false;
    const hasAny = (...patterns) => patterns.some(re => re.test(s));
    switch (id) {
        case 'mapping_survey':
            return hasAny(/\bvermess/, /\bsurvey\b/, /\bmapping\b/, /\blidar\b/, /\bphotogramm/, /\bdigital(?:er|en|e)?\s+zwilling/, /\bpunktwolke\b/, /\bdaten\b/, /\bpass(?:es)?\b/, /\bbahnen\b/);
        case 'cargo_fragile':
            return hasAny(/\bfracht\b/, /\bladung\b/, /\btransport\b/, /\bempfind/, /\bpräzision/, /\bpraezision/, /\bschutz/, /\bsto(?:ß|ss)/, /\bersch(?:ü|ue)tter/, /\bsanft/, /\bübergabe\b/, /\buebergabe\b/);
        case 'fire_watch':
            return hasAny(/\bbrand\b/, /\bwaldbrand\b/, /\brauch/, /\bhotspot/, /\bglut/, /\bfeuer\b/, /\bfrühwarn/, /\bfruehwarn/);
        case 'search_and_rescue':
            return hasAny(/\bsuch/, /\bsar\b/, /\brettung/, /\blagebild\b/, /\bvermisst/, /\bsignal/);
        case 'inspection_infra':
            return hasAny(/\binspektion/, /\bprüfung\b/, /\bpruefung\b/, /\bwartung/, /\bschaden/, /\bbauwerk/, /\bdokumentation/, /\bstörung\b/, /\bstoerung\b/, /\btrasse\b/, /\bumspannwerk\b/, /\bwindpark\b/, /\bsolarpark\b/, /\bmodulreihe\b/, /\bwechselrichter\b/, /\btrafopunkt\b/);
        case 'news_coverage':
            return hasAny(/\breporter/, /\bredaktion/, /\bbericht/, /\bberichterstattung/, /\bauffaenger\b/, /\baufhänger\b/, /\bverkehrslage\b/, /\bbesucher/, /\bfestbetrieb\b/, /\bbaustelle\b/, /\bortsbild\b/, /\blageeinschaetzung\b/, /\blageeinschätzung\b/);
        case 'media_photo':
            return hasAny(/\bfoto/, /\bfilm/, /\bkamera/, /\bluftbild/, /\bbildserie\b/, /\bestablishing/, /\baufmacherbild\b/, /\bortsmarketing\b/, /\btourismusbroschuere\b/, /\btourismusbroschüre\b/, /\bjubilaeumsfilm\b/, /\bjubiläumsfilm\b/, /\bgemeindeaufnahme\b/, /\bpr\b/);
        case 'science_geo':
            return hasAny(/\bgeolog/, /\brelief\b/, /\berosion\b/, /\bhangstruktur\b/, /\bgeomorph/, /\bsediment/, /\btalform\b/, /\babbruchkante\b/, /\buferkante\b/, /\bhangstabil/);
        case 'science_bio':
            return hasAny(/\bnatur/, /\bumwelt/, /\bbiolog/, /\bhabitat/, /\bflora/, /\bfauna/, /(?:oe|ö)kolog/, /vegetation/, /\bschilf/, /\bpflanzen/, /wissenschaft/, /\bgischt/, /\bgew(?:ae|ä)sser/, /\buferzone\b/, /\btrockenstress\b/, /\brastbereich\b/, /\bbrutbereich\b/, /\bmonitoring\b/);
        case 'tour_guide_knowledge':
            return hasAny(/\bfakten\b/, /\beinordnung\b/, /\borientierung\b/, /\bbildung\b/, /\blern/, /\bwissens/, /\bgeschichte\b/);
        case 'historian_guided_tour':
            return hasAny(/\bhistor/, /\bgeschichte\b/, /\bsiedlungsgeschichte\b/, /\bdorfgeschichte\b/, /\bzeitgeschichte\b/, /\bkulturgeschichte\b/, /\beinordnung\b/, /\barchiv/, /\bkarten\b/, /\bchronik/, /\bdenkmal/, /\bortsbild\b/, /\bortskern\b/, /\bsiedlungsform\b/, /\bkirchenlage\b/, /\bmarktplatzlage\b/, /\btallage\b/, /\bhanglage\b/);
        case 'sightseeing_tour':
            return hasAny(/\bausflug\b/, /\bblick\b/, /\baussicht\b/, /\bfoto/, /\berinnerung/, /\bpanorama/, /\brundflug/, /\bgast\b/, /\bgaeste\b/, /\bgäste\b/, /\bentspannt/);
        default:
            return false;
    }
}

function _profileOpsRuleForPrompt(profile, isPOI = false) {
    if (!profile || profile.id === 'auto') return '';
    if (profile.id === 'bush_scenic_hopper') {
        return '16. OPERATIONS-REGEL BUSH-ADVENTURE: Auftrag ist ein glaubwuerdiger Backcountry-Adventure- oder Wildnis-Transfer zu einem Remote Strip mit Landung am Ziel. Die Story MUSS dem Passagier einen konkreten persoenlichen Anlass geben, warum er genau dorthin will oder dort hinmuss (z.B. Fotoaufenthalt nach der Landung, Lodge, Rangerhuette, Trekking-Start, Canyon-Camp, Fluss- oder Angeltrip, abgelegene Verabredung, Huettennacht, Wildnisbesuch). Formuliere als konkreten Hinflug mit Ausstieg und Beginn des Bodenplans am Zielstrip; Beobachtungen aus dem Cockpit sind nur Anflugstimmung. Der Bush-Strip und die abgelegene Lage muessen in Story und greetingText spuerbar wichtig sein.';
    }
    if (profile.id === 'news_coverage' && !isPOI) {
        return '16. OPERATIONS-REGEL REPORTER A-B: Dies ist ein reiner Transport zum Zielflugplatz. KEIN Arbeitsauftrag in der Luft am Ziel, KEIN Kreisen, KEIN Verweilen/Überflug als Missionsziel. Die eigentliche Berichterstattung findet nach der Landung am Boden statt.';
    }
    if (profile.id === 'news_coverage' && isPOI) {
        return '16. OPERATIONS-REGEL REPORTER POI: Luftbeobachtung am POI ist erlaubt; Auftrag bleibt sachliche Berichterstattung. Gib einen konkreten sichtbaren Anlass, z.B. lokales Fest, Besucherandrang, Verkehrslage, Baustelle im Ortskern, Sperrung, neue Nutzung oder sichtbare Veraenderung. Bei POI-City keine "O-Toene sammeln"-Story und keine APT-/Bodenreporter-Transferlogik. Keine Touri-Rhetorik, keine Einsatzdramatisierung, keine technische Inspektion.';
    }
    if (profile.id === 'historian_guided_tour' && isPOI) {
        return '16. OPERATIONS-REGEL HISTORIKER POI: Auftrag ist ein ruhiger POI-Rundflug mit historischer Ortslesart. Nutze Rollen wie Ortsarchivarin, Denkmalpfleger, Heimatforscherin oder Stadtchronist. Bei City/Castle eignen sich Ortskern, Siedlungsform, alte Verkehrswege, Kirchen-/Marktplatzlage, Tal-/Hanglage, Burg-/Schlosslage, Bauachsen oder fruehere Nutzung als Erzaehlanker. Briefing/Greeting/Folgeansagen bleiben historisch-bildend. Kein SAR/Feuer/Inspektionsauftrag, keine allgemeine Sightseeing-Tour.';
    }
    if (profile.id === 'sightseeing_tour' && isPOI) {
        return '16. OPERATIONS-REGEL SIGHTSEEING POI: Auftrag ist ein persoenlicher, ruhiger Rundflug zum POI mit Blickmoment, Orientierung, Erinnerungsfotos und entspannter Rueckkehr. Schreibe keine Arbeits-, Erfassungs-, Dokumentations-, Lagebild-, Vermessungs-, Inspektions- oder Einsatzsprache. Keine Landung am POI andeuten. Nenne nach Moeglichkeit einen kleinen sozialen Anlass: Besuch, Freund/Familie, Geschenkflug, Heimatblick, Wochenendausflug oder persoenliche Fotos.';
    }
    if (profile.id === 'tour_guide_knowledge' && isPOI) {
        return '16. OPERATIONS-REGEL LERN-GUIDE POI: Rolle ist Wissensvermittlung fuer den Piloten: Der Guide erklaert Ziel, Gegend, Landschaft, Nutzung und sichtbare Referenzen mit kurzen Fakten. Der Guide ist nicht selbst in Ausbildung und fliegt nicht zur Vorbereitung spaeterer Touren. Keine Arbeitsanweisungen an den Piloten, keine feste Arbeitshoehe verlangen, keine technische Inspektions- oder Einsatzsprache. Bestaetigte visualLandmarks aus targetGeoContext/missionTruth duerfen als Orientierungshilfe genutzt werden, besonders bei unauffaelligen Zielen. Pro Ansage einen neuen Fakt oder eine neue Referenz bevorzugen. Keine Strommasten, Freileitungen, Windraeder, Bruecken, Fluesse, Autobahnen, Eisenbahnlinien, Gelaendemarken oder Tuerme erfinden, wenn sie nicht Ziel oder in targetGeoContext/missionTruth bestaetigt sind.';
    }
    if (profile.id === 'inspection_infra' && isPOI) {
        return '16. OPERATIONS-REGEL INSPEKTION POI: Auftrag ist technische Betreiberarbeit. Nutze Schäden, Sturmschaden-Check, Wartung, Störung, Baufortschritt, Wärmebild, Dach-/Bauwerks-/Trassenprüfung oder Dokumentation. Bei Brücken/Viadukten sind Pfeiler, Widerlager, Fundamente, Brückendeck, Unterführung/Hochstraße, Bahnviadukt, Sperrung oder Hochwasser an Pfeilern passende Varianten. Bei Staudamm/Talsperre/Stausee/Rueckhaltebecken bleibt das Wasserbauwerk Primärziel: Staumauer, Dammkrone, Ablaufbauwerk, Uferbefestigung, Pegel-/Schieberanlagen oder Hochwasserschutz. Windparks, Solarparks, Umspannwerke, Trassen, Funkmasten und Industrieanlagen sind ebenfalls passende Infra-Ziele: Rotor-/Turmbereich, Modulreihen, Wechselrichter, Trafopunkt, Leitung, Zaun, Zufahrt, Kranfläche oder Betriebsfläche dürfen den Anlass tragen. Zufahrt, Straße oder Strommast sind nur Lagehilfe/Support, wenn sie nicht selbst Ziel sind. Keine Geologie-/Relief-/Bodenforschungsstory, ausser das Ziel ist ausdrücklich Berg, Steinbruch, Hang oder Naturgebiet.';
    }
    if (profile.id === 'science_bio' && isPOI) {
        return '16. OPERATIONS-REGEL SCIENCE BIO POI: Auftrag ist biologische oder ökologische Beobachtung. Baue eine konkrete Fragestellung ein: Habitat, Vegetation, Uferzone, Wasserfarbe, Rast-/Brutbereiche, Trockenstress, Störfaktoren oder Monitoringvergleich. Der Luftblick soll Feldarbeit, Studie oder Naturschutz-Monitoring vorbereiten. Keine Technikinspektion, keine Schadensdiagnose an Bauwerken, keine SAR-/Feuerlage, keine reine Sightseeing-Tour. Keine harten Messwerte oder Artenfunde erfinden, wenn sie nicht aus dem Kontext kommen.';
    }
    if (profile.id === 'science_geo' && isPOI) {
        return '16. OPERATIONS-REGEL SCIENCE GEO POI: Auftrag ist geologische oder geomorphologische Beobachtung. Baue eine konkrete Fragestellung ein: Relief, Erosion, Hangstabilität, Sedimente, Uferkante, Abbruchkante, Talform, Steinbruch, alte Fließwege oder Geländekartierung. Der Luftblick soll Kartierung, Studie oder Bodenbegehung vorbereiten. Keine Bio-/Artenanalyse, keine Technikinspektion, keine SAR-/Feuerlage, keine reine Vermessungs- oder Sightseeing-Sprache.';
    }
    if (profile.id === 'media_photo' && isPOI) {
        return '16. OPERATIONS-REGEL FOTO/FILM POI: Auftrag ist eine verwertbare Bildserie mit erkennbarem Zweck und Auftraggeber: Tourismusbroschuere, Ortsmarketing, Gemeindeaufnahme, Immobilien-/Projektbild, Jubiläumsfilm, Redaktion, Betreiber, Dokumentation oder PR. Bei City geht es um Ortsbild, Lage, Wiedererkennungswert und Establishing Shots; bei Castle um Denkmal-/Burgmotiv und Umfeld. Nicht in Sightseeing kippen: keine persoenliche Ausflugserzaehlung, keine "Aussicht geniessen"-Sprache. Keine technische Diagnose, keine Geologie-/Reliefstory, keine Einsatzdramatisierung.';
    }
    return '';
}

function _pickFromWeighted(values = [], fallback = 'auto') {
    const src = Array.isArray(values) ? values.filter(Boolean) : [];
    if (!src.length) return fallback;
    return src[Math.floor(Math.random() * src.length)] || fallback;
}

function _pickFromWeightedWithRecentGuard(values = [], storageKey = '', { fallback = 'auto', recentLimit = 3 } = {}) {
    const src = Array.isArray(values) ? values.filter(Boolean) : [];
    if (!src.length) return fallback;

    const unique = [...new Set(src)];
    if (!storageKey || unique.length <= 1) return _pickFromWeighted(src, fallback);

    const guardLimit = Math.max(1, Math.min(parseInt(recentLimit, 10) || 1, unique.length - 1));
    let history = [];
    try {
        const parsed = JSON.parse(localStorage.getItem(storageKey) || '[]');
        if (Array.isArray(parsed)) history = parsed.map(x => String(x || '')).filter(Boolean);
    } catch (_) {
        history = [];
    }

    const recent = new Set(history.slice(-guardLimit));
    let pool = src.filter(id => !recent.has(String(id)));
    if (!pool.length) {
        pool = src;
        history = [];
    }

    const selected = _pickFromWeighted(pool, fallback);
    try {
        const nextHistory = history
            .filter(id => unique.includes(id))
            .concat(selected)
            .slice(-Math.max(unique.length, guardLimit + 1));
        localStorage.setItem(storageKey, JSON.stringify(nextHistory));
    } catch (_) {}

    return selected;
}

function _poiCategoryTaskPool(category = 'generic') {
    const c = String(category || 'generic').toLowerCase();
    // Kategorie bleibt fix, Task rotiert innerhalb passender Missionsfamilien.
    if (c === 'bridge' || c === 'dam' || c === 'industry') {
        return ['inspection_infra', 'inspection_infra', 'mapping_survey', 'media_photo', 'news_coverage', 'tour_guide_knowledge'];
    }
    if (c === 'road') {
        return ['inspection_infra', 'inspection_infra', 'mapping_survey', 'media_photo', 'news_coverage'];
    }
    if (c === 'telecom') {
        return ['inspection_infra', 'inspection_infra', 'mapping_survey', 'media_photo', 'news_coverage', 'tour_guide_knowledge'];
    }
    if (c === 'infrastructure') {
        return ['inspection_infra', 'inspection_infra', 'mapping_survey', 'media_photo', 'news_coverage', 'search_and_rescue'];
    }
    if (c === 'castle' || c === 'city') {
        return ['historian_guided_tour', 'historian_guided_tour', 'tour_guide_knowledge', 'sightseeing_tour', 'news_coverage'];
    }
    if (c === 'water') {
        return ['science_bio', 'science_bio', 'search_and_rescue', 'sightseeing_tour', 'historian_guided_tour', 'tour_guide_knowledge'];
    }
    if (c === 'mountain') {
        return ['science_geo', 'science_bio', 'sightseeing_tour', 'historian_guided_tour', 'search_and_rescue', 'mapping_survey', 'tour_guide_knowledge'];
    }
    if (c === 'fire') {
        return ['fire_watch', 'fire_watch', 'search_and_rescue'];
    }
    if (c === 'generic') {
        return ['mapping_survey', 'news_coverage', 'sightseeing_tour', 'historian_guided_tour'];
    }
    return ['mapping_survey', 'news_coverage'];
}

function pickAutoMissionTaskProfileId({ isPOI = false, selectedAptCategory = 'all', selectedPoiCategory = 'all', missionCat = '' } = {}) {
    const cat = String(missionCat || '').toLowerCase();
    const aptSel = String(selectedAptCategory || 'all').toLowerCase();
    const poiSel = String(selectedPoiCategory || 'all').toLowerCase();

    // Harte Picker-Regel fuer POI-Location-Filter:
    // Kategorie fix, Task daraus passend rotieren.
    if (isPOI && poiSel !== 'all' && poiSel !== 'trn') {
        const key = `ga_poi_auto_profile_history_${poiSel || cat || 'generic'}`;
        return _pickFromWeightedWithRecentGuard(_poiCategoryTaskPool(poiSel || cat), key, {
            fallback: 'mapping_survey',
            recentLimit: 3
        });
    }

    // Harte Picker-Regeln: explizite APT-Kategorien nicht mischen.
    if (!isPOI && (aptSel === 'club' || cat === 'club')) return 'club_utility';
    // "Cargo (ohne PAX)" bleibt bewusst ein eigener, neutraler Cargo-Flow.
    // "cargo_fragile" darf nur über den expliziten Fragile-Picker gewählt werden.
    if (!isPOI && (aptSel === 'cargo' || cat === 'cargo')) return 'auto';
    if (!isPOI && (aptSel === 'private')) return 'sightseeing_tour';

    const weighted = [];
    const pushMany = (id, n) => { for (let i = 0; i < n; i++) weighted.push(id); };

    if (isPOI) {
        if (poiSel === 'trn' || cat === 'trn') return 'auto';
        // POI Default-Mix (all): breit, aber profilerhaltend.
        pushMany('mapping_survey', 3);
        pushMany('news_coverage', 2);
        pushMany('inspection_infra', 2);
        pushMany('media_photo', 2);
        pushMany('search_and_rescue', 2);
        pushMany('fire_watch', 2);
        pushMany('sightseeing_tour', 1);
        pushMany('historian_guided_tour', 2);
        pushMany('tour_guide_knowledge', 2);
        pushMany('science_bio', 2);
        pushMany('science_geo', 1);
    } else {
        if (aptSel === 'trn' || cat === 'trn') return 'auto';
        if (aptSel === 'charter' || cat === 'charter') return 'auto';
        // APT Default-Mix
        pushMany('sightseeing_tour', 4);
        pushMany('news_coverage', 3);
        pushMany('cargo_fragile', 2);
        pushMany('animal_transport', 1);
        pushMany('medical_transfer', 2);
        pushMany('club_utility', 2);
        // Category-bias
        if (aptSel === 'cargo' || cat === 'cargo') {
            pushMany('club_utility', 2);
            pushMany('news_coverage', 1);
        }
        if (aptSel === 'private' || cat === 'std') {
            pushMany('sightseeing_tour', 2);
        }
        if (aptSel === 'club' || cat === 'club') {
            pushMany('club_utility', 3);
        }
    }

    if (!isPOI && aptSel === 'all' && (!cat || cat === 'all')) {
        let aptHistory = [];
        try {
            const parsed = JSON.parse(localStorage.getItem('ga_apt_auto_profile_history') || '[]');
            if (Array.isArray(parsed)) aptHistory = parsed;
        } catch (_) {
            aptHistory = [];
        }
        const effectiveWeighted = aptHistory.length
            ? weighted
            : weighted.filter(id => id !== 'animal_transport');
        return _pickFromWeightedWithRecentGuard(effectiveWeighted, 'ga_apt_auto_profile_history', {
            fallback: 'auto',
            recentLimit: 4
        });
    }

    if (isPOI && poiSel === 'all' && (!cat || cat === 'all')) {
        return _pickFromWeightedWithRecentGuard(weighted, 'ga_poi_auto_profile_history', {
            fallback: 'mapping_survey',
            recentLimit: 5
        });
    }

    return _pickFromWeighted(weighted, 'auto');
}

const ANIMAL_TRANSPORT_SCENE_OPTIONS = [
    { title: 'Seagull', label: 'Moewe', role: 'animal.waterfowl', keywords: /möwe|moewe|seagull|wildvogel|vogelstation/i },
    { title: 'Goose', label: 'Gans', role: 'animal.waterfowl', keywords: /gans|goose|wasservogel/i },
    { title: 'Goose', label: 'Gans', role: 'animal.waterfowl', keywords: /ente|enten|duck|mallard|schwan|swan|heimischer\s+wasservogel/i },
    { title: 'CHircusHircusFemale', label: 'Ziege', role: 'animal.grazing', keywords: /ziege|geiss|geiß|bock|goat|hircus/i },
    { title: 'CHircusHircusJuvenile', label: 'junge Ziege', role: 'animal.grazing', keywords: /kitz|jungziege|zicklein/i },
    { title: 'OHemionusJuvenile', label: 'junges Reh', role: 'animal.deer', keywords: /rehkitz|kitz|junges\s+reh/i },
    { title: 'OHemionusFemale', label: 'Reh', role: 'animal.deer', keywords: /reh|hirsch|wildtier|deer|\bwild\b/i },
    { visible: false, label: 'Schaf-Transportbox', cargoLabel: 'Schaf-Transportbox', cargoTitle: 'Pallet01_03', keywords: /schaf|sheep/i },
    { visible: false, label: 'Luchs-Transportbox', cargoLabel: 'Luchs-Transportbox', cargoTitle: 'Cardboard', keywords: /luchs|lux|lynx/i },
    { visible: false, label: 'Tiertransportbox', cargoLabel: 'Tiertransportbox', cargoTitle: 'Cardboard', keywords: /hund|katze|dackel|welpe|dog|cat/i },
    { visible: false, label: 'Auffangstations-Kiste', cargoLabel: 'Auffangstations-Kiste', cargoTitle: 'Pallet01_03', keywords: /seelöwe|seeloewe|seal|sealion/i },
    { visible: false, label: 'Pferde-Vet-Material', cargoLabel: 'Pferde-Vet-Material', cargoTitle: 'Pallet01_03', keywords: /pferd|gestuet|gestüt|horse/i }
];

function pickAnimalTransportSceneSpec(text = '') {
    const hay = String(text || '');
    const byText = ANIMAL_TRANSPORT_SCENE_OPTIONS.find(opt => opt.keywords && opt.keywords.test(hay));
    if (byText) return byText;
    return ANIMAL_TRANSPORT_SCENE_OPTIONS.find(opt => opt.label === 'Tiertransportbox')
        || ANIMAL_TRANSPORT_SCENE_OPTIONS.find(opt => opt.visible === false)
        || ANIMAL_TRANSPORT_SCENE_OPTIONS[0];
}

function animalTransportBoxLabel(animalSpec = null) {
    const cargoLabel = String(animalSpec?.cargoLabel || '').trim();
    if (cargoLabel) return cargoLabel;
    const label = String(animalSpec?.label || '').trim();
    if (label && !/transportbox|kiste|material/i.test(label)) return `${label}-Transportbox`;
    return label || 'Tiertransportbox';
}

function getMissionPlanV2Plan(missionPlanV2 = null) {
    if (!missionPlanV2 || typeof missionPlanV2 !== 'object') return null;
    if (String(missionPlanV2.status || '').toLowerCase() !== 'ready') return null;
    const plan = missionPlanV2.plan && typeof missionPlanV2.plan === 'object' ? missionPlanV2.plan : null;
    return plan || null;
}

function compactPoiKnowledgeFactListForMission(sourceFacts = [], maxFacts = 10, seenTexts = new Set()) {
    const limit = Math.max(0, Math.min(40, Math.round(Number(maxFacts) || 0)));
    const out = [];
    for (const fact of (Array.isArray(sourceFacts) ? sourceFacts : [])) {
        if (out.length >= limit) break;
        const clean = {
            source: String(fact?.source || 'wiki').replace(/\s+/g, ' ').trim() || 'wiki',
            topic: String(fact?.topic || 'general').replace(/\s+/g, ' ').trim() || 'general',
            text: String(fact?.text || fact || '').replace(/\s+/g, ' ').trim()
        };
        if (clean.text.length < 24) continue;
        const key = clean.text.toLowerCase();
        if (seenTexts.has(key)) continue;
        seenTexts.add(key);
        out.push(clean);
    }
    return out;
}

function compactPoiKnowledgeContextForMission(context = null, maxFacts = POI_KNOWLEDGE_CORE_FACT_LIMIT, options = {}) {
    if (!context || typeof context !== 'object') return null;
    const seenTexts = new Set();
    const facts = compactPoiKnowledgeFactListForMission(
        context.facts,
        Math.min(12, Math.round(Number(maxFacts) || POI_KNOWLEDGE_CORE_FACT_LIMIT)),
        seenTexts
    );
    const includeExtraFacts = options?.includeExtraFacts === true;
    const extraFacts = includeExtraFacts
        ? compactPoiKnowledgeFactListForMission(
            context.extraFacts,
            Math.min(24, Math.round(Number(options.maxExtraFacts) || POI_KNOWLEDGE_EXTRA_FACT_LIMIT)),
            seenTexts
        )
        : [];
    if (!facts.length && !context.ok && !context.status) return null;
    const num = value => Number.isFinite(Number(value)) ? Number(value) : null;
    const compact = {
        ok: context.ok === true,
        status: String(context.status || '').replace(/\s+/g, ' ').trim() || (context.ok ? 'accept' : 'unknown'),
        title: String(context.title || '').replace(/\s+/g, ' ').trim(),
        category: String(context.category || '').replace(/\s+/g, ' ').trim(),
        score: num(context.score),
        qid: String(context.qid || '').replace(/\s+/g, ' ').trim() || null,
        sourceUrl: String(context.sourceUrl || '').replace(/\s+/g, ' ').trim() || null,
        redirectedTo: String(context.redirectedTo || '').replace(/\s+/g, ' ').trim() || null,
        exactTitle: context.exactTitle === true,
        distanceKm: num(context.distanceKm),
        factCandidates: Number.isFinite(Number(context.factCandidates)) ? Math.round(Number(context.factCandidates)) : facts.length,
        selectedFacts: facts.length,
        topics: Array.isArray(context.topics)
            ? context.topics.map(x => String(x || '').replace(/\s+/g, ' ').trim()).filter(Boolean).slice(0, 8)
            : [],
        facts,
        warnings: Array.isArray(context.warnings)
            ? context.warnings.map(x => String(x || '').replace(/\s+/g, ' ').trim()).filter(Boolean).slice(0, 8)
            : [],
        rateLimited: context.rateLimited === true
    };
    if (includeExtraFacts && extraFacts.length) {
        compact.extraFacts = extraFacts;
        compact.extraSelectedFacts = extraFacts.length;
        compact.availableFacts = facts.length + extraFacts.length;
    }
    return compact;
}

function buildPoiKnowledgeBriefingBlock(missionData = null, passenger = null) {
    const md = missionData && typeof missionData === 'object' ? missionData : null;
    const pax = passenger || md?.passenger || md?.missionContract?.passenger || null;
    const taskDomain = String(pax?.taskDomain || md?.missionContract?.taskDomain || '').toLowerCase();
    if (taskDomain !== 'poi_learning_guide') return '';
    const context = md?.knowledgeContext || md?.missionContract?.knowledgeContext || pax?.knowledgeContext || null;
    if (!context || context.status !== 'accept') return '';
    const factCount = Math.max(
        Number.isFinite(Number(context.availableFacts)) ? Math.round(Number(context.availableFacts)) : 0,
        Number.isFinite(Number(context.selectedFacts)) ? Math.round(Number(context.selectedFacts)) : 0,
        Array.isArray(context.facts) ? context.facts.length : 0
    );
    if (factCount <= 0) return '';
    const target = String(context.title || md?.poiName || md?.targetName || 'Zielgebiet').replace(/\s+/g, ' ').trim();
    const paxName = String(pax?.name || 'Der Lern-Guide').replace(/\s+/g, ' ').trim();
    return `Guide-Hinweis: ${paxName} hat gesicherte Ortsfakten zu ${target} vorbereitet. Die Details kommen unterwegs als kurze Guide-Ansagen; das Briefing bleibt beim Rahmen des ruhigen Rundflugs.`;
}

function buildMissionContract({ isPOI = false, missionType = '', bushSpec = null, requestedProfileId = 'auto', appliedProfileId = 'auto', mission = null, passenger = null, paxText = '', cargoText = '', category = '', targetSceneOverride = undefined, sceneIntentOverride = undefined, sceneAccepted = true, targetGeoContext = null, missionTruth = null, aptArrivalPlan = null, missionPlanV2 = null, missionPlanV4 = null, missionContractV4 = null, knowledgeContext = null } = {}) {
    const normalizedMissionType = normalizeMissionType(missionType || mission?.missionType || passenger?.missionType || '', isPOI);
    const profileGroup = normalizedMissionType === 'bush' ? 'bush' : (normalizedMissionType === 'poi' ? 'poi' : 'apt');
    const profile = getMissionTaskProfile(appliedProfileId, profileGroup) || getMissionTaskProfile('auto', profileGroup);
    const taskDomain = String(passenger?.taskDomain || profile?.taskDomain || 'general').toLowerCase();
    const roleProfile = String(passenger?.roleProfile || profile?.roleProfile || 'general_passenger_v1').toLowerCase();
    const urgencyPriority = (String(passenger?.urgencyPriority || '').toLowerCase() === 'hoch') ? 'hoch' : 'niedrig';
    const title = String(mission?.t || mission?.title || '').trim();
    const story = String(mission?.s || mission?.story || '').trim();
    const rawTargetScene = targetSceneOverride !== undefined ? targetSceneOverride : (mission?.targetScene || passenger?.targetScene || null);
    const targetScene = sanitizeMissionTargetSceneSpec(rawTargetScene, { isPOI, taskDomain, targetGeoContext, missionPlanV2 });
    const sceneIntent = sanitizeMissionSceneIntentSpec(
        sceneIntentOverride !== undefined ? sceneIntentOverride : (mission?.sceneIntent || passenger?.sceneIntent || null),
        { isPOI, taskDomain }
    );
    const summaryBase = normalizedMissionType === 'bush'
        ? 'Bush-Einsatz'
        : (profile?.label || (isPOI ? 'POI-Einsatz' : 'A-B Einsatz'));
    const modeLabel = normalizedMissionType === 'bush' ? 'BUSH' : (isPOI ? 'POI' : 'A-B');
    const summary = `${summaryBase} | ${modeLabel} | cat:${String(category || 'std')}`;
    const constraints = [
        `Rollenkonsistenz: roleProfile=${roleProfile}, taskDomain=${taskDomain}, urgency=${urgencyPriority}`,
        'Kein Themenmix zwischen Auftrag, PAX und Fracht',
        'Alle Folgeansagen bleiben im gleichen Auftragsrahmen'
    ];
    const normalizedBushSpec = (normalizedMissionType === 'bush' || bushSpec || mission?.bush || passenger?.bush)
        ? sanitizeBushMissionSpec(bushSpec || mission?.bush || passenger?.bush || null)
        : null;
    const compactKnowledgeContext = compactPoiKnowledgeContextForMission(
        knowledgeContext || mission?.knowledgeContext || passenger?.knowledgeContext || null,
        10
    );
    return {
        missionType: normalizedMissionType,
        requestedProfileId: String(requestedProfileId || 'auto').toLowerCase(),
        appliedProfileId: String(appliedProfileId || 'auto').toLowerCase(),
        summary,
        taskDomain,
        roleProfile,
        urgencyPriority,
        paxText: String(paxText || ''),
        cargoText: String(cargoText || ''),
        missionTitle: title,
        missionStory: story,
        sceneIntent,
        sceneAccepted: !!sceneAccepted,
        targetGeoContext: targetGeoContext || mission?.targetGeoContext || passenger?.targetGeoContext || null,
        missionTruth: attachAptArrivalPlanToMissionTruth(missionTruth || mission?.missionTruth || passenger?.missionTruth || null, aptArrivalPlan),
        missionPlanV2: missionPlanV2 || mission?._missionPlanV2 || mission?.missionPlanV2 || passenger?.missionPlanV2 || null,
        missionPlanV4: missionPlanV4 || mission?._missionPlanV4 || mission?.missionPlanV4 || passenger?.missionPlanV4 || null,
        missionContractV4: missionContractV4 || mission?._missionContractV4 || mission?.missionContractV4 || passenger?.missionContractV4 || null,
        knowledgeContext: compactKnowledgeContext,
        missionVariety: mission?.missionVariety
            || missionContractV4?.pickupCreativeBrief?.variety
            || missionContractV4?.missionVarietyBrief?.variety
            || missionContractV4?.variety
            || missionPlanV4?.variety
            || missionPlanV2?.variety
            || null,
        aptArrivalPlan: aptArrivalPlan || mission?.aptArrivalPlan || passenger?.aptArrivalPlan || null,
        sarHeli: missionSarHeliSpecFromMission(mission) || null,
        bush: normalizedBushSpec,
        targetScene,
        constraints
    };
}

const MISSION_SURVEY_PATTERN_DEFAULTS = {
    altitudeToleranceFt: 300,
    scan: {
        lineCount: 4,
        lineLengthNm: 1.6,
        lineSpacingNm: 0.35,
        crossTrackToleranceNm: 0.10,
        headingToleranceDeg: 35,
        minCoverage: 0.82,
        bins: 24,
        startEndTolerance: 0.18,
        resetGraceSec: 5,
        minGroundSpeedKts: 45
    },
    orbit: {
        radiusNm: 0.55,
        radialToleranceNm: 0.12,
        requiredTurns: 3,
        sectorsPerTurn: 36,
        minTurnCoverage: 0.86,
        resetGraceSec: 5,
        minGroundSpeedKts: 45,
        minTurnSec: 45
    }
};

function missionSurveyPatternTargetPoint(missionData = null, contract = null) {
    const md = missionData && typeof missionData === 'object' ? missionData : {};
    const c = contract && typeof contract === 'object' ? contract : {};
    const truth = md.missionTruth || c.missionTruth || null;
    const main = truth?.mainTarget || null;
    const anchor = truth?.sceneAnchor || null;
    const sources = [
        main,
        anchor,
        { name: md.targetName || md.poiName, lat: md.targetLat, lon: md.targetLon },
        { name: md.poiName, lat: md.dest?.lat, lon: md.dest?.lon }
    ];
    for (const src of sources) {
        const lat = Number(src?.lat);
        const lon = Number(src?.lon ?? src?.lng);
        if (Number.isFinite(lat) && Number.isFinite(lon)) {
            return {
                name: String(src?.name || md.targetName || md.poiName || 'Zielgebiet').trim() || 'Zielgebiet',
                lat,
                lon,
                source: src === main ? 'missionTruth.mainTarget' : (src === anchor ? 'missionTruth.sceneAnchor' : 'missionData')
            };
        }
    }
    return null;
}

function missionSurveyPatternCategory(missionData = null, contract = null) {
    const md = missionData && typeof missionData === 'object' ? missionData : {};
    const c = contract && typeof contract === 'object' ? contract : {};
    const truth = md.missionTruth || c.missionTruth || {};
    return String(
        truth.primaryCategory
        || truth.poiCategory
        || truth.requestedCategory
        || c.category
        || c.poiCategory
        || c.requestedCategory
        || md.poiCategory
        || md.category
        || md.requestedCategory
        || ''
    ).toLowerCase();
}

function missionSurveyPatternTypeForTarget(missionData = null, contract = null) {
    const md = missionData && typeof missionData === 'object' ? missionData : {};
    const c = contract && typeof contract === 'object' ? contract : {};
    const truth = md.missionTruth || c.missionTruth || {};
    const category = missionSurveyPatternCategory(md, c);
    const geometryMode = String(truth.geometryMode || '').toLowerCase();
    if (/^(area|corridor|facility|broad_infrastructure)$/.test(geometryMode)) return 'north_south_scan';
    if (/^(city|town|village|settlement|generic|water|lake|river|canal|forest|mountain|industry|infrastructure|road|rail|dam|fire)$/.test(category)) {
        return 'north_south_scan';
    }
    return 'orbit';
}

function buildMissionSurveyPatternScanLines(center, scan = {}) {
    const lineCount = Math.max(1, Math.min(8, Math.round(Number(scan.lineCount || MISSION_SURVEY_PATTERN_DEFAULTS.scan.lineCount))));
    const lineLengthNm = Math.max(0.4, Math.min(5, Number(scan.lineLengthNm || MISSION_SURVEY_PATTERN_DEFAULTS.scan.lineLengthNm)));
    const lineSpacingNm = Math.max(0.12, Math.min(1.2, Number(scan.lineSpacingNm || MISSION_SURVEY_PATTERN_DEFAULTS.scan.lineSpacingNm)));
    const halfLen = lineLengthNm / 2;
    const mid = (lineCount - 1) / 2;
    const out = [];
    for (let i = 0; i < lineCount; i++) {
        const offsetNm = (i - mid) * lineSpacingNm;
        const base = Math.abs(offsetNm) > 0.0001
            ? getDestinationPoint(center.lat, center.lon, Math.abs(offsetNm), offsetNm >= 0 ? 90 : 270)
            : { ...center };
        const north = getDestinationPoint(base.lat, base.lon, halfLen, 0);
        const south = getDestinationPoint(base.lat, base.lon, halfLen, 180);
        out.push({
            id: `S${i + 1}`,
            label: `Survey-Linie ${i + 1}`,
            start: { lat: Math.round(north.lat * 1000000) / 1000000, lon: Math.round(north.lon * 1000000) / 1000000 },
            end: { lat: Math.round(south.lat * 1000000) / 1000000, lon: Math.round(south.lon * 1000000) / 1000000 }
        });
    }
    return out;
}

function buildMissionSurveyPatternSpec({ missionData = null, missionContract = null, passenger = null } = {}) {
    const md = missionData && typeof missionData === 'object' ? missionData : null;
    const contract = missionContract && typeof missionContract === 'object' ? missionContract : (md?.missionContract || null);
    const pax = passenger && typeof passenger === 'object' ? passenger : (md?.passenger || null);
    const taskDomain = String(pax?.taskDomain || contract?.taskDomain || '').toLowerCase();
    if (taskDomain !== 'mapping_survey') return null;
    const isPoiTask = !!(md?.isPOI || md?.poiName || md?.poiPresentation || missionUsesPoiTaskRecipe(md));
    if (!isPoiTask) return null;
    const target = missionSurveyPatternTargetPoint(md, contract);
    if (!target) return null;
    const type = missionSurveyPatternTypeForTarget(md, contract);
    const category = missionSurveyPatternCategory(md, contract);
    const targetAltFt = Math.max(0, Math.round(Number(pax?.targetAltFt || 0)));
    const center = {
        lat: Math.round(Number(target.lat) * 1000000) / 1000000,
        lon: Math.round(Number(target.lon) * 1000000) / 1000000
    };
    const scan = { ...MISSION_SURVEY_PATTERN_DEFAULTS.scan };
    if (/^(city|town|village|settlement|industry|infrastructure|dam)$/.test(category)) {
        scan.lineCount = 5;
        scan.lineLengthNm = 1.9;
        scan.lineSpacingNm = 0.35;
    } else if (/^(road|rail|river|canal)$/.test(category)) {
        scan.lineCount = 3;
        scan.lineLengthNm = 2.2;
        scan.lineSpacingNm = 0.32;
    } else if (/^(water|lake|forest|mountain|fire)$/.test(category)) {
        scan.lineCount = 4;
        scan.lineLengthNm = 2.0;
        scan.lineSpacingNm = 0.42;
    }
    scan.lines = buildMissionSurveyPatternScanLines(center, scan);
    const orbit = { ...MISSION_SURVEY_PATTERN_DEFAULTS.orbit };
    if (/^(castle|church|religious|monument|stadium|telecom|tower)$/.test(category)) {
        orbit.radiusNm = 0.45;
        orbit.radialToleranceNm = 0.10;
    } else if (category === 'bridge') {
        orbit.radiusNm = 0.50;
        orbit.radialToleranceNm = 0.11;
    }
    return {
        schema: 'ga.surveyPattern.v1',
        enabled: true,
        key: [
            'survey',
            String(md?.missionId || md?.missionKey || md?.targetName || md?.poiName || 'mission').replace(/[^a-zA-Z0-9_-]+/g, '-').slice(0, 48),
            type,
            center.lat.toFixed(5),
            center.lon.toFixed(5)
        ].join(':'),
        taskDomain: 'mapping_survey',
        type,
        label: type === 'orbit' ? 'Survey-Orbit' : 'Nord-Sued-Scan',
        targetLabel: target.name,
        targetSource: target.source,
        category,
        center,
        targetAltFt,
        altitudeToleranceFt: MISSION_SURVEY_PATTERN_DEFAULTS.altitudeToleranceFt,
        scan,
        orbit,
        completion: {
            mode: type === 'orbit' ? 'all_turns' : 'all_lines',
            returnToBaseOnComplete: true
        }
    };
}

function attachMissionSurveyPattern(missionData = null, missionContract = null, passenger = null) {
    const md = missionData && typeof missionData === 'object' ? missionData : null;
    const contract = missionContract && typeof missionContract === 'object' ? missionContract : md?.missionContract || null;
    const spec = buildMissionSurveyPatternSpec({ missionData: md, missionContract: contract, passenger });
    if (!spec) {
        if (md && md.surveyPattern) delete md.surveyPattern;
        if (contract && contract.surveyPattern) delete contract.surveyPattern;
        return null;
    }
    if (md) md.surveyPattern = spec;
    if (contract) contract.surveyPattern = spec;
    return spec;
}
window.buildMissionSurveyPatternSpec = buildMissionSurveyPatternSpec;
window.attachMissionSurveyPattern = attachMissionSurveyPattern;

function pickFireWatchExtent(truth, hazardLevel) {
    if (truth !== 'fire') return 'false_alarm';
    const h = Number.isFinite(Number(hazardLevel)) ? Number(hazardLevel) : 3;
    const r = Math.random();
    if (h >= 4) {
        if (r < 0.22) return 'major_fire';
        if (r < 0.58) return 'multi_smoke';
        return 'single_smoke';
    }
    if (h >= 3) {
        if (r < 0.12) return 'major_fire';
        if (r < 0.42) return 'multi_smoke';
        return 'single_smoke';
    }
    if (r < 0.05) return 'major_fire';
    if (r < 0.25) return 'multi_smoke';
    return 'single_smoke';
}

function fireWatchSiteCountForExtent(extent) {
    if (extent === 'major_fire') return 3;
    if (extent === 'multi_smoke') return 2;
    if (extent === 'single_smoke') return 1;
    return 0;
}

function buildFireWatchSmokeSites(dest, altFt, heading, extent) {
    const siteCount = fireWatchSiteCountForExtent(extent);
    if (!siteCount) return [];
    const baseBearing = Number.isFinite(Number(heading)) ? Number(heading) : Math.random() * 360;
    const sites = [];
    for (let i = 0; i < siteCount; i++) {
        const bearing = (baseBearing + 55 + i * 125 + Math.random() * 55) % 360;
        const distM = i === 0 ? Math.random() * 35 : (260 + i * 170 + Math.random() * 160);
        const p = getDestinationPoint(Number(dest.lat), Number(dest.lon), distM / 1852, bearing);
        const denseMajor = extent === 'major_fire';
        sites.push({
            siteId: `smoke-${i + 1}`,
            label: siteCount === 1 ? 'Rauchentwicklung' : `Rauchentwicklung ${i + 1}`,
            objectTitle: 'Chimney_Smoke_V1',
            lat: Number(p.lat),
            lon: Number(p.lon),
            altFt,
            hdg: Math.round((baseBearing + i * 35) % 360),
            count: denseMajor ? 9 : 8,
            radiusM: denseMajor ? 55 : 35
        });
    }
    return sites;
}

function buildFireWatchFireSites(smokeSites, extent, fireConfig = {}) {
    if (!Array.isArray(smokeSites) || smokeSites.length === 0) return [];
    const n = extent === 'major_fire' ? Math.min(2, smokeSites.length) : (extent === 'multi_smoke' ? 1 : 0);
    const ladderTest = fireConfig.testMode === 'offset_ladder' || fireConfig.testMode === 'fire_only_ladder';
    if (!n && !ladderTest) return [];
    const objectTitle = String(fireConfig.objectTitle || 'VO_Fire_R1_40').trim() || 'VO_Fire_R1_40';
    const altOffsetFt = Number.isFinite(Number(fireConfig.altOffsetFt)) ? Math.round(Number(fireConfig.altOffsetFt)) : 0;
    const count = Number.isFinite(Number(fireConfig.count)) ? Math.max(1, Math.min(6, Math.round(Number(fireConfig.count)))) : (extent === 'major_fire' ? 2 : 1);
    const radiusM = Number.isFinite(Number(fireConfig.radiusM)) ? Math.max(0, Math.min(80, Math.round(Number(fireConfig.radiusM)))) : (count > 1 ? 8 : 0);
    if (ladderTest) {
        const base = smokeSites[0];
        const offsets = [80, 40, 0, -40, -80, -120];
        return offsets.map((offset, idx) => {
            const sideM = (idx - (offsets.length - 1) / 2) * 55;
            const p = getDestinationPoint(Number(base.lat), Number(base.lon), Math.abs(sideM) / 1852, sideM >= 0 ? 90 : 270);
            return {
                siteId: `fire-offset-${offset}`,
                smokeSiteId: base.siteId,
                label: `Fire Offset ${offset} ft`,
                objectTitle,
                lat: Number(p.lat),
                lon: Number(p.lon),
                altFt: base.altFt,
                altOffsetFt: offset,
                hdg: base.hdg || 0,
                count: 1,
                radiusM: 0
            };
        });
    }
    return smokeSites.slice(0, n).map((site, idx) => ({
        siteId: `fire-${idx + 1}`,
        smokeSiteId: site.siteId,
        objectTitle,
        lat: site.lat,
        lon: site.lon,
        altFt: site.altFt,
        altOffsetFt,
        hdg: site.hdg || 0,
        count,
        radiusM
    }));
}

function missionAllowsFireWatchScenario({ mission = null, passenger = null } = {}) {
    const taskDomain = String(passenger?.taskDomain || mission?.passenger?.taskDomain || '').toLowerCase();
    const profileId = String(passenger?.roleProfile || mission?.profileId || mission?._appliedProfile || mission?._requestedProfile || '').toLowerCase();
    if (taskDomain === 'fire_watch' || profileId === 'fire_watch') return true;
    if (/(mapping|survey|photogrammetry|sightseeing|tour_guide|cargo|medical|search_and_rescue|rescue|sar)/.test(`${taskDomain} ${profileId}`)) return false;
    const titleStory = normalizeMissionText(`${mission?.t || ''} ${mission?.s || ''}`);
    return /(waldbrand|feuerwacht|rauchfahne|rauchentwicklung|brandherd|brandmeldung|hotspot|fire watch|smoke report)/.test(titleStory);
}

function missionDataAllowsFireWatchScenario(md = null, passenger = null, contract = null) {
    if (!md || typeof md !== 'object') return false;
    return missionAllowsFireWatchScenario({
        passenger: passenger || md?.passenger || contract?.passenger || null,
        mission: {
            t: md?.mission || contract?.missionTitle || contract?.summary || '',
            s: [contract?.missionStory, contract?.summary, md?.poiName, md?.targetName].filter(Boolean).join(' '),
            passenger: passenger || md?.passenger || contract?.passenger || null,
            profileId: contract?.appliedProfileId || contract?.requestedProfileId || md?.appliedProfile || md?.profile || ''
        }
    });
}

function buildFireWatchScenario({ isPOI = false, mission = null, passenger = null, dest = null, poiTerrainFt = null, heading = 0, fireHazard = null } = {}) {
    const isFireMission = isPOI && missionAllowsFireWatchScenario({ mission, passenger });
    if (!isFireMission || !dest || !Number.isFinite(Number(dest.lat)) || !Number.isFinite(Number(dest.lon))) return null;

    const hazardLevel = Number(fireHazard?.level);
    const fireProbability = Number.isFinite(hazardLevel)
        ? Math.max(0.25, Math.min(0.82, 0.18 + hazardLevel * 0.13))
        : 0.55;
    const debugTruthOverride = (typeof window.fireMissionTruthOverride === 'function')
        ? window.fireMissionTruthOverride()
        : null;
    const truth = debugTruthOverride || (Math.random() < fireProbability ? 'fire' : 'false_alarm');
    const debugExtentOverride = (typeof window.fireMissionExtentOverride === 'function')
        ? window.fireMissionExtentOverride()
        : null;
    const extent = (truth === 'fire' && debugExtentOverride && debugExtentOverride !== 'false_alarm')
        ? debugExtentOverride
        : pickFireWatchExtent(truth, hazardLevel);
    const altFt = Number.isFinite(Number(poiTerrainFt))
        ? Math.max(0, Math.round(Number(poiTerrainFt)))
        : Math.max(0, Math.round(Number(dest.elevation ?? currentDestElev ?? currentDepElev ?? 0)));
    const missionId = `fire-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const smokeSites = buildFireWatchSmokeSites(dest, altFt, heading, extent);
    const fireConfig = (typeof window.fireMissionFireOverride === 'function')
        ? (window.fireMissionFireOverride() || {})
        : {};
    const fireSites = buildFireWatchFireSites(smokeSites, extent, fireConfig);
    const fireObjectTitle = String(fireConfig.objectTitle || 'VO_Fire_R1_40').trim() || 'VO_Fire_R1_40';
    const fireAltOffsetFt = Number.isFinite(Number(fireConfig.altOffsetFt)) ? Math.round(Number(fireConfig.altOffsetFt)) : 0;

    return {
        enabled: true,
        type: 'fire_watch',
        missionId,
        truth,
        extent,
        smokeSiteCount: smokeSites.length,
        fireSiteCount: fireSites.length,
        state: 'enroute',
        createdAt: Date.now(),
        debugOverride: [debugTruthOverride || null, debugExtentOverride || null].filter(Boolean).join(',') || null,
        fireProbability: Math.round(fireProbability * 100) / 100,
        paxAwarenessRangeNm: 4,
        confirmRangeNm: 2,
        targetAreaNm: Number(passenger?.targetRadiusNm || 1.5) || 1.5,
        searchDwellSec: Math.max(120, Math.round(Number(passenger?.targetDwellMin || 3) * 60)),
        assessmentDwellSec: 240,
        target: {
            name: String(dest.n || dest.name || 'Zielgebiet'),
            lat: Number(dest.lat),
            lon: Number(dest.lon),
            altFt
        },
        smoke: {
            objectTitle: 'Chimney_Smoke_V1',
            lat: Number(dest.lat),
            lon: Number(dest.lon),
            altFt,
            hdg: Number.isFinite(Number(heading)) ? Math.round(Number(heading)) : 0,
            count: smokeSites[0]?.count || 0,
            radiusM: smokeSites[0]?.radiusM || 0,
            sites: smokeSites,
            spawned: false,
            spawnRequestedAt: 0,
            clearRequestedAt: 0
        },
        fire: {
            enabled: fireSites.length > 0,
            objectTitle: fireObjectTitle,
            altOffsetFt: fireAltOffsetFt,
            count: Number.isFinite(Number(fireConfig.count)) ? Math.round(Number(fireConfig.count)) : null,
            radiusM: Number.isFinite(Number(fireConfig.radiusM)) ? Math.round(Number(fireConfig.radiusM)) : null,
            testMode: fireConfig.testMode || null,
            sites: fireSites
        },
        observations: []
    };
}

function missionMatchesTaskProfile(missionLike, profileId, isPOI = false) {
    const id = String(profileId || 'auto').toLowerCase();
    if (!id || id === 'auto') return true;
    const expectedProfile = getMissionTaskProfile(id, isPOI ? 'poi' : 'apt') || null;
    const t = normalizeMissionText(missionLike?.t || missionLike?.title || '');
    const s = normalizeMissionText(missionLike?.s || missionLike?.story || '');
    const hay = `${t} ${s}`;
    const has = (re) => re.test(hay);
    const conflictsWithProfile = (profile) => {
        if (profile === 'sightseeing_tour') return has(/\bverein|vereins|ersatzteil|pumpe|werkzeug|mechaniker|fracht|kurier|medizin|tierschutz|training|fluglehrer/);
        if (profile === 'cargo_fragile') return has(/\bverein|vereins|stammtisch|fly in|sightseeing|panorama|kuchen|burger|wellness|tour|konzert|city\b/);
        if (profile === 'animal_transport') return has(/\bverein|vereins|ersatzteil|pumpe|werkzeug|sightseeing|panorama|training|fluglehrer/);
        if (profile === 'medical_transfer') return has(/\bverein|vereins|sightseeing|panorama|kuchen|burger|tierschutz|tiertransport/);
        if (profile === 'news_coverage') return has(/\bverein|vereins|ersatzteil|pumpe|werkzeug|tierschutz|tiertransport|training|fluglehrer/);
        return false;
    };
    const rp = String(missionLike?.passenger?.roleProfile || '').toLowerCase().trim();
    const td = String(missionLike?.passenger?.taskDomain || '').toLowerCase().trim();
    if (expectedProfile && (rp || td)) {
        const rpOk = !expectedProfile.roleProfile || rp === String(expectedProfile.roleProfile || '').toLowerCase();
        const tdOk = !expectedProfile.taskDomain || td === String(expectedProfile.taskDomain || '').toLowerCase();
        if (rpOk && tdOk && !conflictsWithProfile(id)) return true;
    }

    if (id === 'medical_transfer') {
        return has(/organtransport|medicine emergency|medizin|medical|notfall|blut|plasma|anti serum|klinik|arzt|notarzt|labor kurier/);
    }
    if (id === 'cargo_fragile') {
        return has(/aog|ersatzteil|fracht|transport|kurier|urgent mail|high priority courier|archive transport|art transfer|uhren|flower delivery|labor/);
    }
    if (id === 'animal_transport') {
        return has(/(^|[^a-zäöüß])(animal|tier|tiertransport|tierrettung|tierarzt|hund|hunderettung|welpen|katze|ziege|reh|hirsch|möwe|moewe|gans|ente|enten|schwan|pferd|wildvogel|auffangstation|horse vet)(?=$|[^a-zäöüß])/);
    }
    if (id === 'news_coverage') {
        if (isPOI) return has(/report|redaktion|medien|kamera|dreh|event|fest|besucher|verkehr|stau|baustell|lage|aufhaenger|aufhänger|dokument|live|beobacht|ortsbild|veraender|veränder/);
        return has(/report|medien|kamera|dreh|event|verkehr|stau|city|festival|skydiver/);
    }
    if (id === 'sightseeing_tour') {
        const positive = has(/ausflug|stadtetrip|stadttrip|sightseeing|panorama|rundflug|aussicht|kuchen|burger|wellness|romant|tour/);
        const negative = has(/aog|ersatzteil|organtransport|medicine|notfall|urgent|kurier|fracht|transport/);
        return positive && !negative;
    }
    if (id === 'tour_guide_knowledge') {
        const positive = has(/bildungsflug|wissensflug|lernflug|fakten|einordnung|hintergrund|geschichte des ortes|kultur|reiseguide|ortskunde/);
        const negative = has(/sar|search|rescue|rettung|hotspot|brand|rauch|feuer|notfall|inspekt|schaden|riss|vermess/);
        return positive && !negative;
    }
    if (id === 'historian_guided_tour') {
        const positive = has(/histor|geschichte|zeitreise|denkmal|kultur|stadtfuehr|stadtfuehrung|stadtchron|ortschron|heimatforsch|ortsarchiv|archiv|ortskern|ortsbild|siedlungsform|alte wege|verkehrsweg|kirchenlage|marktplatzlage|tal|hang|schloss|burg|turm|fluss|berg/);
        const negative = has(/sar|search|rescue|rettung|hotspot|brand|rauch|feuer|notfall/);
        return positive && !negative;
    }
    if (id === 'science_bio') {
        const positive = has(/biolog|oekolog|ökolog|naturschutz|umwelt|vegetation|fauna|flora|habitat|gewasser|gewaesser|uferzone|trockenstress|rastbereich|brutbereich|monitoring|schilf|feucht/);
        const negative = has(/sar|search|rescue|rettung|hotspot|brand|rauch|feuer|notfall/);
        return positive && !negative;
    }
    if (id === 'science_geo') {
        const positive = has(/geolog|geomorph|erosion|relief|hang|sediment|gestein|tal|berg|bruchkante|uferkante|abbruchkante|talform|hangstabil|fliessweg|fließweg|gelaende|gelände/);
        const negative = has(/sar|search|rescue|rettung|hotspot|brand|rauch|feuer|notfall/);
        return positive && !negative;
    }
    if (id === 'mapping_survey') {
        return has(/scan|vermess|lidar|photogram|kartier|topo|mess|dokumentation/);
    }
    if (id === 'inspection_infra') {
        return has(/inspekt|prüfung|pruef|wartung|schaden|sturm|stör|stoer|baufortschritt|zustand|waermebild|wärmebild|brueck|bruck|viadukt|pfeiler|widerlager|fundament|sperrung|unterfuehr|unterführ|hochstrass|hochstraß|damm|talsperre|industrie|anlage|infrastruktur|trasse|umspannwerk|windpark|windkraft|windrad|solarpark|solaranlage|photovoltaik|modulreihe|wechselrichter|trafopunkt/);
    }
    if (id === 'media_photo') {
        const positive = has(/foto|film|kamera|luftbild|aufnahmen|bildserie|shots|establishing|dreh|pr|medien|redaktion|aufmacher|tourismus|ortsmarketing|gemeinde|jubilaeum|jubiläum|immobilien|jahresbericht|firmen|doku/);
        const negative = has(/sar|search|rescue|rettung|hotspot|brand|rauch|feuer|notfall/);
        return positive && !negative;
    }
    if (id === 'search_and_rescue') {
        return has(/sar|search|rescue|rettung|vermisst|suchmuster|einsatz|lagebild|polizei support/);
    }
    if (id === 'fire_watch') {
        return has(/brand|rauch|hotspot|feuer|waldbrand|fruhwarn|aufklar/);
    }
    return true;
}

function _pickUniqueTrainingItems(pool, count, used = new Set()) {
    const src = Array.isArray(pool) ? pool.filter(Boolean) : [];
    const shuffled = src
        .filter(item => !used.has(item))
        .sort(() => Math.random() - 0.5);
    const out = [];
    for (const item of shuffled) {
        out.push(item);
        used.add(item);
        if (out.length >= count) break;
    }
    return out;
}

function _isPatternFocusItem(text) {
    const s = String(text || '').toLowerCase();
    return /pattern|platzrunde|touch|go-around|missed|no-flap|engine-out|anflug|landung|final/.test(s);
}

function buildDistributedTrainingPlan(seedMode = 'airwork') {
    const totalCount = 2 + Math.floor(Math.random() * 3); // 2..4
    const preferPattern = String(seedMode || '').toLowerCase() === 'pattern';
    let patternCount = 0;

    if (preferPattern) {
        patternCount = Math.min(totalCount - 1, totalCount >= 4 ? 2 : 1);
    } else if (totalCount >= 3 && Math.random() < 0.55) {
        // Airwork bleibt dominant, aber oft mit einer Landeuebung gemischt.
        patternCount = 1;
    }
    const airworkCount = Math.max(1, totalCount - patternCount);
    const used = new Set();
    const focus = [
        ..._pickUniqueTrainingItems(TRAINING_AIRWORK_ITEMS, airworkCount, used),
        ..._pickUniqueTrainingItems(TRAINING_PATTERN_ITEMS, patternCount, used)
    ];
    const mode = patternCount > 0 ? 'pattern' : 'airwork';
    const trigger = mode === 'pattern' ? 'five_nm_before_landing' : 'half_route';
    const instructorLine = mode === 'pattern'
        ? 'Wir machen erst die Uebungen in der Luft und gehen dann in eine Landeuebung am Platz.'
        : 'Wir bleiben heute beim Airwork: sauber, ruhig und mit klarem Ablauf.';
    return { mode, trigger, focus, instructorLine };
}

function sanitizeTrainingPlan(rawPlan, isTrainingMission) {
    if (!isTrainingMission) return null;
    if (!rawPlan || typeof rawPlan !== 'object') {
        return buildDistributedTrainingPlan('airwork');
    }
    const modeRaw = String(rawPlan.mode || '').toLowerCase();
    const requestedMode = (modeRaw === 'airwork' || modeRaw === 'pattern') ? modeRaw : 'airwork';
    const focusRaw = Array.isArray(rawPlan.focus) ? rawPlan.focus : [];
    let focus = focusRaw
        .map(x => String(x || '').trim())
        .filter(Boolean)
        .slice(0, 4);
    // Trainingsvielfalt erzwingen: insgesamt 2-4 Manoever, oft Airwork + optional 1 Pattern.
    if (focus.length < 2) {
        const fallback = buildDistributedTrainingPlan(requestedMode);
        focus = fallback.focus;
    } else {
        const hasPattern = focus.some(_isPatternFocusItem);
        if (!hasPattern && focus.length >= 3 && requestedMode === 'airwork' && Math.random() < 0.45) {
            const add = _pickUniqueTrainingItems(TRAINING_PATTERN_ITEMS, 1, new Set(focus));
            focus = focus.concat(add).slice(0, 4);
        }
    }
    const mode = focus.some(_isPatternFocusItem) ? 'pattern' : requestedMode;
    const triggerRaw = String(rawPlan.trigger || '').toLowerCase();
    const trigger = (triggerRaw === 'half_route' || triggerRaw === 'five_nm_before_landing')
        ? triggerRaw
        : (mode === 'pattern' ? 'five_nm_before_landing' : 'half_route');
    const instructorLine = String(rawPlan.instructorLine || '').trim().slice(0, 220);
    const instructorFallback = mode === 'pattern'
        ? 'Heute mit gemischtem Programm: Airwork im Uebungsgebiet, dann eine saubere Landeuebung am Platz.'
        : 'Heute konzentrieren wir uns auf Airwork mit ruhigem, sauberem Ablauf.';
    return { mode, trigger, focus, instructorLine: instructorLine || instructorFallback };
}

function formatPaxBriefingText(paxText, passenger) {
    const base = String(paxText || '').trim();
    const name = String(passenger?.name || '').trim();
    const role = String(passenger?.role || '').trim();
    if (!base || !name) return base;
    if (/^\s*0\s*PAX\b/i.test(base)) return base;
    if (base.toLowerCase().includes(name.toLowerCase())) return base;
    const m = base.match(/^(.*)\(([^)]*)\)\s*$/);
    if (m) {
        const left = String(m[1] || '').trim();
        const inner = String(m[2] || '').trim();
        const descriptor = role || inner;
        if (!descriptor) return `${left} (${name})`.trim();
        return `${left} (${descriptor}: ${name})`.trim();
    }
    return `${base} (${name})`;
}

function buildBushPickupStoryHint({
    mission = null,
    missionPlanV2 = null,
    missionContractV4 = null,
    targetGeoContext = null,
    dest = null
} = {}) {
    const parts = [];
    const add = (value) => {
        if (Array.isArray(value)) {
            value.forEach(add);
            return;
        }
        if (value && typeof value === 'object') {
            Object.values(value).forEach(add);
            return;
        }
        const text = String(value || '').replace(/\s+/g, ' ').trim();
        if (text) parts.push(text.slice(0, 360));
    };
    const plan = missionPlanV2?.plan && typeof missionPlanV2.plan === 'object' ? missionPlanV2.plan : {};
    const frame = plan.storyFrame && typeof plan.storyFrame === 'object' ? plan.storyFrame : {};
    const contractPlan = missionContractV4?.plan && typeof missionContractV4.plan === 'object' ? missionContractV4.plan : {};
    const contractFrame = missionContractV4?.storyFrame && typeof missionContractV4.storyFrame === 'object'
        ? missionContractV4.storyFrame
        : (contractPlan.storyFrame && typeof contractPlan.storyFrame === 'object' ? contractPlan.storyFrame : {});
    add(dest?.n || dest?.name || dest?.icao);
    add(mission?.t);
    add(mission?.s);
    add(mission?.pax);
    add(plan.primaryObjective);
    add(plan.missionTrigger);
    add(plan.focusSubject);
    add(plan.keyQuestion);
    add(plan.missionStakes);
    add(plan.completionSignal);
    add(plan.localFacts);
    add(plan.weatherHooks);
    add(plan.operationalDetails);
    add(plan.realismBrief);
    add(plan.narrativeHooks);
    add(plan.mustMention);
    add(frame);
    add(contractPlan.primaryObjective);
    add(contractPlan.mustMention);
    add(contractFrame);
    add(targetGeoContext?.summary);
    add(targetGeoContext?.localFacts);
    add(targetGeoContext?.airportDetails);
    return parts.join(' | ').slice(0, 1800);
}

function compactBushPickupStoryExcerpt(text = '', maxLen = 320) {
    const clean = String(text || '')
        .replace(/\s+/g, ' ')
        .trim();
    if (!clean) return '';
    const sentences = clean
        .split(/(?<=[.!?])\s+/)
        .map(s => s.trim())
        .filter(Boolean);
    let out = '';
    for (const sentence of sentences) {
        const next = `${out}${out ? ' ' : ''}${sentence}`.trim();
        if (next.length > maxLen && out) break;
        out = next;
        if (out.length >= Math.min(180, maxLen)) break;
    }
    return (out || clean).slice(0, maxLen).trim();
}

function bushPickupStorySentences(text = '') {
    return String(text || '')
        .replace(/\s+/g, ' ')
        .trim()
        .split(/(?<=[.!?])\s+/)
        .map(s => s.trim())
        .filter(Boolean);
}

function pickBushPickupStorySentence(text = '', pattern = null, maxLen = 260) {
    const sentences = bushPickupStorySentences(text);
    const re = pattern instanceof RegExp ? pattern : null;
    const picked = re ? sentences.find(sentence => re.test(normalizeMissionText(sentence))) : sentences[0];
    return String(picked || '').slice(0, maxLen).trim();
}

function normalizeBushPickupWhyThereText(value = '', targetName = 'dem Zielstrip') {
    const clean = _missionPipelineV4BushPickupDisplayText(value).replace(/\s+/g, ' ').trim();
    if (!clean) return '';
    const parts = clean.split(/\s*;\s*/).map(part => part.trim()).filter(Boolean);
    if (!parts.length) return clean;
    const first = parts[0];
    const firstNorm = normalizeMissionText(first);
    const needsAccessSentence = _missionPipelineV4LooksBushPickupFragmentText(first)
        || /^(?:der\s+)?strip\s+(?:selbst\s+)?(?:ist|liegt|dient|bleibt)\b/.test(firstNorm)
        || /^(treffpunkt|abholpunkt|naechster|nachster|nächster|sicherer|neutraler|kurzer|schnellster|besserer)\b/.test(firstNorm);
    if (!needsAccessSentence) return clean;
    const access = _missionPipelineV4StripSentenceEnd(
        _missionPipelineV4BushPickupAccessSentence(first, targetName)
    ).replace(/[.!?]+$/g, '').trim();
    return [access, ...parts.slice(1)].filter(Boolean).join('; ');
}

function bushPickupRoleContext(role = '', storyText = '') {
    const hay = normalizeMissionText(`${role} ${storyText}`);
    if (/\b(hydrolog|wasserstand|pegel|fluss|river|bach|ufer|sediment)\b/.test(hay)) {
        return {
            equipment: 'Feldmappe, Tablet, Wasserproben und zwei leichten Kisten',
            boarding: 'Die Pegelpunkte sind kontrolliert, die Wasserproben sind beschriftet und die Messdaten liegen im Tablet.',
            departure: 'In der Basis werden Wasserstandsreihen, Proben und Fotos ausgewertet und an die nächste Crew übergeben.',
            returnReason: 'In der Basis gehen Messdaten, Proben und Fotos in die nächste Einsatzplanung.'
        };
    }
    if (/\b(geolog|gestein|fels|hang|erosion|rutsch|kartier|probe|sediment)\b/.test(hay)) {
        return {
            equipment: 'Probenbeuteln, GPS-Notizen, Feldskizzen und einem Messkoffer',
            boarding: 'Die Proben sind beschriftet, die GPS-Punkte sitzen und die Feldskizzen sind trocken verpackt.',
            departure: 'In der Basis werden Proben, Fotos und Kartiernotizen zusammengeführt.',
            returnReason: 'In der Basis gehen Proben, Fotos und Kartiernotizen an das Projektteam.'
        };
    }
    if (/\b(ranger|wildlife|trail|forst|permit|bachlauf|markierung|sperr)\b/.test(hay)) {
        return {
            equipment: 'Rucksack, Markierungsband, Kartenmappe und einer kleinen Rückholkiste',
            boarding: 'Die Markierungen sind gesetzt, die Fotos sind im Tablet und die Notizen für die Rangerstation sind vollständig.',
            departure: 'Die Rangerstation braucht die Sperr- und Zustandsnotizen für die nächste Crewplanung.',
            returnReason: 'In der Basis werden Zustandsnotizen, Fotos und Markierungen für die nächste Crewplanung abgegeben.'
        };
    }
    if (/\b(technik|techniker|inspekt|mechan|wartung|funk|relais|generator|pruef|prüf|maengel|mängel)\b/.test(hay)) {
        return {
            equipment: 'Prüfmappe, Werkzeugtasche, Tablet und zwei leichten Kisten',
            boarding: 'Die Prüfung ist abgeschlossen, die Fotos sind im Tablet und die kleinen Kisten können mit zurück.',
            departure: 'In der Basis gehen Prüfwerte, Mängelliste und Ersatzteilbedarf in die nächste Planung.',
            returnReason: 'In der Basis werden Prüfwerte, Mängelliste und Materialbedarf für den nächsten Einsatz eingetragen.'
        };
    }
    return {
        equipment: 'Feldmappe, Tablet, persönlichem Gepäck und leichter Ausrüstung',
        boarding: 'Die Feldnotizen sind vollständig, die Fotos sind gesichert und die leichte Ausrüstung ist bereit für den Rückflug.',
        departure: 'In der Basis gehen Notizen, Daten und Rückholmaterial in den nächsten Ablauf.',
        returnReason: 'In der Basis werden Notizen, Daten und Rückholmaterial für den nächsten Schritt übergeben.'
    };
}

function buildAiBushPickupStory({
    aiPassenger = null,
    storyText = '',
    fallbackPickupStory = null,
    dest = null,
    start = null
} = {}) {
    const passenger = aiPassenger && typeof aiPassenger === 'object' ? aiPassenger : {};
    const aiStory = passenger.pickupStory && typeof passenger.pickupStory === 'object' ? passenger.pickupStory : {};
    const display = (value = '') => _missionPipelineV4BushPickupDisplayText(String(value || '')).replace(/\s+/g, ' ').trim();
    const role = display(aiStory.role || passenger.role || fallbackPickupStory?.role || 'Pickup-Gast');
    const personName = display(aiStory.personName || passenger.name || fallbackPickupStory?.personName || '');
    const targetName = String(dest?.n || dest?.name || dest?.icao || 'dem Zielstrip').trim();
    const homeName = String(start?.n || start?.name || start?.icao || currentStartICAO || 'dem Heimatplatz').trim();
    const roleContext = bushPickupRoleContext(role, storyText);
    const storyReturn = display(pickBushPickupStorySentence(
        storyText,
        /\b(zurueck|zurück|heim|basis|mccall|auswert|ueberg|überg|bericht|planung|crew|naechst|nächst|handoff|termin|freigabe)\b/,
        280
    ));
    const storyWork = display(pickBushPickupStorySentence(
        storyText,
        /\b(gemess|mess|probe|daten|foto|tablet|karte|skizz|markier|kontroll|geprueft|geprüft|dokument|wartung|feld)\b/,
        320
    ));
    const exactWhere = display(aiStory.exactWhere)
        || `am Striprand bei ${targetName}, neben einem kleinen Geländewagen mit ${roleContext.equipment}`;
    const whyThere = normalizeBushPickupWhyThereText(aiStory.whyThere, targetName)
        || compactBushPickupStoryExcerpt(storyText, 320)
        || normalizeBushPickupWhyThereText(fallbackPickupStory?.whyThere, targetName);
    const returnReason = display(aiStory.returnReason)
        || storyReturn
        || roleContext.returnReason.replace(/\bder Basis\b/g, homeName);
    const boardingCue = display(aiStory.boardingCue)
        || storyWork
        || roleContext.boarding;
    const departureCue = display(aiStory.departureCue)
        || roleContext.departure.replace(/\bder Basis\b/g, homeName);
    const story = {
        personName,
        role,
        exactWhere,
        whyThere,
        returnReason,
        boardingCue,
        departureCue
    };
    return (typeof _sanitizeBushPickupStory === 'function')
        ? _sanitizeBushPickupStory(story)
        : story;
}

function sanitizeBushPickupBriefingWhere(value = '', fallback = 'am Treffpunkt am Zielstrip') {
    let text = String(value || '').replace(/\s+/g, ' ').trim().replace(/[.!?]+$/g, '');
    if (!text) return fallback;
    text = text
        .replace(/^ich\s+(?:warte|stehe|sitze)\s+/i, '')
        .replace(/^ich\s+bin\s+/i, '')
        .replace(/^(?:warte|stehe|sitze)\s+/i, '')
        .replace(/\s+(?:und\s+)?(?:warte|stehe|sitze)?\s*(?:hier\s+)?auf\s+(?:sie|dich|den\s+piloten|meine\s+abholung)\s*$/i, '')
        .replace(/\s+auf\s+(?:sie|dich|den\s+piloten|meine\s+abholung)\s*$/i, '')
        .replace(/\bmein(?:e|en|em|er)?\s+/gi, '')
        .replace(/\s+/g, ' ')
        .trim();
    return text || fallback;
}

function addBushPickupNameToStory(storyText = '', { name = '', role = '', exactWhere = '' } = {}) {
    const story = String(storyText || '').replace(/\s+/g, ' ').trim();
    const personName = String(name || '').trim();
    if (!story || !personName) return story;
    if (story.toLowerCase().includes(personName.toLowerCase())) return story;
    const roleText = String(role || '').trim();
    const where = sanitizeBushPickupBriefingWhere(exactWhere, 'am Treffpunkt am Zielstrip');
    const intro = roleText
        ? `${personName}, ${roleText}, wartet ${where}.`
        : `${personName} wartet ${where}.`;
    return `${intro} ${story}`;
}

function missionHasPassengerByPaxText(paxText) {
    const txt = String(paxText || '').trim();
    if (!txt) return true;
    const m = txt.match(/^\s*(\d+)\s*PAX\b/i);
    if (m) return parseInt(m[1], 10) > 0;
    return !/^\s*0\s*PAX\b/i.test(txt);
}

