function _missionPipelineV4LocalHistoryRead(key = '') {
    if (!key || typeof localStorage === 'undefined') return [];
    try {
        const parsed = JSON.parse(localStorage.getItem(key) || '[]');
        return Array.isArray(parsed) ? parsed.map(x => String(x || '')).filter(Boolean) : [];
    } catch (_) {
        return [];
    }
}

function _missionPipelineV4LocalHistoryWrite(key = '', values = [], limit = 32) {
    if (!key || typeof localStorage === 'undefined') return;
    try {
        const cleaned = (Array.isArray(values) ? values : [])
            .map(x => String(x || '').trim())
            .filter(Boolean)
            .slice(-Math.max(1, Number(limit) || 32));
        localStorage.setItem(key, JSON.stringify(cleaned));
    } catch (_) {}
}

function _missionPipelineV4PickNameShortlist(pool = [], historyKey = '', count = 6) {
    const src = (Array.isArray(pool) ? pool : [])
        .map(item => ({
            name: String(item?.name || '').trim(),
            gender: String(item?.gender || '').trim().toLowerCase() === 'female' ? 'female' : 'male'
        }))
        .filter(item => item.name);
    if (!src.length) return [];
    const history = _missionPipelineV4LocalHistoryRead(historyKey);
    const recent = new Set(history.slice(-Math.min(12, Math.max(1, src.length - 1))));
    let fresh = src.filter(item => !recent.has(item.name));
    if (fresh.length < Math.min(count, src.length)) fresh = src;
    const start = Math.floor(Math.random() * fresh.length);
    const out = [];
    for (let i = 0; i < fresh.length && out.length < count; i++) {
        const item = fresh[(start + i) % fresh.length];
        if (!out.some(existing => existing.name === item.name)) out.push(item);
    }
    if (out[0]) {
        _missionPipelineV4LocalHistoryWrite(historyKey, history.concat(out[0].name), 32);
    }
    return out;
}

function _missionPipelineV4BuildVarietyHints({ taskDomain = '', roleProfile = '', profileId = '' } = {}) {
    const isBushPickup = String(taskDomain || '').toLowerCase() === 'bush_pickup_return'
        || String(roleProfile || '').toLowerCase() === 'bush_pickup_guest_v1'
        || String(profileId || '').toLowerCase() === 'bush_pickup_strip';
    if (!isBushPickup) return null;
    return {
        passengerNameCandidates: _missionPipelineV4PickNameShortlist(
            MISSION_PIPELINE_V4_BUSH_PICKUP_NAME_POOL,
            'ga_bush_pickup_passenger_name_history_v1',
            6
        ),
        note: 'Rotierende Namensvorschlaege fuer Bush-Pickup; Rolle und Geschichte weiterhin aus Kontext, Role-Pool und StoryFrame ableiten.'
    };
}

function buildMissionContractV4({
    plannerContext = {},
    plannerResult = null
} = {}) {
    const plan = compactMissionPlanV2ForPrompt(plannerResult);
    const mode = normalizeMissionType(
        plannerContext.missionType || plannerContext.missionPicker?.baseType || (plannerContext.isPOI ? 'poi' : 'apt'),
        !!plannerContext.isPOI
    );
    const profile = getMissionTaskProfile(plannerContext.dispatchProfileId || 'auto', mode) || {};
    const sarHeli = missionIsSarHeliProfileId(plannerContext.dispatchProfileId || '');
    const semantics = plannerResult?.semantics || _missionSemanticsV4Build({
        mode,
        taskDomain: plan?.plan?.taskDomain || profile.taskDomain || 'general',
        targetCategory: plan?.plan?.targetCategory || plannerContext.selectedCategory || 'generic',
        requestedCategory: plannerContext.requestedCategory || plannerContext.selectedCategory || 'all',
        targetName: plannerContext.dest?.n || '',
        missionTruth: plannerResult?.resolvedNeeds?.mission_truth || plannerContext.missionTruth || null
    });
    const sarDecision = missionPipelineV4SarDecision({
        semantics,
        plan: plan?.plan || {},
        resolvedNeeds: plannerResult?.resolvedNeeds || {},
        suggestedIncidentType: plan?.plan?.storyFrame?.incidentType || '',
        allowedIncidentTypes: sarHeli ? missionSarHeliIncidentIdsForCategory(
            semantics.focusLock.targetCategory || plan?.plan?.targetCategory || plannerContext.selectedCategory || '',
            semantics.focusLock.primarySubjectLabel || plan?.plan?.targetLabel || plannerContext.dest?.n || ''
        ) : null,
        writeHistory: false,
        lockSuggested: true
    });
    const contractProfileId = String(profile.id || plannerContext.dispatchProfileId || '').trim().toLowerCase();
    const followUpContext = plannerContext.followUpContext && typeof plannerContext.followUpContext === 'object'
        ? plannerContext.followUpContext
        : (plannerResult?.followUpContext && typeof plannerResult.followUpContext === 'object' ? plannerResult.followUpContext : null);
    const followUpRoute = followUpContext?.route && typeof followUpContext.route === 'object' ? followUpContext.route : {};
    const contractHomeName = String(followUpRoute.homeName || plannerContext.start?.n || plannerContext.start?.name || currentStartICAO || '').trim();
    const pickupCreativeBrief = contractProfileId === 'bush_pickup_strip'
        ? (plannerResult?.pickupCreativeBrief || buildBushPickupCreativeBrief(plannerContext, {
            target: { name: plannerContext.dest?.n || plannerContext.dest?.name || '' },
            picker: { profile: contractProfileId }
        }, _missionPipelineV3WeatherBundle(plannerContext.missionWeather || null), { writeHistory: false }))
        : null;
    const missionVarietyBrief = (!pickupCreativeBrief && bushProfileSupportsMissionVariety(contractProfileId))
        ? (plannerResult?.missionVarietyBrief || buildBushMissionVarietyBrief(plannerContext, {
            target: { name: plannerContext.dest?.n || plannerContext.dest?.name || '' },
            picker: { profile: contractProfileId }
        }, _missionPipelineV3WeatherBundle(plannerContext.missionWeather || null), { profileId: contractProfileId, writeHistory: false }))
        : null;
    const storyFrame = _missionPipelineV4BuildStoryFrame(plan?.plan || {}, semantics, plannerResult?.resolvedNeeds || {}, {
        sarDecision,
        pickupCreativeBrief,
        missionVarietyBrief,
        followUpContext,
        homeName: contractHomeName
    });
    const knowledgeContext = compactPoiKnowledgeContextForMission(
        plannerContext.knowledgeContext || plannerContext.dest?.knowledgeContext || null,
        10
    );
    const taskDomain = String(plan?.plan?.taskDomain || profile.taskDomain || 'general');
    const roleProfile = String(plan?.plan?.roleProfile || profile.roleProfile || 'general_passenger_v1');
    const profileId = String(profile.id || plannerContext.dispatchProfileId || 'auto');
    return {
        pipelineVersion: MISSION_PIPELINE_V4_VERSION,
        status: String(plan?.status || 'invalid'),
        mode,
        route: {
            startIcao: currentStartICAO || '',
            startName: String(plannerContext.start?.n || ''),
            targetIcao: plannerContext.isPOI ? 'POI' : String(plannerContext.dest?.icao || currentDestICAO || ''),
            targetName: String(plannerContext.dest?.n || ''),
            distanceNm: Number.isFinite(Number(plannerContext.dist)) ? Math.round(Number(plannerContext.dist) * 10) / 10 : null
        },
        profile: {
            id: profileId,
            label: String(profile.label || ''),
            roleProfile,
            taskDomain,
            pickerCategory: String(plannerContext.selectedCategory || 'all'),
            requestedCategory: String(plannerContext.requestedCategory || plannerContext.selectedCategory || 'all')
        },
        target: {
            isPOI: !!plannerContext.isPOI,
            name: String(plannerContext.dest?.n || ''),
            lat: Number.isFinite(Number(plannerContext.dest?.lat)) ? Number(plannerContext.dest.lat) : null,
            lon: Number.isFinite(Number(plannerContext.dest?.lon)) ? Number(plannerContext.dest.lon) : null,
            poiSource: String(plannerContext.dest?.poiSource || ''),
            poiCategory: String(plannerContext.dest?.poiCategory || plannerContext.selectedCategory || ''),
            terrainFt: Number.isFinite(Number(plannerContext.poiTerrainFt)) ? Math.round(Number(plannerContext.poiTerrainFt)) : null
        },
        knowledgeContext,
        weather: _missionPipelineV3WeatherBundle(plannerContext.missionWeather || null),
        fireHazard: plannerResult?.resolvedNeeds?.fire_hazard || plannerContext.missionFireHazard || null,
        missionPlan: plan,
        storyFrame,
        pickupCreativeBrief,
        missionVarietyBrief,
        variety: pickupCreativeBrief?.variety || missionVarietyBrief?.variety || plannerResult?.variety || null,
        sarHeli: sarHeli ? (plannerContext.sarHeli || null) : null,
        missionTruth: compactMissionTruthForPrompt(
            plannerResult?.resolvedNeeds?.mission_truth || plannerContext.missionTruth || null
        ),
        semantics,
        followUpContext,
        missionTemporalContext: followUpContext?.temporalContext || plannerContext.missionTemporalContext || null,
        varietyHints: followUpContext?.lockedPassenger
            ? {
                lockedPassenger: followUpContext.lockedPassenger,
                note: 'Follow-up nutzt den Passagier aus der Ursprungsmission; keine Namensrotation anwenden.'
            }
            : _missionPipelineV4BuildVarietyHints({ taskDomain, roleProfile, profileId }),
        targetGeoContext: _missionPipelineV3CompactGeoContext(
            plannerResult?.resolvedNeeds?.geo_context || plannerContext.targetGeoContext || null
        ),
        airportDetails: _missionPipelineV3AirportDetails(plannerContext)
    };
}
window.buildMissionContractV4 = buildMissionContractV4;

function buildMissionWriterV4Prompt(contract = {}) {
    return `<INSTRUKTIONEN>
Du bist Mission Writer V4 fuer einen GA-Missionsgenerator.
Du schreibst aus einem bindenden Mission Contract eine konkrete, abwechslungsreiche und lokal plausible Mission.

Regeln:
1. Nutze nur Fakten aus <CONTRACT>.
2. Erfinde keine freien Ortsfakten ausserhalb der dort enthaltenen lokalen Hinweise.
3. taskDomain, roleProfile, missionType, targetLabel, mustMention und mustAvoid sind bindend.
4. Die Story muss denselben Sachverhalt beschreiben wie primaryObjective, localFacts, weatherHooks und sceneIntent.
5. sceneIntent beschreibt sichtbare, semantische Dinge am Ziel oder begruendet, warum keine Zielszene entstehen soll. Keine Asset-Namen.
6. Wenn sceneKind="none", dann sceneIntent sehr sparsam halten: keine Zielszene, visibleIdeas=[], densityHint="none".
7. Bei POI niemals Landung am Ziel andeuten, ausser CONTRACT.sarHeli.enabled ist true; dann muss der SAR-Heli-Ablauf mit Fundstelle, Landung/Hover-Aufnahme und medizinischem Handoff beschrieben werden.
7a. Bei SAR-Heli darf die Story keinen separaten "Evac-Hinweis" und keine technischen Hoehen-/Zeitvorgaben enthalten. Erzaehle die Bergung und den medizinischen Weiterflug als natuerlichen Teil des Briefings.
8. Das Zielsubjekt und die TaskDomain bleiben bindend; Kontext darf nur anreichern, nicht umwidmen.
9. Benannte Nebenanker nur dann prominent nutzen, wenn sie in CONTRACT.semantics als Kontextrolle plausibel bleiben.
10. Die Story muss einen klaren Story-Frame aus CONTRACT.storyFrame transportieren: Trigger, Fokus-Subjekt, offene Frage, Stakes und Abschluss/Handoff.
11. Nutze aus CONTRACT.storyFrame nach Moeglichkeit auch subjectDetail, incidentContext, whyNow und soughtOutcome, damit der Auftrag nicht abstrakt bleibt.
12. Wenn CONTRACT.storyFrame incidentType, lastSeenContext, probableScenario oder visibleClueCandidates enthaelt, muessen diese Informationen im Briefing spuerbar werden statt zu abstrakten Standardfloskeln zu verfallen.
13. Du darfst einen plausiblen operativen Anlass frei ausformulieren, solange keine neuen Ortsnamen oder harten Geofakten ausserhalb des Contracts behauptet werden.
14. search_and_rescue: Sag klar, wer oder was betroffen ist, wo die letzte Sichtung oder Meldung war, welche Lage vermutet wird und worauf wir aus der Luft konkret achten sollen.
15. search_and_rescue: CONTRACT.storyFrame.incidentType ist bindender Einsatz-Lock. Vermische keine anderen SAR-Incidents im Briefing: road_collision bleibt Unfall-/Kollisionslage; vehicle_off_road bleibt Fahrzeug abseits der Strasse; angler_missing bleibt Ufer-/Anglerlage; small_boat_overdue bleibt Bootslage; downed_ultralight bleibt Luftfahrzeuglage.
16. search_and_rescue: Schreibe keine Einsatz-Alternativen wie "Wanderer oder UL" oder "Person oder Wrack". Triff aus dem Contract eine konkrete Dispatch-Annahme und erzaehle sie mit Hintergrund: wer/was, wo, was ist gemeldet, warum jetzt, welcher Befund wird gebraucht.
17. inspection_infra: Sag klar, welche Stoerung, Beobachtung oder Schadensmeldung den Einsatz ausloest und welche Folgeentscheidung daran haengt.
17a. science_bio: Schreibe eine biologische/ökologische Studie oder Monitoringfrage, keine allgemeine "Umweltbeobachtung". Nenne sichtbare Bio-Anker wie Habitat, Vegetation, Uferzone, Wasserfarbe, Rast-/Brutbereiche, Trockenstress, Stoerfaktoren oder Monitoringvergleich. Keine Technikinspektion, keine SAR-/Feuerlage, keine harten Messwerte oder Artenfunde frei erfinden.
17b. science_geo: Schreibe eine geologische/geomorphologische Fragestellung, keine allgemeine "Relief anschauen"-Floskel. Nenne sichtbare Geo-Anker wie Relief, Erosion, Hangstabilitaet, Sedimente, Uferkante, Abbruchkante, Talform, Steinbruch, alte Fliesswege oder Gelaendekartierung. Keine Bio-/Artenanalyse, keine Technikinspektion, keine SAR-/Feuerlage.
18. news_coverage: Gib einen beobachtbaren redaktionellen Aufhaenger statt nur "wir machen Bilder". Bei POI-City keine "O-Toene sammeln"-Story, sondern z.B. lokales Fest, Besucherandrang, Verkehrslage, Baustelle im Ortskern, Sperrung oder sichtbare Veraenderung. Sachlich bleiben, keine Einsatz- oder Inspektionssprache.
18a. media_photo: Gib eine Story-Spine fuer die Bildserie: Auftraggeber/Verwendungszweck + Motivlogik + was nach dem Flug mit dem Material passiert. Gute City-Anlaesse sind Tourismusbroschuere, Gemeindeaufnahme, Ortsmarketing, Jubiläumsfilm, Immobilien-/Projektbild oder redaktionelle Establishing Shots. Nicht in Sightseeing kippen.
18b. historian_guided_tour: Schreibe eine historische Ortslesart, keine generische Geschichtsstunde. Gute City/Castle-Anker sind Ortskern, Siedlungsform, alte Verkehrswege, Kirchen-/Marktplatzlage, Tal-/Hanglage, Burg-/Schlosslage, Denkmalgestalt oder fruehere Nutzung. Rollen duerfen Ortsarchivarin, Denkmalpfleger, Heimatforscherin oder Stadtchronist sein.
18c. mapping_survey: Schreibe einen echten Survey-Auftrag, keine Sightseeing- oder Foto-Story. Benenne Auftraggeber/Verwendung (GIS, Orthofoto, Photogrammetrie, Korridoraufnahme, Projektvergleich), Zielgeometrie, geplante Arbeitsweise und Handoff an die Auswertung. Einzelobjekte koennen einen ruhigen Orbit brauchen, Flaechen/Korridore parallele Nord-Sued-Passes. Keine Schadensdiagnose, keine SAR-Sprache und keine Behauptung, dass ein Pattern bereits technisch geprueft wird.
19. charter und club_utility: Sag klar, warum genau dieser Gast oder diese Erledigung heute nach genau diesem Ziel muss und welcher Termin, Zielkontakt oder praktische Ablauf daran haengt.
19a. bush + CONTRACT.missionVarietyBrief: Nutze missionVarietyBrief, storyFrame, localFacts, narrativeHooks und weatherHooks als offenen Rahmen. Wenn candidateShortlist vorhanden ist, waehle im Normalfall genau eine Richtung daraus und halte Rolle, Taetigkeiten, Ausruestung, Zweck und Folgegrund konsistent zusammen; nicht quer durch alle Kandidaten mischen. Candidate-Elemente sind Rohmaterial: grammatisch umformen, nicht als Fragmente oder Feldtexte wortwoertlich in Story oder PAX-Cues kopieren. Schreibe niemals Rohfragmente wie "weil der Strip ist..." oder "damit die Basis kann..."; forme daraus natuerliche deutsche Saetze. Das Profil-Rezept bleibt bindend: Supply liefert am Ziel aus, Charter setzt am Ziel ab, Adventure landet am Ziel und startet dort den Aufenthalt am Boden, Recon prueft aus der Luft und kehrt heim, Cargo-Pickup holt nur Fracht zur Basis zurueck.
19b. bush + bush_pickup_strip / taskDomain bush_pickup_return: Nutze CONTRACT.pickupCreativeBrief, storyFrame, localFacts, narrativeHooks und weatherHooks als offenen Rahmen. Wenn pickupCreativeBrief.candidateShortlist vorhanden ist, waehle im Normalfall genau eine Richtung daraus und halte Rolle, Taetigkeiten, Ausruestung und Rueckkehrgrund konsistent zusammen; nicht quer durch alle Kandidaten mischen. Candidate-Elemente sind Rohmaterial: grammatisch umformen, nicht als Fragmente oder Feldtexte wortwoertlich in Story oder PAX-Cues kopieren. Schreibe niemals Rohfragmente wie "weil der Strip ist..." oder "damit die Basis kann..."; forme daraus natuerliche deutsche Saetze. Schreibe eine eigenständige Bush-Pickup-Geschichte, die wer/was/wo/wann/wie/warum beantwortet: Name/Rolle, was genau vor Ort getan wurde, warum genau dieser Strip, Wartepunkt mit Gepäck/Ausrüstung, warum jetzt zurück, welcher nächste Schritt in der Basis folgt. Der Rueckkehrgrund darf organisatorisch, persoenlich, wetterbedingt oder ergebnisbezogen sein, aber nicht automatisch wie ein Charter-Termin oder Notfall klingen. Nicht als Schema abarbeiten; natürlich in 4-5 Sätzen erzählen.
19c. bush + bush_pickup_strip: Fülle passenger.pickupStory mit Voice-Ankern zur exakt gleichen Geschichte. Diese Felder sind keine neue Story, sondern die Basis für spätere PAX-Ansagen: exactWhere, whyThere, returnReason, boardingCue, departureCue.
19d. bush + bush_pickup_strip: OUTPUT.story ist immer ein Briefing fuer den Piloten aus Dispatcher-/Auftragsperspektive. Keine Ich-Form aus Sicht des Pickup-Gasts, keine Formulierungen wie "ich war", "bring mich", "ich sitze an Bord" oder "ich muss zurueck". Die Ich-Perspektive gehoert nur in passenger.greetingText und die Pickup-Voice-Cues.
19e. bush + bush_pickup_strip / taskDomain bush_pickup_return: Wenn CONTRACT.varietyHints.passengerNameCandidates vorhanden ist, setze passenger.name auf genau einen passenden Namen aus dieser Liste und halte gender konsistent. Die Liste ist nur eine Rotationshilfe gegen wiederkehrende Fuellnamen; Rolle, Auftrag und Story muessen weiter aus StoryFrame, pickupCreativeBrief, Rollenfamilie und Zielkontext entstehen.
19f. bush + bush_pickup_strip / taskDomain bush_pickup_return: Das Briefing braucht einen kurzen, natuerlichen Wetter-/Pistenanker aus CONTRACT.weather und dem Zielstrip: Wind/Sicht/Temperatur knapp einbauen, dazu Zielpiste, Bahnzustand oder Randbereich im Anflug nennen. Nicht als Checkliste schreiben.
19g. Follow-up-Missionen: Wenn CONTRACT.followUpContext vorhanden ist, schreibe die Mission als natürliche Fortsetzung des vorherigen Auftrags. Nutze sourceMission, storyFrame, lockedPassenger, pickupStory oder missionVarietyBrief als Faktenanker. Das Briefing darf nicht nach Systemanweisung, Debugtext oder Formularfeldern klingen; es soll wie ein neuer Dispatcher-Auftrag mit vertrautem Teamkontext wirken.
19h. Follow-up-Zeitkontext: Wenn CONTRACT.missionTemporalContext oder followUpContext.temporalContext vorhanden ist, nutze stayText/stayDays nur als natürliche Aufenthaltsdauer oder Vorbereitungszeit. Keine technischen Feldnamen, keine Datumsrechnung, keine explizite Systemlogik.
19i. sightseeing_tour + POI: Schreibe einen persönlichen Rundflug, keinen Arbeitsauftrag. Beantworte natürlich: wer freut sich auf den Blick, warum ist genau dieser Zielbereich der Höhepunkt, warum passt der Flug jetzt, und was bleibt nach der Rückkehr hängen. Gute Anlässe sind Besuch, Freund/Familie, Geschenkflug, Heimatblick, Wochenendausflug oder persönliche Fotos. Verboten sind Erfassung, Dokumentation, Lagebild, Vermessung, Inspektion, Befund, Bewertung, Arbeitsauftrag, Arbeitsflughöhe und Formulierungen wie "abgearbeitet". Keine Landung am POI andeuten.
19j. poi_learning_guide + CONTRACT.knowledgeContext: Wenn knowledgeContext.status="accept", nutze knowledgeContext.facts als geprüfte Wissensbasis für Story und greetingText. Der Passagier ist dann ein Guide, der dem Piloten und ggf. Mitfliegenden unterwegs Interessantes zum POI erklärt. Greife 1-2 konkrete Fakten natürlich auf, aber erfinde keine zusätzlichen Ortsdaten, Baujahre, Größen, Namen oder historischen Details außerhalb von knowledgeContext, missionTruth und targetGeoContext. Story und greetingText dürfen die Fakten nur anteasern; die ausführliche Faktenfolge bleibt den Voice-Meldungen vorbehalten. Keine Zielhöhe, keine targetAltFt/radius/dwell-Angaben, keine Pilot-Anweisungen wie "Achten Sie", kein formelles "Sie", kein "Ziel ist es" und kein Arbeitswort wie "Informationsflug" oder "durchführen".
20. cargo_fragile, medical_transfer und animal_transport: Sag klar, welcher vorbereitete Folgeablauf am Ziel unsere ruhige und zeitgerechte Uebergabe heute erforderlich macht.
21. sceneIntent und visibleIdeas duerfen nur Dinge zeigen, die zur Story passen. Keine bereits "geloeste" Lage, wenn die Story noch eine offene Frage beschreibt.
22. Jede Mission soll implizit oder explizit vier Fragen beantworten: Wer/was genau ist betroffen? Was ist passiert oder was hat den Auftrag ausgeloest? Warum gerade jetzt? Welchen konkreten Unterschied macht unser Flug?
23. Vermeide reine Dispatcher-Floskeln wie "wir machen heute Fotos", "wir fliegen heute eine Inspektion" oder "wir suchen das Gebiet ab", wenn kein genauer Anlass, kein betroffenes Subjekt und keine Folgeentscheidung benannt werden.
24. Antworte in natuerlichen, vollstaendigen Saetzen; keine Aufzaehlung einzelner Lagefragmente als Kurzsaetze.
25. CONTRACT.storyFrame-Felder sind Rohmaterial, keine Satzliste. Formuliere sie zu 4-5 fluessigen Saetzen um, statt jedes Feld einzeln aneinanderzureihen.
25a. Vermeide Satzstarts, die nach Formularfeldern klingen: "Zuletzt...", "Der letzte...", "Die Meldung...", "Aus der Luft liefern wir...". Baue daraus eine zusammenhaengende Einsatzgeschichte.
26. Wenn subjectDetail bereits ein ganzer Satz ist, schreibe nicht "Gesucht wird nach ..." davor. Nutze dann eine passende eigene Formulierung.
27. Schreibe alle frei formulierten Texte auf Deutsch. Eigennamen, ICAO-Kürzel und feststehende Ortsnamen dürfen unverändert bleiben.
27a. Nutze normale deutsche Umlaute in Briefing, PAX-Texten und Dialogen, also "für", "zurück", "prüfen" statt "fuer", "zurueck", "pruefen".
28. Antwort nur als JSON.
</INSTRUKTIONEN>

<CONTRACT>
${JSON.stringify(contract)}
</CONTRACT>

<OUTPUT>
{
  "title": "Kurzer Missionstitel",
  "story": "4-5 Saetze als Dispatch-Briefing fuer den Piloten, konkret, lokal plausibel und mit echtem Missionsanlass",
  "pax": "z.B. 1 PAX (...) oder 0 PAX",
  "cargo": "z.B. Messkoffer (45 lbs)",
  "passenger": {
    "name": "Vollstaendiger Name",
    "role": "Rolle/Beruf",
    "gender": "male|female",
    "personality": "3 Adjektive",
    "dialectHint": "neutral oder leicht regional",
    "roleProfile": "exakt aus CONTRACT.profile.roleProfile",
    "taskDomain": "exakt aus CONTRACT.profile.taskDomain",
    "gTolerance": "niedrig|mittel|hoch",
    "bankTolerance": "niedrig|mittel|hoch",
    "cargoSensitivity": "niedrig|mittel|hoch",
    "stomachSensitivity": "niedrig|mittel|hoch",
    "comfortPriority": "niedrig|mittel|hoch",
    "urgencyPriority": "niedrig|hoch",
    "targetAltFt": 0,
    "targetRadiusNm": 0,
    "targetDwellMin": 0,
    "greetingText": "Kurze persoenliche Begruessung an den Piloten mit konkretem Auftragsbezug und einem Hauch vom Warum des Flugs",
    "pickupStory": {
      "personName": "nur bei bush_pickup_strip: gleicher Name wie passenger.name",
      "role": "nur bei bush_pickup_strip: gleiche Rolle wie passenger.role",
      "exactWhere": "wo die Person am Zielstrip wartet, mit Gepäck/Ausrüstung",
      "whyThere": "warum sie dort draußen war und was sie konkret getan hat",
      "returnReason": "warum sie jetzt zurück zur Basis muss",
      "boardingCue": "kurzer Ich-Satz für den Moment direkt nach dem Einsteigen",
      "departureCue": "kurzer Ich-Satz für den Rückflug, mit Ergebnis oder nächstem Schritt"
    }
  },
  "sceneIntent": {
    "summary": "Was am Ziel aus Pilotensicht sichtbar oder eben nicht sichtbar sein soll",
    "environment": "z.B. Vorfeld, Waldrand, Uferbereich, offenes Gelaende, leer",
    "visibleIdeas": ["konkrete sichtbare Ideen"],
    "avoid": ["Dinge, die nicht auftauchen duerfen"],
    "densityHint": "none|sparse|normal|busy",
    "notes": "Kurzer Grund"
  }
}
</OUTPUT>`;
}

function _missionPipelineV4StoryKeywords(text = '') {
    const stop = new Set([
        'der', 'die', 'das', 'und', 'oder', 'aber', 'eine', 'einer', 'einem', 'einen', 'eines', 'eines',
        'nach', 'heute', 'damit', 'dass', 'fuer', 'ueber', 'unter', 'ohne', 'nicht', 'mehr', 'noch',
        'wird', 'werden', 'wurde', 'sind', 'sein', 'soll', 'sollen', 'muss', 'muessen', 'jetzt', 'dort',
        'rund', 'bereich', 'ziel', 'einsatz', 'auftrag', 'luft', 'lagebild', 'klaren', 'konkreten'
    ]);
    return normalizeMissionText(text)
        .split(/[^a-z0-9]+/)
        .filter(token => token && token.length >= 4 && !stop.has(token));
}

function _missionPipelineV4StoryFieldCovered(story = '', phrase = '', minHits = 1) {
    const storyText = normalizeMissionText(story);
    const tokens = Array.from(new Set(_missionPipelineV4StoryKeywords(phrase)));
    if (!tokens.length) return false;
    let hits = 0;
    for (const token of tokens) {
        if (storyText.includes(token)) hits += 1;
        if (hits >= minHits) return true;
    }
    return false;
}

function _missionPipelineV4LooksEnglish(text = '') {
    const normalized = normalizeMissionText(text);
    if (!normalized) return false;
    const englishHits = (normalized.match(/\b(the|with|from|near|last|confirmed|position|reported|wearing|their|group|during|steep|section|climber|ground|teams|immediate|aerial|required|before|light|conditions|confirmation|assessment|accessibility|handover|coordinates|coordination|center|need|needs|retrieve|someone|something|remote|location|specific|operational|context|completed|counting|inventory|weekend|secured|forgotten|special|order|ready|transport|transported|return|flight|logical|step|collected|data|base|processing|planning|pickup|passenger|cargo|departure|destination|prevail|involve|personnel|essential|items|common|operation)\b/g) || []).length;
    const germanHits = (normalized.match(/\b(der|die|das|und|mit|von|bei|nahe|letzte|meldung|sichtung|ortung|funkkontakt|person|fahrzeug|einsatz|leitstelle|bodenkraefte|suchtrupps|rettung|ausruestung|befund|lagebild|wartet|flieg|flug|rueckflug|rückflug|zurueck|zurück|abholung|abholen|aufnehmen|bringen|basis|planung|notizen|unterlagen|auftrag|gelandet|ziel|zielstrip|wetter|sicht|wind)\b/g) || []).length;
    const englishStarts = (normalized.match(/(^|[.!?]\s*)(the|this|that|she|he|they|pickup|return|transport|vfr)\b/g) || []).length;
    return (englishHits >= 4 && englishHits > germanHits)
        || (englishHits >= 3 && englishStarts >= 1 && englishHits >= germanHits);
}

function _missionPipelineV4NarrativeTextUsable(text = '') {
    const clean = String(text || '').replace(/\s+/g, ' ').trim();
    if (!clean) return false;
    return !_missionPipelineV4LooksEnglish(clean) && !_missionPipelineV4LooksInternalMissionText(clean);
}

function _missionPipelineV4LooksBushPickupFragmentText(text = '') {
    const normalized = normalizeMissionText(text);
    if (!normalized) return false;
    if (/^(strip\s+(selbst\s+)?(ist|liegt|dient|bleibt)|treffpunkt|abholpunkt|naechster|nachster|nächster|sicherer|neutraler|kurzer|schnellster|besserer)\b/.test(normalized)) return true;
    if (/^(der\s+)?strip\s+selbst\s+ist\s+der\s+arbeitsort\b/.test(normalized)) return true;
    if (/\bweil\s+(?:(?:der|die|das)\s+)?(?:strip|treffpunkt|abholpunkt|naechster|nachster|nächster|sicherer|neutraler|kurzer|schnellster|besserer)\b/.test(normalized)) return true;
    if (/\bweil\s+(?:der|die|das)\s+[a-z0-9_-]+\s+(?:selbst\s+)?ist\s+/.test(normalized)) return true;
    if (/\bweil\s+[a-z0-9_-]+\s+ist\s+/.test(normalized)) return true;
    if (/(^|[.!?]\s+)(naechste|nächste|rangerstation|basis|lodge-team|projektleitung|freigabe)[a-z0-9_-]*\s+(crew|braucht|passt|wartet|geht|wird)\b/.test(normalized)) return true;
    return false;
}

function _missionPipelineV4FilterNarrativeTexts(values = []) {
    return (Array.isArray(values) ? values : [])
        .map(value => String(value || '').replace(/\s+/g, ' ').trim())
        .filter(text => text && _missionPipelineV4NarrativeTextUsable(text));
}

function _missionPipelineV4LooksInternalMissionText(text = '') {
    const normalized = normalizeMissionText(text);
    if (!normalized) return false;
    return /\b(sar[\s_-]*erkundung|unterfokus|storyframe|missiontruth|contract|writer|planner|pipeline|zielkategorie|objectfamil(?:y|ien)?|primaerfokus|passt durch zielkategorie|sichtbare suchhinweise zu diesem sar)\b/.test(normalized);
}

function _missionPipelineV4SarIncidentSignatureRegex(incidentType = '') {
    const id = missionSarCanonicalIncidentType(incidentType);
    return ({
        missing_hiker: /\b(wanderer|wanderin|spaziergaenger|spazierganger|vermisste person|personensuche|orientierungslos|verlaufen)\b/,
        fallen_climber: /\b(kletterer|kletterin|bergsteiger|bergsteigerin|kletter|fels|grat|steig|abgerutscht|absturzkante|geroell|geroll)\b/,
        downed_ultralight: /\b(luftfahrzeug|kleinflugzeug|ultraleichtflugzeug|ultraleicht|ul[\s-]?maschine|echo[\s-]?maschine|flugzeug|mayday|wrack|wrackteil|einschlag|absturz)\b/,
        vehicle_off_road: /\b(von der fahrbahn abgekommen|fahrbahn abgekommen|abseits der strasse|abseits der straße|boeschung|boschung|waldsaum|vermisstes fahrzeug|fahrzeugspuren|reifenspuren|handy[\s-]?ortung)\b/,
        road_collision: /\b(verkehrsunfall|kollision|auffahrunfall|kreuzungsunfall|unfallstelle|mehrere fahrzeuge|mehreren fahrzeugen|fahrzeugkollision|sperrung|rettungsgasse)\b/,
        missing_kayaker: /\b(kajak|kajakfahrer|kajakfahrerin|paddler|paddlerin|paddel|kanu|kenterung|gekentert)\b/,
        angler_missing: /\b(angler|anglerin|angelplatz|angelausruestung|angelausrustung|angelrute|fischerei|fischer)\b/,
        small_boat_overdue: /\b(bootsbesatzung|bootscrew|motorboot|freizeitboot|angelboot|aluboot|ueberfaelliges boot|uberfalliges boot)\b/,
        riverside_vehicle_entry: /\b(fahrzeugeintritt ins wasser|fahrzeug im wasser|pkw im wasser|auto im wasser|fahrzeug.*wasserkontakt|wasserkontakt.*fahrzeug|fahrzeug.*ufer|ufer.*fahrzeug)\b/
    })[id] || null;
}

function _missionPipelineV4SarTextConflictsIncidentType(text = '', incidentType = '') {
    const id = missionSarCanonicalIncidentType(incidentType);
    const normalized = normalizeMissionText(text);
    if (!normalized || !id) return false;
    const own = _missionPipelineV4SarIncidentSignatureRegex(id);
    const known = [
        'missing_hiker',
        'fallen_climber',
        'downed_ultralight',
        'vehicle_off_road',
        'road_collision',
        'missing_kayaker',
        'angler_missing',
        'small_boat_overdue',
        'riverside_vehicle_entry'
    ];
    return known.some(otherId => {
        if (otherId === id) return false;
        const other = _missionPipelineV4SarIncidentSignatureRegex(otherId);
        if (!other || !other.test(normalized)) return false;
        return !own || !own.test(normalized) || /\b(oder|bzw|stattdessen)\b/.test(normalized);
    });
}

function _missionPipelineV4SarTextConflictsIncidentFamily(text = '', incidentType = '') {
    const id = missionSarCanonicalIncidentType(incidentType);
    const normalized = normalizeMissionText(text);
    if (!normalized || !id) return false;
    const has = re => re.test(normalized);
    const aircraftTerms = /\b(luftfahrzeug|kleinflugzeug|ultraleichtflugzeug|ultraleichtflugzeuge|ultraleicht|ul[\s-]?maschine|echo[\s-]?maschine|flugzeug|einschlag|wrackhinweis)\b/;
    const roadCollisionTerms = /\b(verkehrsunfall|kollision|auffahrunfall|kreuzungsunfall|unfallstelle mit|mehrere fahrzeuge|mehreren fahrzeugen|unfallfahrzeug)\b/;
    const offRoadTerms = /\b(von der fahrbahn abgekommen|fahrbahn abgekommen|abseits der strasse|abseits der straße|boeschung|boschung|waldsaum|vermisstes fahrzeug|fahrzeugspuren|reifenspuren)\b/;
    const waterTerms = /\b(kajak|paddel|boot|bootscrew|bootsbesatzung|angler|wasserrettung|uferabschnitt|anlandepunkt)\b/;
    const missingPersonTerms = /\b(wanderer|wanderin|kletterer|kletterin|bergsteiger|bergsteigerin|personensuche|vermisste person|vermisstenmeldung)\b/;
    if (id === 'downed_ultralight') return has(roadCollisionTerms) || has(offRoadTerms) || has(waterTerms) || has(missingPersonTerms);
    if (id === 'road_collision') return has(aircraftTerms) || has(offRoadTerms) || has(waterTerms) || has(missingPersonTerms);
    if (id === 'vehicle_off_road' || id === 'riverside_vehicle_entry') return has(aircraftTerms) || has(roadCollisionTerms);
    if (['missing_hiker', 'fallen_climber'].includes(id)) return has(aircraftTerms) || has(roadCollisionTerms) || has(waterTerms);
    if (['missing_kayaker', 'angler_missing', 'small_boat_overdue'].includes(id)) return has(aircraftTerms) || has(roadCollisionTerms) || has(offRoadTerms);
    return false;
}

function _missionPipelineV4SarTextLooksUndecided(text = '') {
    const normalized = normalizeMissionText(text);
    if (!normalized) return false;
    const personFamily = /\b(wanderer|wanderin|kletterer|kletterin|bergsteiger|bergsteigerin|personensuche|vermisste person|vermisstenmeldung)\b/;
    const aircraftFamily = /\b(luftfahrzeug|kleinflugzeug|ultraleichtflugzeug|ultraleichtflugzeuge|ultraleicht|ul[\s-]?maschine|echo[\s-]?maschine|flugzeug|wrack|wrackteile|absturzortung)\b/;
    const roadFamily = /\b(verkehrsunfall|kollision|unfallstelle|fahrbahn|fahrzeuge|fahrzeug)\b/;
    const waterFamily = /\b(kajak|boot|bootscrew|bootsbesatzung|angler|wasserrettung|uferhinweis)\b/;
    const families = [personFamily, aircraftFamily, roadFamily, waterFamily].filter(re => re.test(normalized)).length;
    return families >= 2 && /\b(oder|bzw)\b/.test(normalized);
}

function _missionPipelineV4SentenceCount(text = '') {
    return String(text || '')
        .split(/(?<=[.!?])\s+/)
        .map(x => String(x || '').trim())
        .filter(Boolean)
        .length;
}

function _missionPipelineV4CountNeedle(text = '', needle = '') {
    const hay = normalizeMissionText(text);
    const key = normalizeMissionText(needle);
    if (!hay || !key) return 0;
    return hay.split(key).length - 1;
}

function _missionPipelineV4LooksEnumerative(text = '') {
    const s = String(text || '').trim();
    if (!s) return false;
    if (/^([A-ZÄÖÜ][^.!?]{0,80}\.\s*){4,}$/.test(s) && /Wir sollen|Der letzte|Nach dem|Aufgrund|Zuletzt/i.test(s)) return true;
    if (/(^|[.!?]\s*)(Der letzte|Zuletzt|Moegliche Hinweise|Aus der Luft achten wir|Verdeckte |Aufgrund der |Wir uebernehmen )/i.test(s) && _missionPipelineV4SentenceCount(s) >= 5) return true;
    return false;
}

function _missionPipelineV4LooksFragmentedStory(text = '') {
    const s = String(text || '').replace(/\s+/g, ' ').trim();
    if (!s) return false;
    return /[.!?]\s+(einem|einer|einen|eines|mit|bei|nach|wegen|durch|unter)\s+[a-zäöüß][^.!?]{8,}[.!?]/.test(s);
}

function _missionPipelineV4JoinNaturalList(values = []) {
    const src = Array.isArray(values) ? values.map(x => String(x || '').trim()).filter(Boolean) : [];
    if (!src.length) return '';
    if (src.length === 1) return src[0];
    if (src.length === 2) return `${src[0]} und ${src[1]}`;
    return `${src.slice(0, -1).join(', ')} und ${src[src.length - 1]}`;
}

function _missionPipelineV4BushVarietyCandidate(contract = {}) {
    const brief = contract?.missionVarietyBrief && typeof contract.missionVarietyBrief === 'object'
        ? contract.missionVarietyBrief
        : null;
    const candidates = Array.isArray(brief?.candidateShortlist) ? brief.candidateShortlist : [];
    if (!candidates.length) return null;
    const primaryId = String(brief?.variety?.primaryId || '').trim();
    return (primaryId ? candidates.find(c => String(c?.id || '').trim() === primaryId) : null) || candidates[0] || null;
}

function _missionPipelineV4BushVarietyFirst(values = [], fallback = '') {
    return Array.isArray(values) && values.length
        ? String(values[0] || fallback).trim()
        : String(fallback || '').trim();
}

function _missionPipelineV4BushVarietySecond(values = [], fallback = '') {
    return Array.isArray(values) && values.length > 1
        ? String(values[1] || fallback).trim()
        : String(fallback || '').trim();
}

function _missionPipelineV4ContractHomeName(contract = {}, fallback = 'der Basis') {
    const followRoute = contract?.followUpContext?.route && typeof contract.followUpContext.route === 'object'
        ? contract.followUpContext.route
        : null;
    return String(
        followRoute?.homeName
        || followRoute?.returnHomeRef?.name
        || contract?.route?.homeName
        || contract?.route?.startName
        || contract?.route?.startIcao
        || currentStartICAO
        || fallback
    ).trim() || fallback;
}

function _missionPipelineV4ComposeBushVarietyStory(contract = {}) {
    const profileId = String(contract?.profile?.id || '').trim().toLowerCase();
    if (!bushProfileSupportsMissionVariety(profileId)) return '';
    const candidate = _missionPipelineV4BushVarietyCandidate(contract);
    if (!candidate) return '';
    const targetName = String(contract?.target?.name || contract?.route?.targetName || 'dem Zielstrip').trim() || 'dem Zielstrip';
    const homeName = _missionPipelineV4ContractHomeName(contract, 'der Basis');
    const role = _missionPipelineV4BushVarietyFirst(candidate.roleIdeas, 'Backcountry-Kontakt');
    const taskA = _missionPipelineV4BushVarietyFirst(candidate.taskIdeas, 'den Auftrag vor Ort vorbereiten');
    const taskB = _missionPipelineV4BushVarietySecond(candidate.taskIdeas, 'die offenen Punkte dokumentieren');
    const objects = _missionPipelineV4JoinNaturalList(
        Array.isArray(candidate.objectIdeas) ? candidate.objectIdeas.slice(0, 3) : []
    ) || 'leichte Ausruestung';
    const returnReason = _missionPipelineV4EnsureSentence(_missionPipelineV4BushVarietyFirst(candidate.returnDrivers, 'Der naechste Schritt haengt an diesem Flug'));
    const accessReason = _missionPipelineV4EnsureSentence(_missionPipelineV4BushVarietyFirst(candidate.accessReasons, 'Der Zielstrip ist der passende Zugangspunkt'));
    if (profileId === 'bush_supply_strip') {
        return [
            `Wir bringen heute ${objects} nach ${targetName}; am Strip wartet ${role} auf die Uebergabe.`,
            `Die Lieferung wird dort draussen gebraucht, um ${taskA} und ${taskB}.`,
            accessReason,
            `${returnReason} Nach dem Abladen ist der Supply-Auftrag am Ziel abgeschlossen.`
        ].filter(Boolean).join(' ');
    }
    if (profileId === 'bush_charter_strip') {
        return [
            `Heute bringen wir ${role} mit ${objects} nach ${targetName}.`,
            `Nach der Landung beginnt vor Ort der eigentliche Termin: ${taskA} und ${taskB}.`,
            accessReason,
            `${returnReason} Der Charterflug endet mit dem Dropoff am Zielstrip.`
        ].filter(Boolean).join(' ');
    }
    if (profileId === 'bush_scenic_hopper') {
        return [
            `Dieser Bush-Hop nach ${targetName} ist als ruhiger Backcountry-Leg fuer ${role} geplant.`,
            `Nach der Landung beginnt draussen der kleine Tagesplan: ${taskA} und ${taskB}.`,
            `${objects} bleibt als leichtes Kit dabei.`,
            `Die Landung am Zielstrip ist der Abschluss des Fluglegs und der Start des Aufenthalts.`
        ].filter(Boolean).join(' ');
    }
    if (profileId === 'bush_recon_return') {
        return [
            `Heute pruefen wir ${targetName} aus der Luft, ohne dort eine Landung einzuplanen.`,
            `Im Fokus stehen ${taskA} und ${taskB}.`,
            accessReason,
            `${returnReason} Danach bringen wir Befund, Fotos und Notizen zurueck nach ${homeName}.`
        ].filter(Boolean).join(' ');
    }
    if (profileId === 'bush_pickup_cargo') {
        return [
            `Wir fliegen leer nach ${targetName}; dort liegen ${objects} am Striprand zur Rueckholung bereit.`,
            `Vor Ort geht es konkret darum, ${taskA} und ${taskB}.`,
            accessReason,
            `${returnReason} Danach bringen wir die Fracht zurueck nach ${homeName} und laden sie dort aus.`
        ].filter(Boolean).join(' ');
    }
    return '';
}

function _missionPipelineV4StripSentenceEnd(text = '') {
    return String(text || '')
        .replace(/\s+/g, ' ')
        .trim()
        .replace(/\s*[.!?]+$/g, '')
        .trim();
}

function _missionPipelineV4LowerFirst(text = '') {
    const s = String(text || '').trim();
    if (!s) return '';
    return s.charAt(0).toLowerCase() + s.slice(1);
}

function _missionPipelineV4UpperSentenceStart(text = '') {
    return String(text || '').replace(/^(\s*["'„“(]*)([a-zäöü])/u, (_m, prefix, first) => `${prefix}${first.toUpperCase()}`);
}

function _missionPipelineV4BuildSarObjective(frame = {}, semantics = {}) {
    const targetName = String(semantics?.focusLock?.primarySubjectLabel || '').trim() || 'dem Zielgebiet';
    const subject = _missionPipelineV4SarPrimarySubjectText(frame.focusSubject || frame.subjectDetail || 'einer konkreten Suchlage');
    return `Luftsuche bei ${targetName}: ${_missionPipelineV4LowerFirst(subject)}`;
}

function _missionPipelineV4BuildSarRealismBrief(frame = {}, semantics = {}, resolvedNeeds = {}) {
    const targetName = String(semantics?.focusLock?.primarySubjectLabel || '').trim() || 'Das Zielgebiet';
    const cues = Array.isArray(resolvedNeeds?.mission_truth?.visibleCues)
        ? resolvedNeeds.mission_truth.visibleCues.slice(0, 2).map(x => String(x || '').trim()).filter(Boolean)
        : [];
    const cueText = cues.length ? ` mit ${_missionPipelineV4JoinNaturalList(cues)}` : '';
    const subject = _missionPipelineV4SarPrimarySubjectText(frame.focusSubject || frame.subjectDetail || 'Suchhinweisen');
    return `${targetName}${cueText} ist ein plausibler Suchraum fuer ${_missionPipelineV4LowerFirst(subject)}.`;
}

function _missionPipelineV4SarPrimarySubjectText(text = '') {
    const subject = _missionPipelineV4StripSentenceEnd(text || 'eine konkrete Suchlage');
    return subject
        .replace(/\s+oder\s+(frischer|klarer|verwertbarer|eindeutiger|moeglicher|möglicher)?\s*(hinweis|unfallhinweis|wasserhinweis|suchhinweis|einschlaghinweis|uferhinweis|zugriffspunkt|befund).*$/i, '')
        .trim() || subject;
}

function _missionPipelineV4EnsureSentence(text = '', fallback = '') {
    const s = _missionPipelineV4UpperSentenceStart(_missionPipelineV4StripSentenceEnd(text || fallback));
    if (!s) return '';
    return /[.!?]$/.test(s) ? s : `${s}.`;
}

function _missionPipelineV4SentenceParts(text = '') {
    const protectedText = String(text || '')
        .replace(/\bbzw\./gi, m => `${m.slice(0, -1)}__DOT__`)
        .replace(/\bca\./gi, m => `${m.slice(0, -1)}__DOT__`)
        .replace(/\bggf\./gi, m => `${m.slice(0, -1)}__DOT__`)
        .replace(/\bu\.a\./gi, m => m.replace(/\./g, '__DOT__'))
        .replace(/\bd\.h\./gi, m => m.replace(/\./g, '__DOT__'))
        .replace(/\bz\.\s*b\./gi, m => m.replace(/\./g, '__DOT__'));
    return protectedText
        .split(/(?<=[.!?])\s+/)
        .map(part => _missionPipelineV4StripSentenceEnd(part.replace(/__DOT__/g, '.')))
        .filter(Boolean);
}

function _missionPipelineV4LooksLikeCompleteSentence(text = '') {
    const s = _missionPipelineV4StripSentenceEnd(text);
    if (!s) return false;
    if (/^Meldung\b/i.test(s)) return false;
    return /\b(wird|wurde|ist|sind|hat|haben|befindet|fehlt|meldet|melden|sucht|suchen|braucht|brauchen|soll|sollen|muss|muessen|müssen)\b/i.test(s);
}

function _missionPipelineV4SarSubjectSentence(detail = '', fallback = '') {
    const s = _missionPipelineV4StripSentenceEnd(detail || fallback);
    if (!s) return '';
    if (/^(einem|einer|einen|eines)\b/i.test(s)) return `Gesucht wird nach ${_missionPipelineV4LowerFirst(s)}.`;
    if (_missionPipelineV4LooksLikeCompleteSentence(s)) return _missionPipelineV4EnsureSentence(s);
    return `Im Mittelpunkt steht ${_missionPipelineV4LowerFirst(s)}.`;
}

function _missionPipelineV4OutcomeSentence(text = '', fallback = '') {
    let s = _missionPipelineV4StripSentenceEnd(text || fallback);
    if (!s) return '';
    if (_missionPipelineV4LooksLikeCompleteSentence(s)) {
        return _missionPipelineV4EnsureSentence(s);
    }
    return _missionPipelineV4EnsureSentence(`Aus der Luft liefern wir den benoetigten Befund: ${_missionPipelineV4LowerFirst(s)}`);
}

function _missionPipelineV4CompletionSentence(text = '') {
    let s = _missionPipelineV4StripSentenceEnd(text);
    if (!s) return '';
    if (/^(Uebergabe|Übergabe)\b/i.test(s)) {
        return _missionPipelineV4EnsureSentence(`Anschliessend folgt die ${s}`);
    }
    return _missionPipelineV4EnsureSentence(s);
}

function _missionPipelineV4PushUniqueSentence(out = [], sentence = '', minHits = 2) {
    const s = _missionPipelineV4EnsureSentence(sentence);
    if (!s) return;
    const existing = out.join(' ');
    if (existing && _missionPipelineV4StoryFieldCovered(existing, s, minHits)) return;
    out.push(s);
}

function _missionPipelineV4WeatherBitsForBriefing(wx = null) {
    const raw = (wx && typeof wx === 'object' && wx.raw && typeof wx.raw === 'object') ? wx.raw : wx;
    const bits = [];
    const windDeg = Number(raw?.windDeg);
    const windKts = Number(raw?.windKts);
    if (Number.isFinite(windDeg) && Number.isFinite(windKts)) {
        bits.push(`Wind ${Math.round(windDeg)}°/${Math.round(windKts)} kt`);
    } else if (Number.isFinite(windKts)) {
        bits.push(`Wind ${Math.round(windKts)} kt`);
    }
    const visKm = Number(raw?.visKm);
    if (Number.isFinite(visKm)) bits.push(visKm >= 10 ? 'Sicht >10 km' : `Sicht ${visKm.toFixed(1)} km`);
    const fltCat = String(raw?.fltCat || '').trim().toUpperCase();
    if (fltCat && !bits.some(bit => bit.toUpperCase().includes(fltCat))) bits.push(fltCat);
    const tempC = Number(raw?.tempC);
    if (Number.isFinite(tempC)) bits.push(`${Math.round(tempC)}°C`);
    return bits.slice(0, 4);
}

function _missionPipelineV4BushPickupConditionSentence(contract = {}) {
    const destWeather = contract?.weather?.dest || contract?.weather?.targetPoi || null;
    const depWeather = contract?.weather?.dep || null;
    const bits = _missionPipelineV4WeatherBitsForBriefing(destWeather);
    if (bits.length) {
        return `Bei ${bits.join(', ')} am Ziel bleibt der Anflug ein Bush-Strip-Anflug: lies Zielpiste, Wind und Randbereich sauber mit, bevor du zum Wartepunkt rollst.`;
    }
    const depBits = _missionPipelineV4WeatherBitsForBriefing(depWeather).slice(0, 2);
    if (depBits.length) {
        return `Mit ${depBits.join(', ')} am Start bleibt der Zielstrip trotzdem der entscheidende Punkt: lies Zielpiste, Wind und Randbereich sauber mit, bevor du zum Wartepunkt rollst.`;
    }
    return 'Der Zielstrip bleibt ein Bush-Strip: lies Zielpiste, Wind und Randbereich sauber mit, bevor du zum Wartepunkt rollst.';
}

function _missionPipelineV4BushPickupStoryHasConditionCue(text = '') {
    const normalized = normalizeMissionText(text);
    if (!normalized) return false;
    const weatherCue = /\b(wind|sicht|vfr|mvfr|ifr|temperatur|wetter|metar|\d+\s*°\s*c)\b/.test(normalized);
    const stripCue = /\b(piste|bahn|landebahn|strip|zielstrip|pistenrand|randbereich|anflug)\b/.test(normalized);
    return weatherCue && stripCue;
}

function _missionPipelineV4EnsureBushPickupConditions(story = '', contract = {}) {
    const base = String(story || '').replace(/\s+/g, ' ').trim();
    const condition = _missionPipelineV4BushPickupConditionSentence(contract);
    if (!base) return condition;
    if (_missionPipelineV4BushPickupStoryHasConditionCue(base)) return base;
    return `${base} ${condition}`.trim();
}

function _missionPipelineV4EscapeRegExp(value = '') {
    return String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function _missionPipelineV4EnforceBushPickupNameCandidates(passenger = {}, contract = {}, story = '') {
    const taskDomain = String(contract?.profile?.taskDomain || passenger?.taskDomain || '').trim().toLowerCase();
    const roleProfile = String(contract?.profile?.roleProfile || passenger?.roleProfile || '').trim().toLowerCase();
    const profileId = String(contract?.profile?.id || '').trim().toLowerCase();
    const isBushPickup = taskDomain === 'bush_pickup_return'
        || roleProfile === 'bush_pickup_guest_v1'
        || profileId === 'bush_pickup_strip';
    if (!isBushPickup) return { passenger, story };
    const lockedPassenger = contract?.followUpContext?.lockedPassenger && typeof contract.followUpContext.lockedPassenger === 'object'
        ? contract.followUpContext.lockedPassenger
        : null;
    if (lockedPassenger?.name) {
        const pax = (passenger && typeof passenger === 'object') ? { ...passenger } : {};
        const selectedName = String(lockedPassenger.name || '').trim();
        const selectedRole = String(lockedPassenger.role || pax.role || '').trim();
        const selectedGender = String(lockedPassenger.gender || pax.gender || '').trim().toLowerCase();
        const currentName = String(pax.name || '').replace(/\s*\([^)]*\)\s*$/, '').trim();
        let nextStory = String(story || '').replace(/\s+/g, ' ').trim();
        if (currentName && currentName !== selectedName) {
            nextStory = nextStory.replace(new RegExp(_missionPipelineV4EscapeRegExp(currentName), 'g'), selectedName);
        }
        pax.name = selectedName;
        if (selectedRole) pax.role = selectedRole;
        if (selectedGender === 'female' || selectedGender === 'male') pax.gender = selectedGender;
        if (pax.pickupStory && typeof pax.pickupStory === 'object') {
            pax.pickupStory = {
                ...pax.pickupStory,
                personName: selectedName,
                role: selectedRole || pax.pickupStory.role || pax.role || ''
            };
        }
        return { passenger: pax, story: nextStory || story };
    }
    const candidates = (Array.isArray(contract?.varietyHints?.passengerNameCandidates)
        ? contract.varietyHints.passengerNameCandidates
        : [])
        .map(item => ({
            name: String(item?.name || '').trim(),
            gender: String(item?.gender || '').trim().toLowerCase() === 'female' ? 'female' : 'male'
        }))
        .filter(item => item.name);
    if (!candidates.length) return { passenger, story };
    const pax = (passenger && typeof passenger === 'object') ? { ...passenger } : {};
    const currentName = String(pax.name || '').replace(/\s*\([^)]*\)\s*$/, '').trim();
    const normalizedCurrent = normalizeMissionText(currentName);
    const exactCandidate = normalizedCurrent
        ? candidates.find(item => normalizeMissionText(item.name) === normalizedCurrent)
        : null;
    const currentGender = String(pax.gender || '').trim().toLowerCase();
    const selected = exactCandidate
        || candidates.find(item => item.gender === currentGender)
        || candidates[0];
    if (!selected?.name) return { passenger: pax, story };
    const storyText = String(story || '').replace(/\s+/g, ' ').trim();
    const leadingName = (storyText.match(/^([A-ZÄÖÜ][A-Za-zÄÖÜäöüß'’.-]+(?:\s+[A-ZÄÖÜ][A-Za-zÄÖÜäöüß'’.-]+){1,2})(?=,\s)/) || [])[1] || '';
    const oldName = currentName || leadingName;
    let nextStory = storyText;
    if (oldName && oldName !== selected.name) {
        nextStory = nextStory.replace(new RegExp(_missionPipelineV4EscapeRegExp(oldName), 'g'), selected.name);
    } else if (!oldName && nextStory) {
        nextStory = nextStory.replace(/^([A-ZÄÖÜ][A-Za-zÄÖÜäöüß'’.-]+(?:\s+[A-ZÄÖÜ][A-Za-zÄÖÜäöüß'’.-]+){1,2})(?=,\s)/, selected.name);
    }
    pax.name = selected.name;
    pax.gender = selected.gender;
    if (pax.pickupStory && typeof pax.pickupStory === 'object') {
        pax.pickupStory = { ...pax.pickupStory, personName: selected.name };
    }
    return { passenger: pax, story: nextStory || story };
}

function _missionPipelineV4ComposeStoryFallback(contract = {}) {
    const targetName = String(contract?.target?.name || 'dem Zielgebiet').trim() || 'dem Zielgebiet';
    const taskDomain = String(contract?.profile?.taskDomain || 'general').trim().toLowerCase();
    const bushVarietyStory = _missionPipelineV4ComposeBushVarietyStory(contract);
    if (bushVarietyStory) return bushVarietyStory;
    const frame = (contract?.storyFrame && typeof contract.storyFrame === 'object') ? contract.storyFrame : {};
    const detail = String(frame.subjectDetail || frame.focusSubject || targetName).trim();
    const incident = String(frame.incidentContext || frame.trigger || '').trim();
    const whyNow = String(frame.whyNow || frame.stakes || '').trim();
    const sought = String(frame.soughtOutcome || frame.keyQuestion || '').trim();
    const completion = String(frame.completionSignal || '').trim();
    const lastSeen = String(frame.lastSeenContext || '').trim();
    const probableScenario = String(frame.probableScenario || '').trim();
    const clueLine = Array.isArray(frame.visibleClueCandidates) && frame.visibleClueCandidates.length
        ? `Aus der Luft achten wir besonders auf ${_missionPipelineV4JoinNaturalList(frame.visibleClueCandidates.slice(0, 3))}.`
        : '';
    const avoidText = normalizeMissionText([
        ...(Array.isArray(contract?.missionPlan?.plan?.mustAvoid) ? contract.missionPlan.plan.mustAvoid : []),
        ...(Array.isArray(contract?.mustAvoid) ? contract.mustAvoid : []),
        ...(Array.isArray(contract?.plan?.mustAvoid) ? contract.plan.mustAvoid : [])
    ].join(' '));
    const avoidSpeculation = /spekulation|ursache.*verschwind|cause.*missing|keine.*hypothese/.test(avoidText);
    const weather = contract?.weather?.dest || contract?.weather?.dep || null;
    const weatherBits = [];
    if (Number.isFinite(Number(weather?.tempC))) weatherBits.push(`${Math.round(Number(weather.tempC))}°C`);
    if (String(weather?.fltCat || '').trim()) weatherBits.push(String(weather.fltCat).trim());
    const weatherSentence = weatherBits.length
        ? ` Die Bedingungen bleiben mit ${weatherBits.join(' und ')} gut genug fuer einen ruhigen, praezisen Ueberflug.`
        : '';
    if (taskDomain === 'search_and_rescue') {
        const sentences = [];
        const triggerText = String(frame.trigger || '').trim();
        const introSource = (!_missionPipelineV4LooksLikeCompleteSentence(triggerText) && detail)
            ? _missionPipelineV4SarSubjectSentence(detail, frame.focusSubject)
            : (triggerText || `Im Bereich ${targetName} laeuft eine SAR-Lage, die aus der Luft verengt werden soll.`);
        _missionPipelineV4PushUniqueSentence(sentences, introSource);
        const subjectLine = detail ? _missionPipelineV4SarSubjectSentence(detail, frame.focusSubject) : '';
        if (subjectLine && !_missionPipelineV4StoryFieldCovered(sentences.join(' '), detail, 2)) {
            _missionPipelineV4PushUniqueSentence(sentences, subjectLine);
        }
        const contextCandidates = avoidSpeculation
            ? [lastSeen, incident]
            : [lastSeen, incident, probableScenario];
        for (const candidate of contextCandidates) {
            if (sentences.length >= 3) break;
            for (const part of _missionPipelineV4SentenceParts(candidate)) {
                const before = sentences.length;
                _missionPipelineV4PushUniqueSentence(sentences, part, 4);
                if (sentences.length > before) break;
            }
        }
        const weatherClause = weatherBits.length
            ? `; bei ${weatherBits.join(' und ')} bleiben die Bedingungen fuer einen ruhigen, praezisen Ueberflug brauchbar`
            : '';
        _missionPipelineV4PushUniqueSentence(
            sentences,
            `${_missionPipelineV4StripSentenceEnd(whyNow || 'Die Bodenkraefte brauchen jetzt einen engeren Suchraum, bevor weitere Teams gebunden werden')}${weatherClause}`.trim()
        );
        const outcomeSentence = _missionPipelineV4OutcomeSentence(
            sought,
            'einen klaren Hinweis oder den sinnvollsten Zugang fuer die Suchtrupps'
        );
        const completionSentence = _missionPipelineV4CompletionSentence(completion);
        const handoff = [outcomeSentence, completionSentence].filter(Boolean).join(' ');
        _missionPipelineV4PushUniqueSentence(sentences, handoff);
        if (clueLine && sentences.length < 4) _missionPipelineV4PushUniqueSentence(sentences, clueLine);
        return sentences.filter(Boolean).slice(0, 5).join(' ');
    }
    if (taskDomain === 'mapping_survey') {
        const pattern = String(frame.surveyPatternHint || '').trim();
        const use = String(frame.surveyUse || detail || '').trim();
        return [
            String(frame.trigger || `Für ${targetName} braucht die Auswertung heute einen verwertbaren Survey-Datensatz.`).trim(),
            incident || `${use || 'Der geplante Datensatz'} gibt dem Flug den Zweck: Ziel, Randbereiche und erkennbare Referenzen sollen später sauber zusammenpassen.`,
            `${whyNow || 'Der nächste Arbeitsstand hängt daran, dass die Aufnahmen heute vollständig, ruhig und mit stabiler Höhe entstehen.'}${weatherSentence}`.trim(),
            `${sought || `Wir erfassen ${targetName}${pattern ? ` mit ${pattern}` : ''} so, dass GIS-, Photogrammetrie- oder Projektteam ohne Nachflug weiterarbeiten können.`} ${completion}`.trim()
        ].join(' ');
    }
    if (taskDomain === 'inspection_infra') {
        return [
            `Heute pruefen wir an ${targetName} ${detail}.`,
            incident || `Am Ziel liegt eine frische technische Auffaelligkeit vor, die aus der Luft schneller eingegrenzt werden soll.`,
            `${whyNow || 'Noch waehrend dieses Einsatzfensters muss entschieden werden, wie gross der Folgeaufwand am Boden wird.'}${weatherSentence}`.trim(),
            `${sought || 'Wir sollen eine klare Erstbewertung fuer Betreiber und Technikteam liefern.'} ${completion}`.trim()
        ].join(' ');
    }
    if (taskDomain === 'science_bio') {
        return [
            String(frame.trigger || `Fuer ${targetName} wird heute eine biologische Beobachtung aus der Luft gebraucht.`).trim(),
            incident || `${detail} ist der konkrete Beobachtungsanker fuer Studie, Monitoring oder naechste Feldbegehung.`,
            `${whyNow || 'Der Luftblick hilft jetzt, Habitat, Vegetation und Randzonen besser zu sortieren, bevor Bodenzeit gebunden wird.'}${weatherSentence}`.trim(),
            `${sought || 'Wir sollen sichtbare Bioindikatoren, Stoerfaktoren und passende Fotoanker fuer die Feldnotizen einordnen.'} ${completion}`.trim()
        ].join(' ');
    }
    if (taskDomain === 'science_geo') {
        return [
            String(frame.trigger || `Fuer ${targetName} wird heute eine geologische Beobachtung aus der Luft gebraucht.`).trim(),
            incident || `${detail} ist der konkrete Gelaendeanker fuer Kartierung, Reliefstudie oder naechste Feldarbeit.`,
            `${whyNow || 'Der Luftblick macht Relief, Kanten und Ablagerungen jetzt als Gesamtbild besser lesbar als eine einzelne Bodenstelle.'}${weatherSentence}`.trim(),
            `${sought || 'Wir sollen geologische Merkmale, offene Verdachtsstellen und passende Fotoanker fuer die Kartierung einordnen.'} ${completion}`.trim()
        ].join(' ');
    }
    if (taskDomain === 'media_photo') {
        return [
            String(frame.trigger || `Fuer ${targetName} wird heute eine verwertbare Luftbildserie gebraucht.`).trim(),
            incident || `${detail} gibt der Serie den konkreten Zweck und verhindert, dass daraus nur ein beliebiger Rundflug wird.`,
            `${whyNow || 'Der heutige Slot soll stabile Perspektiven liefern, die direkt in Redaktion, Broschuere, Film oder Projektkommunikation weiterverwendet werden koennen.'}${weatherSentence}`.trim(),
            `${sought || 'Wir sollen ruhige Motive liefern, die Ziel, Lage und Wiedererkennungswert klar zeigen.'} ${completion}`.trim()
        ].join(' ');
    }
    if (taskDomain === 'news_coverage') {
        return [
            String(frame.trigger || `Die Redaktion braucht zu ${targetName} heute einen klaren Aufhaenger aus der Luft.`).trim(),
            incident || `${detail} steht dabei als beobachtbarer Kern der Geschichte im Mittelpunkt.`,
            `${whyNow || 'Die Bilder und Eindruecke werden noch im aktuellen Slot fuer Bericht oder Schalte gebraucht.'}${weatherSentence}`.trim(),
            `${sought || 'Wir sollen ein belastbares Bild und eine kurze Einordnung liefern, damit die Redaktion nicht auf Archivmaterial ausweichen muss.'} ${completion}`.trim()
        ].join(' ');
    }
    if (taskDomain === 'historian_guided_tour') {
        return [
            String(frame.trigger || `Zu ${targetName} soll heute eine historische Ortslesart aus der Luft entstehen.`).trim(),
            incident || `${detail} bildet den historischen Erzaehlanker fuer den ruhigen Ueberflug.`,
            `${whyNow || 'Der Luftblick macht Lage, Wege, Ortskern oder Bauwerk in ihrem Zusammenhang besser lesbar.'}${weatherSentence}`.trim(),
            `${sought || 'Wir sollen eine kurze historische Einordnung liefern, die nach dem Ueberflug wirklich haengen bleibt.'} ${completion}`.trim()
        ].join(' ');
    }
    if (taskDomain === 'sightseeing_tour') {
        const sightseeingWeather = weatherBits.length
            ? ` Bei ${weatherBits.join(' und ')} bleibt der Rundflug gut planbar und angenehm.`
            : '';
        return [
            String(frame.trigger || `Zwei Gaeste haben den Rundflug zu ${targetName} als ruhigen Ausflugsmoment geplant.`).trim(),
            incident || `${detail} steht als persoenlicher Blickfang der Runde im Mittelpunkt.`,
            `${whyNow || 'Der Ueberflug ist der gemeinsame Hoehepunkt der Tour und soll ohne Hektik wirken.'}${sightseeingWeather}`.trim(),
            `${sought || 'Der Zielbereich soll ruhig zu sehen sein, damit Aussicht, Orientierung und ein paar Erinnerungsfotos tragen.'} ${completion || 'Danach geht es entspannt zum Heimatplatz zurueck.'}`.trim()
        ].join(' ');
    }
    if (taskDomain === 'bush_pickup_return') {
        return [
            String(frame.trigger || `Am ${targetName} wartet ein Pickup-Gast nach abgeschlossener Arbeit draussen auf den Rueckflug.`).trim(),
            incident || `${detail} gibt dem Pickup einen konkreten Grund und macht den Zielstrip zum passenden Treffpunkt.`,
            `${whyNow || 'Der Aufenthalt am Strip ist abgeschlossen; der Rueckflug bringt Person, Notizen und Ausruestung zurueck zur Basis.'}${weatherSentence}`.trim(),
            `${sought || 'Wir sollen leer zum Pickup fliegen, den Gast aufnehmen und die Geschichte auf dem Rueckflug nach Hause weiterfuehren.'} ${completion}`.trim()
        ].join(' ');
    }
    if (taskDomain === 'charter' || taskDomain === 'club_utility') {
        return [
            String(frame.trigger || `Der Flug nach ${targetName} hat heute einen konkreten Anlass am Ziel.`).trim(),
            incident || `${detail} macht genau diesen Umlauf sinnvoll und nicht nur irgendeinen Transport.`,
            `${whyNow || 'Der Termin oder Folgeablauf am Ziel haengt daran, dass wir jetzt und nicht spaeter ankommen.'}${weatherSentence}`.trim(),
            `${sought || 'Wir sollen die Uebergabe oder Ankunft so vorbereiten, dass der eigentliche Termin am Ziel direkt weiterlaufen kann.'} ${completion}`.trim()
        ].join(' ');
    }
    if (taskDomain === 'cargo_fragile' || taskDomain === 'medical_transfer' || taskDomain === 'animal_transport') {
        return [
            String(frame.trigger || `Der Flug nach ${targetName} dient einer konkreten Uebergabe, die am Ziel vorbereitet ist.`).trim(),
            incident || `${detail} steht im Mittelpunkt des Ablaufs am Ziel.`,
            `${whyNow || 'Das Zeitfenster und die Art der Uebergabe machen genau diesen ruhigen Flug jetzt notwendig.'}${weatherSentence}`.trim(),
            `${sought || 'Wir sollen die Uebergabe so sauber vorbereiten, dass Material, Begleitung oder Tier ohne Zusatzstress uebernommen werden koennen.'} ${completion}`.trim()
        ].join(' ');
    }
    return [
        String(frame.trigger || `Heute geht es fuer uns nach ${targetName}, weil dort ein konkreter Auftrag offen ist.`).trim(),
        incident || `${detail} steht dabei im Mittelpunkt des Flugs.`,
        `${whyNow || String(frame.stakes || 'Das Ergebnis des Ueberflugs wird fuer den naechsten Schritt direkt benoetigt.').trim()}${weatherSentence}`.trim(),
        `${sought || String(frame.keyQuestion || 'Wir sollen den Auftrag aus der Luft so weit klaeren, dass es geordnet weitergehen kann.').trim()} ${completion}`.trim()
    ].join(' ');
}

function _missionPipelineV4SarHeliSubjectLabel(frame = {}) {
    const incidentId = missionSarCanonicalIncidentType(frame.incidentType || '');
    const byIncident = {
        missing_hiker: 'eine vermisste Person',
        fallen_climber: 'einen abgestürzten Bergsteiger',
        missing_kayaker: 'einen überfälligen Kajakfahrer',
        angler_missing: 'einen vermissten Angler',
        small_boat_overdue: 'eine überfällige Bootsbesatzung',
        vehicle_off_road: 'eine Person an einem verunfallten Fahrzeug',
        road_collision: 'eine verletzte Person an der Unfallstelle',
        riverside_vehicle_entry: 'eine Person nach einem Fahrzeug-Wasser-Kontakt'
    };
    return byIncident[incidentId] || 'eine vermisste oder verletzte Person';
}

function _missionPipelineV4BushPickupBriefingLooksPaxPerspective(text = '') {
    const normalized = normalizeMissionText(text);
    if (!normalized) return false;
    return /\b(ich\s+(bin|war|habe|muss|soll|sitze|stehe|warte|komme|fliege|bringe)|bring\s+mich|hol\s+mich|nimm\s+mich|mein(?:e|er|em|en)?\s+(arbeit|auftrag|ausruestung|ausrüstung|rucksack|tablet|daten|proben|werkzeug|notizen)|als\s+passagier\s+zurueck|als\s+passagier\s+zuruck|als\s+passagier\s+zurück)\b/.test(normalized);
}

function _missionPipelineV4BushPickupNeutralField(value = '', fallback = '', options = {}) {
    const rejectFragments = options?.rejectFragments !== false;
    const usable = (candidate = '') => _missionPipelineV4NarrativeTextUsable(candidate)
        && (!rejectFragments || !_missionPipelineV4LooksBushPickupFragmentText(candidate));
    const text = _missionPipelineV4EnsureSentence(String(value || '').replace(/\s+/g, ' ').trim());
    const fallbackText = _missionPipelineV4EnsureSentence(String(fallback || '').replace(/\s+/g, ' ').trim());
    const safeFallback = usable(fallbackText) ? fallbackText : '';
    if (!text) return safeFallback;
    return (_missionPipelineV4BushPickupBriefingLooksPaxPerspective(text) || !usable(text))
        ? safeFallback
        : text;
}

function _missionPipelineV4BushPickupReturnSentence(value = '', homeName = 'der Basis') {
    const raw = _missionPipelineV4StripSentenceEnd(_missionPipelineV4BushPickupDisplayText(value || '')).trim();
    const home = String(homeName || 'der Basis').trim() || 'der Basis';
    if (!raw) return `In ${home} kann der Auftrag anschließend sauber abgeschlossen werden.`;
    const normalized = (() => {
        if (/^rangerstation\s+/i.test(raw)) return `Die Rangerstation ${raw.replace(/^rangerstation\s+/i, '').trim()}`;
        if (/^basis\s+/i.test(raw)) return `Die Basis ${raw.replace(/^basis\s+/i, '').trim()}`;
        if (/^lodge-team\s+/i.test(raw)) return `Das Lodge-Team ${raw.replace(/^lodge-team\s+/i, '').trim()}`;
        if (/^projektleitung\s+/i.test(raw)) return `Die Projektleitung ${raw.replace(/^projektleitung\s+/i, '').trim()}`;
        if (/^naechste\s+crew\s+/i.test(raw)) return `Die nächste Crew ${raw.replace(/^naechste\s+crew\s+/i, '').trim()}`;
        if (/^nächste\s+crew\s+/i.test(raw)) return `Die nächste Crew ${raw.replace(/^nächste\s+crew\s+/i, '').trim()}`;
        return raw;
    })();
    return _missionPipelineV4EnsureSentence(normalized.charAt(0).toUpperCase() + normalized.slice(1));
}

function _missionPipelineV4ComposeBushPickupBriefingStory(contract = {}, passenger = {}, sourceStory = '') {
    const frame = (contract?.storyFrame && typeof contract.storyFrame === 'object') ? contract.storyFrame : {};
    const pax = (passenger && typeof passenger === 'object') ? passenger : {};
    const pickupStory = (pax.pickupStory && typeof pax.pickupStory === 'object') ? pax.pickupStory : {};
    const targetName = String(contract?.target?.name || contract?.route?.targetName || 'dem Zielstrip').trim() || 'dem Zielstrip';
    const homeName = _missionPipelineV4ContractHomeName(contract, 'dem Heimatplatz');
    const name = String(pickupStory.personName || pax.name || 'Der Pickup-Gast').replace(/\s*\([^)]*\)\s*$/, '').trim() || 'Der Pickup-Gast';
    const role = String(pickupStory.role || pax.role || 'Pickup-Gast').trim();
    const gender = String(pax.gender || '').toLowerCase();
    const pronoun = gender === 'female' ? 'sie' : (gender === 'male' ? 'ihn' : name);
    const where = _missionPipelineV4BushPickupDisplayText(sanitizeBushPickupBriefingWhere(pickupStory.exactWhere, `am Treffpunkt am Striprand bei ${targetName}`));
    const candidateDefaults = _missionPipelineV4BushPickupCandidateNarrativeDefaults(
        { targetLabel: targetName },
        { focusLock: { taskDomain: 'bush_pickup_return', primarySubjectLabel: targetName } },
        {},
        { pickupCreativeBrief: contract?.pickupCreativeBrief || null, homeName }
    );
    const whyFallback = String(candidateDefaults?.incidentContext || frame.incidentContext || frame.subjectDetail || sourceStory || `${name} hat die Arbeit draußen abgeschlossen und wartet auf den Rückflug.`).trim();
    const backFallback = String(candidateDefaults?.whyNow || frame.whyNow || frame.soughtOutcome || frame.completionSignal || `Zurück in ${homeName} werden Ergebnisse, Notizen und Ausrüstung übergeben.`).trim();
    const why = _missionPipelineV4BushPickupDisplayText(_missionPipelineV4BushPickupNeutralField(pickupStory.whyThere, whyFallback));
    const back = _missionPipelineV4BushPickupReturnSentence(
        _missionPipelineV4BushPickupNeutralField(pickupStory.returnReason, backFallback, { rejectFragments: false }),
        homeName
    );
    const roleLine = role ? `${name}, ${role}, wartet heute ${where}.` : `${name} wartet heute ${where}.`;
    const pickupLine = `Flieg leer von ${homeName} nach ${targetName}, setz die Maschine sauber am Strip ab und nimm ${pronoun} am Wartepunkt auf.`;
    const returnLine = `Bring ${pronoun} anschließend zurück nach ${homeName}. ${back}`;
    return [roleLine, why, pickupLine, returnLine].filter(Boolean).join(' ');
}

function _missionPipelineV4CleanSarHeliBriefingInput(text = '') {
    return String(text || '')
        .replace(/\bN\/A\b/gi, '')
        .replace(/\s+/g, ' ')
        .replace(/^(Lagebild|Evac-Hinweis|Erwartete Hinweise)\s*:\s*/i, '')
        .trim();
}

function _missionPipelineV4SarHeliContextSentence(text = '', targetName = '') {
    const parts = _missionPipelineV4SentenceParts(_missionPipelineV4CleanSarHeliBriefingInput(text));
    const clean = _missionPipelineV4CleanSarHeliBriefingInput(parts[0] || text);
    if (!clean) return '';
    if (/^zuletzt\s+/i.test(clean)) {
        let rest = clean
            .replace(/^zuletzt\s+/i, '')
            .replace(/\s+gemeldet.*$/i, '')
            .replace(/\s+gesichtet.*$/i, '')
            .trim();
        rest = rest
            .replace(/^im Bereich\b/i, 'in den Bereich')
            .replace(/^am Bereich\b/i, 'an den Bereich');
        return `Die letzte belastbare Meldung führt ${rest || `in den Bereich ${targetName}`}; seitdem fehlt der direkte Kontakt.`;
    }
    if (/^der letzte\s+(funkkontakt|kontakt|sichtkontakt|blickkontakt)\b/i.test(clean)) {
        return _missionPipelineV4EnsureSentence(clean.replace(/^Der letzte/i, 'Der letzte belastbare'));
    }
    return _missionPipelineV4EnsureSentence(clean);
}

function _missionPipelineV4SarHeliScenarioSentence(text = '') {
    const clean = _missionPipelineV4CleanSarHeliBriefingInput(text);
    if (!clean) return '';
    if (/^nach aktuellem bild\b/i.test(clean)) return _missionPipelineV4EnsureSentence(clean);
    return _missionPipelineV4EnsureSentence(`Nach aktuellem Bild ${_missionPipelineV4LowerFirst(clean)}`);
}

function _missionPipelineV4SarHeliClues(contract = {}) {
    const frame = (contract?.storyFrame && typeof contract.storyFrame === 'object') ? contract.storyFrame : {};
    const plan = contract?.missionPlan?.plan || contract?.plan || {};
    const scene = contract?.sceneIntent || plan.sceneIntent || {};
    const visibleIdeas = [
        ...(Array.isArray(frame.visibleClueCandidates) ? frame.visibleClueCandidates : []),
        ...(Array.isArray(scene.visibleIdeas) ? scene.visibleIdeas : []),
        ...(Array.isArray(scene.visible) ? scene.visible : [])
    ].map(_missionPipelineV4CleanSarHeliBriefingInput).filter(Boolean);
    return Array.from(new Set(visibleIdeas)).slice(0, 3);
}

function _missionPipelineV4ComposeSarHeliStory(contract = {}, sourceStory = '') {
    const frame = (contract?.storyFrame && typeof contract.storyFrame === 'object') ? contract.storyFrame : {};
    const targetName = String(contract?.target?.name || contract?.route?.targetName || 'dem Einsatzgebiet').trim() || 'dem Einsatzgebiet';
    const sarHeli = contract?.sarHeli || {};
    const hospitalName = String(sarHeli?.hospitalRef?.name || sarHeli?.hospitalRef?.icao || 'dem medizinischen Handoff').trim();
    const subject = _missionPipelineV4SarHeliSubjectLabel(frame);
    const lastSeenSentence = _missionPipelineV4SarHeliContextSentence(frame.lastSeenContext || frame.incidentContext || sourceStory, targetName);
    const scenarioSentence = _missionPipelineV4SarHeliScenarioSentence(frame.probableScenario || '');
    const whyNow = _missionPipelineV4CleanSarHeliBriefingInput(frame.whyNow || frame.stakes || '');
    const sought = _missionPipelineV4CleanSarHeliBriefingInput(frame.soughtOutcome || frame.keyQuestion || '');
    const clues = _missionPipelineV4SarHeliClues(contract);
    const sentences = [];
    _missionPipelineV4PushUniqueSentence(
        sentences,
        `Im Bereich ${targetName} läuft eine SAR-Heli-Bergung für ${subject}.`
    );
    if (lastSeenSentence) _missionPipelineV4PushUniqueSentence(sentences, lastSeenSentence, 4);
    if (scenarioSentence) _missionPipelineV4PushUniqueSentence(sentences, scenarioSentence, 4);
    const decisionText = sought || 'den genauen Fundort und die sicherste Bergungsseite';
    const nowText = whyNow || 'die Bodenteams brauchen vor dem Einstieg ins Gelände eine klare Luftentscheidung';
    _missionPipelineV4PushUniqueSentence(
        sentences,
        `${_missionPipelineV4StripSentenceEnd(nowText)}; für sie zählt jetzt ${_missionPipelineV4LowerFirst(decisionText)}.`
    );
    const clueText = clues.length
        ? `Aus dem Cockpit achten wir besonders auf ${_missionPipelineV4JoinNaturalList(clues)}, bevor wir die Aufnahme an der Fundstelle freigeben.`
        : 'Nach der Fundbestätigung folgt eine ruhige Aufnahme an der Fundstelle, ohne zum Startplatz zurückzukehren.';
    _missionPipelineV4PushUniqueSentence(sentences, clueText);
    _missionPipelineV4PushUniqueSentence(
        sentences,
        `Nach der Aufnahme geht der Flug direkt zum medizinischen Handoff ${hospitalName}.`
    );
    return sentences.filter(Boolean).slice(0, 5).join(' ');
}

function missionSarHeliBuildBriefingNarrative(missionData = null, sourceStory = '') {
    const md = (missionData && typeof missionData === 'object')
        ? missionData
        : ((typeof currentMissionData !== 'undefined' && currentMissionData) ? currentMissionData : null);
    if (!md || !missionIsSarHeliMission(md)) return String(sourceStory || '').trim();
    const baseContract = md.missionContractV4
        || md.missionPlanV4
        || md._missionPlanV4
        || md.missionContract?.missionContractV4
        || window.activeMissionContract?.missionContractV4
        || md.missionContract
        || {};
    const plan = md.missionPlanV2?.plan || md._missionPlanV2?.plan || baseContract?.missionPlan?.plan || {};
    const contract = {
        ...baseContract,
        target: {
            ...(baseContract.target || {}),
            name: md.poiName || md.targetName || baseContract?.target?.name || baseContract?.route?.targetName || ''
        },
        profile: {
            ...(baseContract.profile || {}),
            taskDomain: baseContract?.profile?.taskDomain || md.passenger?.taskDomain || 'search_and_rescue'
        },
        storyFrame: baseContract.storyFrame || plan.storyFrame || {},
        sarHeli: md.sarHeli || baseContract.sarHeli || null,
        sceneIntent: md.sceneIntent || baseContract.sceneIntent || plan.sceneIntent || null
    };
    return _missionPipelineV4ComposeSarHeliStory(contract, sourceStory);
}
window.missionSarHeliBuildBriefingNarrative = missionSarHeliBuildBriefingNarrative;

function _missionPipelineV4BuildGreetingFallback(passenger = {}, contract = {}, storyText = '') {
    const pax = (passenger && typeof passenger === 'object') ? passenger : {};
    const frame = (contract?.storyFrame && typeof contract.storyFrame === 'object') ? contract.storyFrame : {};
    const targetName = String(contract?.target?.name || 'dem Ziel').trim() || 'dem Ziel';
    const taskDomain = String(contract?.profile?.taskDomain || pax.taskDomain || 'general').trim().toLowerCase();
    const opener = (() => {
        const g = String(pax.greetingText || '').trim();
        const match = g.match(/^(hi|hallo|moin|morgen|servus|sali)\b/i);
        return match ? match[0] : 'Hi';
    })();
    const subject = String(frame.subjectDetail || frame.focusSubject || targetName).trim();
    const outcome = String(frame.soughtOutcome || frame.keyQuestion || '').trim();
    const incident = String(frame.incidentContext || frame.trigger || '').trim();
    if (taskDomain === 'search_and_rescue') {
        return `${opener}, wir suchen heute nach ${subject} rund um ${targetName}; ich brauche von dir einen ruhigen Suchflug, damit wir ${outcome ? outcome.toLowerCase() : 'den entscheidenden Hinweis aus der Luft finden'}.`;
    }
    if (taskDomain === 'inspection_infra') {
        return `${opener}, wir prüfen heute ${subject} an ${targetName}; flieg bitte stabil, damit wir ${outcome ? outcome.toLowerCase() : 'den Verdachtsbereich sauber eingrenzen'}.`;
    }
    if (taskDomain === 'bush_pickup_return') {
        return `${opener}, ich war bei ${targetName} draussen wegen ${subject}; bring mich bitte zurück, damit ${outcome ? outcome.toLowerCase() : 'die Unterlagen und Ausrüstung wieder in der Basis ankommen'}.`;
    }
    if (taskDomain === 'charter' || taskDomain === 'club_utility') {
        return `${opener}, heute geht es wegen ${subject} nach ${targetName}; wichtig ist, dass wir ${outcome ? outcome.toLowerCase() : 'den Termin oder die Uebergabe am Ziel sauber erreichen'}.`;
    }
    if (taskDomain === 'news_coverage') {
        return `${opener}, ich brauche heute zu ${targetName} einen klaren Aufhaenger aus der Luft, damit ${outcome ? outcome.toLowerCase() : 'die Redaktion etwas Belastbares bekommt'}.`;
    }
    if (taskDomain === 'media_photo') {
        return `${opener}, ich brauche heute zu ${targetName} eine verwertbare Bildserie, damit ${outcome ? outcome.toLowerCase() : 'Auftraggeber oder Redaktion ein klares Einstiegsmotiv bekommen'}.`;
    }
    if (taskDomain === 'historian_guided_tour') {
        return `${opener}, ich ordne heute ${targetName} historisch ein; bitte ruhig fliegen, damit ${outcome ? outcome.toLowerCase() : 'Ort, Wege und Landschaft zusammen lesbar werden'}.`;
    }
    if (taskDomain === 'science_bio') {
        return `${opener}, ich begleite heute die biologische Beobachtung bei ${targetName}; bitte ruhig fliegen, damit ${outcome ? outcome.toLowerCase() : 'Habitat, Vegetation und Randzonen fuer die Feldnotizen lesbar bleiben'}.`;
    }
    if (taskDomain === 'science_geo') {
        return `${opener}, ich begleite heute die geologische Beobachtung bei ${targetName}; bitte ruhig fliegen, damit ${outcome ? outcome.toLowerCase() : 'Relief, Kanten und Gelaendeformen sauber einzuordnen sind'}.`;
    }
    if (taskDomain === 'sightseeing_tour') {
        return `${opener}, heute geht es nur um den Blick auf ${targetName}; bitte ruhig und weich, damit wir Aussicht und ein paar Erinnerungsfotos geniessen koennen.`;
    }
    if (taskDomain === 'cargo_fragile' || taskDomain === 'medical_transfer' || taskDomain === 'animal_transport') {
        return `${opener}, dieser Flug ist heute fuer ${subject} angesetzt; bitte ruhig und sauber, damit ${outcome ? outcome.toLowerCase() : 'die Uebergabe am Ziel ohne Zusatzstress klappt'}.`;
    }
    const generic = String(incident || `heute geht es fuer uns nach ${targetName}`).trim().replace(/[.!?]+$/,'');
    const normalized = generic ? generic.charAt(0).toLowerCase() + generic.slice(1) : `heute geht es fuer uns nach ${targetName}`;
    return `${opener}, ${normalized}.`;
}

function _missionPipelineV4FinalizeGreeting(passenger = {}, contract = {}, storyText = '') {
    const pax = (passenger && typeof passenger === 'object') ? { ...passenger } : {};
    const current = String(pax.greetingText || '').trim();
    const taskDomain = String(contract?.profile?.taskDomain || pax.taskDomain || '').trim().toLowerCase();
    const genericGreeting = !current
        || /^hi,\s*(wir arbeiten heute nach suchmuster und klaren calls|bitte ruhig fliegen|danke fuers fliegen heute|heute ist ein klassischer|wir machen heute)/i.test(normalizeMissionText(current))
        || current.length < 55;
    const storyCovered = _missionPipelineV4StoryFieldCovered(current, contract?.storyFrame?.subjectDetail || '', 1)
        || _missionPipelineV4StoryFieldCovered(current, contract?.storyFrame?.soughtOutcome || '', 1);
    if (!genericGreeting && storyCovered) return pax;
    if (!taskDomain) return pax;
    pax.greetingText = _missionPipelineV4BuildGreetingFallback(pax, contract, storyText);
    return pax;
}

function _missionPipelineV4FinalizeStory(story = '', contract = {}, context = {}) {
    const raw = String(story || '').trim();
    const frame = (contract?.storyFrame && typeof contract.storyFrame === 'object') ? contract.storyFrame : {};
    const taskDomain = String(contract?.profile?.taskDomain || '').trim().toLowerCase();
    const passenger = (context?.passenger && typeof context.passenger === 'object') ? context.passenger : {};
    const roleProfile = String(contract?.profile?.roleProfile || passenger?.roleProfile || '').trim().toLowerCase();
    const profileId = String(contract?.profile?.id || '').trim().toLowerCase();
    const isBushPickupReturn = taskDomain === 'bush_pickup_return'
        || roleProfile === 'bush_pickup_guest_v1'
        || profileId === 'bush_pickup_strip';
    if (contract?.sarHeli?.enabled && taskDomain === 'search_and_rescue') {
        const sarHeliStory = _missionPipelineV4ComposeSarHeliStory(contract, raw);
        if (sarHeliStory) return sarHeliStory;
    }
    const rawLooksBad = !raw
        || _missionPipelineV4LooksEnglish(raw)
        || _missionPipelineV4LooksInternalMissionText(raw)
        || _missionPipelineV4LooksFragmentedStory(raw)
        || (isBushPickupReturn && _missionPipelineV4LooksBushPickupFragmentText(raw));
    const fallbackStory = () => isBushPickupReturn
        ? _missionPipelineV4EnsureBushPickupConditions(_missionPipelineV4ComposeBushPickupBriefingStory(contract, passenger, raw), contract)
        : _missionPipelineV4ComposeStoryFallback(contract);
    if (isBushPickupReturn && (rawLooksBad || _missionPipelineV4BushPickupBriefingLooksPaxPerspective(raw))) return fallbackStory();
    if (rawLooksBad) return fallbackStory();
    if (taskDomain === 'search_and_rescue' && (
        _missionPipelineV4SarTextConflictsIncidentType(raw, frame.incidentType)
        || _missionPipelineV4SarTextConflictsIncidentFamily(raw, frame.incidentType)
        || _missionPipelineV4SarTextLooksUndecided(raw)
    )) {
        return _missionPipelineV4ComposeStoryFallback(contract);
    }
    const covered = [
        _missionPipelineV4StoryFieldCovered(raw, frame.subjectDetail, 1),
        _missionPipelineV4StoryFieldCovered(raw, frame.incidentContext, 2),
        _missionPipelineV4StoryFieldCovered(raw, frame.whyNow, 2),
        _missionPipelineV4StoryFieldCovered(raw, frame.soughtOutcome, 2)
    ].filter(Boolean).length;
    const targetName = String(contract?.target?.name || '').trim();
    const repeatedTarget = targetName ? _missionPipelineV4CountNeedle(raw, targetName) : 0;
    const looksFlat = raw.length < 190
        || /(wir machen|wir fliegen|kurze zielarbeit|klar umrissenen, ruhigen auftrag|lagebildaufnahme|zielgebiet .* mit einem klar umrissenen)/i.test(raw)
        || _missionPipelineV4LooksEnumerative(raw)
        || _missionPipelineV4LooksFragmentedStory(raw)
        || repeatedTarget >= 4
        || _missionPipelineV4SentenceCount(raw) < 3;
    if (covered >= 2 && !looksFlat) {
        return isBushPickupReturn ? _missionPipelineV4EnsureBushPickupConditions(raw, contract) : raw;
    }
    return fallbackStory();
}

function sanitizeMissionWriterV4Payload(raw = null, context = {}) {
    const src = (raw && typeof raw === 'object') ? raw : {};
    const contract = context.missionContractV4 || {};
    const plan = contract?.missionPlan?.plan || {};
    const requiredRoleProfile = String(contract?.profile?.roleProfile || plan.roleProfile || 'general_passenger_v1').toLowerCase();
    const requiredTaskDomain = String(contract?.profile?.taskDomain || plan.taskDomain || 'general').toLowerCase();
    const isPOI = !!context.isPOI;
    const sceneIntent = sanitizeMissionSceneIntentSpec(src.sceneIntent || null, {
        isPOI,
        taskDomain: requiredTaskDomain
    });
    if (String(plan.sceneKind || '').toLowerCase() === 'none') {
        sceneIntent.visibleIdeas = [];
        sceneIntent.densityHint = 'none';
        if (!sceneIntent.summary) sceneIntent.summary = 'A-B-Flug ohne Zielszene';
    }
    const passengerRaw = (src.passenger && typeof src.passenger === 'object') ? src.passenger : {};
    let passenger = enforcePoiPassengerAltitudeRule({
        ...passengerRaw,
        roleProfile: requiredRoleProfile,
        taskDomain: requiredTaskDomain
    }, isPOI, context.poiTerrainFt);
    const genderRaw = String(passenger?.gender || '').trim().toLowerCase();
    passenger.gender = genderRaw === 'female' ? 'female' : 'male';
    passenger.roleProfile = requiredRoleProfile;
    passenger.taskDomain = requiredTaskDomain;
    passenger = _missionPipelineV4EnforceBushPickupNameCandidates(passenger, contract).passenger;
    const missionType = normalizeMissionType(context.missionType || contract.mode || '', isPOI);
    const draftTargetScene = sanitizeMissionTargetSceneSpec(null, {
        isPOI,
        taskDomain: requiredTaskDomain,
        targetGeoContext: context.targetGeoContext || null,
        missionPlanV2: context.missionPlanV2 || null
    });
    let finalStory = _missionPipelineV4FinalizeStory(String(src.story || '').trim(), contract, { passenger });
    const nameAligned = _missionPipelineV4EnforceBushPickupNameCandidates(passenger, contract, finalStory);
    passenger = nameAligned.passenger;
    finalStory = nameAligned.story;
    passenger = _missionPipelineV4FinalizeGreeting(passenger, contract, finalStory);
    return {
        t: String(src.title || '').trim(),
        s: finalStory,
        pax: String(src.pax || '').trim(),
        cargo: String(src.cargo || '').trim(),
        passenger,
        sceneIntent,
        targetScene: draftTargetScene,
        sceneCompositionStatus: 'draft',
        targetSceneDebug: {
            source: context.source || 'Mission Writer V4',
            sceneIntentRaw: src.sceneIntent || null,
            sceneIntent,
            aiRaw: null,
            normalized: draftTargetScene,
            pendingComposer: true
        },
        i: '📋',
        cat: String(plan.targetCategory || context.selectedCategory || (isPOI ? 'poi' : 'std')).toLowerCase(),
        missionType,
        sarHeli: contract?.sarHeli || context.sarHeli || null,
        bush: context.bushSpec || null,
        _missionPlanV2: context.missionPlanV2 || null,
        _missionPlanV4: contract || null,
        _source: context.source || 'Mission Writer V4'
    };
}

async function fetchMissionWriterV4(context = {}) {
    const apiKey = String(document.getElementById('apiKeyInput')?.value || '').trim();
    if (!apiKey || !document.getElementById('aiToggle')?.checked) return null;
    const contract = context.missionContractV4 || null;
    if (!contract || String(contract.status || '').toLowerCase() !== 'ready') return null;
    const result = await fetchGeminiJsonWithFallback(
        buildMissionWriterV4Prompt(contract),
        apiKey,
        { promptVersion: 'mission-writer-v4', timeoutMs: 16000 }
    );
    if (!result?.parsed) return null;
    return sanitizeMissionWriterV4Payload(result.parsed, {
        ...context,
        source: `${result.source || 'Gemini'} + V4 Writer`
    });
}
window.fetchMissionWriterV4 = fetchMissionWriterV4;

